/* 令和5年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r05.committeeSessions.push(...[{"id":"r05-20231127-8","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"建設委員会","time":"午前１０時００分～午後 ４時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を128件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出等 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"住宅確保要配慮者入居促進事業のほうなのですけれども、今年度、利用が増えているということで、利用が増えた要因をどのように分析されているのか、伺いたいと思います。それと、第二戸越幹線のほうでは、今回、この工事が遅れた理由ですね、そこのところを伺いたいと思います。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"住宅確保要配慮者入居促進事業ですが、こちら、事業開始が令和３年１１月２９日からということで、昨年度は、まだ事業の周知がいま一つだったというところだと思うのですが、徐々に事業が周知されてきまして、それで今回。現在掘削している場所が細砂層でして、ポンプで圧送する圧送管が締め固まって詰まってしまう、閉塞してしまうという状態が起きておりまして、それにより思ったような進捗が出ていないという状況です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、第二戸越幹線のところで、掘り出した土を圧送する際に詰まってしまうということで、こうしたことは事前に想定することができなかったのかどうかというところを伺いたいと思うのですが、今回、工期が延びてしまって、５億円、さらに予算がかかるということにもなっておりますので、そうするとやはり区民の税金がさらに使われてしまうということになりますので。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"なぜ金額を変更したのかですが、生活保護受給者は生活保護扶助の一つである住宅扶助を受給しており、代理納付も進んでいることから、他の属性の方々に比べると、賃貸人にとって入居を可とするハードルが幾分低いと考えられるため。ただ、現在も少しずつではありますが進んでいる状況でございまして、細砂層を抜ければ進捗が戻ると考えておりますので、改善に向けて対策するとともに、可能な限り早く終われるように努めていきたいと考えております。","voiceIndex":10,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"第二戸越幹線のほうは、しっかりと進めていっていただきたいと思います。住宅改善工事助成も区民が利用できるように補正予算を今回組むべきだったのではないかと思いますが、いかがでしょうか。なぜ補正を組まなかったのか、伺います。","respondent":"竹田住宅課長","answer":"住宅改善工事助成ですが、こちらは毎年当初予算のほうで増額しておりますので、今回、１０月に打切りとなったですが、昨年も１０月でございました。当初予算で対応しておりますので、補正のほうは今回しなかったという結論です。","voiceIndex":13,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"昨年も１０月で受付終了になってしまっているということでは、当初予算として増額しているということですけれども、やはりそれでも足りていないということだと思いますので、そこは補正を組んで利用できるようにしていくということが必要だと思いますが、改めて伺いたいと思います。","respondent":"竹田住宅課長","answer":"事業によって希望の多い・少ないというのは年によって増減がありまして、こちらの事業は２月末までを想定している事業なのですけれども、年度によっては２月末まで執行されている年もありますし、たまたま今年度と昨年度は人気のため早めの終了になったと考えておりますので。","voiceIndex":15,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"年によって増減があるということなので、年度途中で受付終了になってしまったら、その分、補正すればそれで対応できると思いますので、そこはぜひやっていただきたいと。これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"住宅のほうです。区と登録不動産事業者が連携とあるのですが、どんな連携をされていて、不動産事業者の方の役割、それと、１件に対して１００万円ですか、１件に対して補助額１００万円と言っていたと、間違っていたら言ってください。その金額の目的というか、何に使われているのかということ。令和４年・５年というばらつき。その方々のご理解というのはどのような傾向になっているのか、教えてください。","respondent":"竹田住宅課長","answer":"連携ですが、区内に大きな不動産団体が２つありますので、そちらの不動産団体にご協力いただいて、会員の方に周知、そして登録事業者になっていただいているです。","voiceIndex":19,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"別に悪いことではないです。いいことなのですが、やはりこれは住宅施策という形で、しっかり来年度の予算にはとっておかないと、柱をつくっていかないと、また途中で補正、補正、補正。補正で可能なものについてはいいのですけれども、ただ、もうちょっと柱みたいものをつくって、品川区はやるぞという、やりますよ、安心してねというようなメッセージが必要だと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"そういった中で、賃貸人の方には、今後、対象の方がたくさん増えてくる、また、高齢者の方は若い人に比べて長くお住まいになるという傾向がありまして、一つの調査によりますと、平均１３年ぐらい、一つのところにお住まいになるというような調査結果も出ていますので。","voiceIndex":21,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、ぜひ来年度の施策の中には住宅対策というのをしっかり立てて、それなりの金額ですか、予算を立てていただきたいと要望したいと思いますが、後でそのお考えをお聞きします。１点、下流部シールドの件なのですけれども、これ、よく分からないのです。令和６年度に予算はなかったけれども増やしたということで、インフレスライド、いろいろあるとはいえども、この見立てがどうだったのだろうなと。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"福祉のほうも件数が増えていると聞いておりますので、福祉部門とはしっかり連携して、お住まい探しに困る方がないように、区としても連携して取り組んでまいりたいと考えております。金額に関しましては、受注者が決まった段階で、施工方法についてもう少し詳細な検討をしたり、インフレスライドといったものは、当初はなかなか想定できないところもありますので。","voiceIndex":23,"id":"exchange-008"},{"speaker":"田中委員","kind":"提案","question":"これは取水工等の工事の関連が要因で９１日延伸するというものでありましたが、今回はそことは違うシールド工法過程で、土質が当初よりも違うものが出たために、管が詰まり、延長せざるを得ないという状況だったのですけれども、８月１６日に専決処分をした時点で、要は取水工の関連で専決処分せざるを得ない、その時点ではまだ今回の土質の状況というのは分からず。","respondent":"北原河川下水道課長","answer":"今回の閉塞する事態に至りましたのが、最初が８月１７日という形になっておりまして、その後、いろいろな対策をしてきたのですけれども、今回どうしても年度内が難しいということで延伸をさせていただいているものでございまして。","voiceIndex":27,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、この表を見ると、第１四半期だから、６月末までぐらいには完了する見込みだというご判断なのかなと思えるのですけれども、その辺の見通しと、また、工事のそもそもの必要性は、ゲリラ豪雨対策で、被害を起こさないためにも、一日も早く第二戸越幹線が必要だということで工事していただいているわけですが、再び延期されてしまうことに伴う全体の影響度というのはどのように受け止めていらっしゃるのか。","respondent":"北原河川下水道課長","answer":"委員おっしゃいます延長に伴う全体の影響というのはもちろんあると認識していますので、今後、工夫ができないかというところは、検討していかなければいけないと考えているところです。","voiceIndex":29,"id":"exchange-010"},{"speaker":"田中委員","kind":"提案","question":"インフレスライド分だけでいうと、いわゆる変更の場合は、５％以内は専決処分でということでありますけれども、ちょっと詳細が分からないのですが、５億５００万円のうちのインフレスライド分がどれだけなのかということで、それも要は５％を超えるので議決が必要だと捉えて、我々としてはご提案いただいたものに対して捉えるべきなのか、あるいは超えるからなのか。","respondent":"北原河川下水道課長","answer":"今回、補正を行いまして、そしてその後に契約変更、増額の変更を行いますので、その金額が、令和５年の１月１２日に議決している金額に対して５％を超えれば、再度議決が必要になることになりますし、専決処分になった場合も別途ご報告するという形になります。","voiceIndex":31,"id":"exchange-011"},{"speaker":"田中委員","kind":"提案","question":"今回は債務負担行為ということでもあるのですが、令和６年度でのまた、当然、慎重審議を我々はしていかなくてはならないわけですけれども、今後、いろいろ質疑をするに当たりまして、シールド到達に関わるコストとインフレスライドは全く別の観点の予算でありますので、今後はぜひ分けていただいて、議会での質疑がより密度の濃いものになるように、そういうご報告、ご提案をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"住宅確保のほうは、事業概要、資料にもあるとおり、高齢者、障害者、ひとり親世帯、それから先ほどありましたように生活保護の方もその対象ということで、令和４年度と令和５年度、１０月までになりますが、それぞれ対象者の件数を確認させていただきたいと思います。それから、シールドのほうは、今、田中委員から詳細な質疑がありましたので、大体これまでの流れの中で承知をいたしました。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"入居促進事業の属性別の内訳ですが、令和４年度の高齢者が５８、令和５年度が５７、それからひとり親世帯が、令和４年度は１、今年度も１、それから障害者が、昨年度が２、今年度が２、低所得者は、昨年度が８０で。シールドが大体９６０ｍぐらいあるのですけれども、そのうち６００ｍを超えたぐらいのところでこういった現象になってあります。今、少しずつ改善されてきてはおりますが、どこまで続くかというのは、分からない状況にあります。","voiceIndex":35,"id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"これは、実働の店舗数・事業所がまだ少ないのだろうなというのをご相談いただいている中で感じているところですので、なぜ今からご答弁いただくような店舗数にとどまっているのか、また、今後ご協力いただく事業所・店舗数を増やすにはどのようにしたらいいのか、また、店舗数がもし増えるという、今後そのような努力の成果が表れるとしたら、先ほど西本委員のお話にもありましたけれども。","respondent":"竹田住宅課長、北原河川下水道課長","answer":"そういったところで登録数に比べて少し少なくなっているですが、今後増やす方策としましては、今、各店舗の入り口等に貼っていただくステッカーを制作しておりまして、図案のほう、どれでいくかというところで最終的な検討をしています。西品川一丁目の大崎ガーデンタワーの前の付近になります。","voiceIndex":38,"id":"exchange-014"},{"speaker":"まつざわ副委員長","kind":"質問","question":"当事者と不動産屋だけが知っていても、やはり大家がこの事業を理解していないと、なかなか物事というのは進まないと思っていて、例えばこういった予算は、これは現在は賃貸人とあっ旋を行った不動産屋に協力金を支払うという形ですけれども、例えば大家への周知という部分に、何といえばいいのですかね、もっと広報に努めるというか、そういった予算分というのはこれには入っていないのか。","respondent":"竹田住宅課長","answer":"ただ一方で、大家の意思決定に大きな影響を及ぼしているのは、建物の管理を請け負っている不動産事業者というところもありますので、当面は不動産事業者のほうに積極的に働きかけ等を行いまして、不動産事業者を通じて大家にもご理解いただくというような形を。","voiceIndex":42,"id":"exchange-015"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"は不動産業者で、例えばチラシなんかをつくって、そこが大家に理解できるようなことが区で後押しできればいいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-016"}]},{"id":"topic-02","title":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","agenda":"令和５年請願第１６号、リニア新幹線の建設中止を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、このリニア新幹線、２度目の工事停止という状況ですけれども、７月の時点で、現在と同じ１２４ｍ掘り進んだところで止まっているという状況です。それと、この間、同様の大深度地下工事で陥没事故が起きた調布市の外環道の問題を把握すべきだということで言ってきましたけれども、それは把握されたのかどうか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"１点目の今回の停止の理由ですが、公表されていますとおり、曲線区間での掘進が続く中で、一部に局所的に土がたまってしまいまして、その大きな圧力がスキンプレートを押し、変形させたものと認識しております。","voiceIndex":58,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"工事のマシンが壊れてしまったというところでは、点検した際に見つかったということで、もしこれ、点検しなかったら、このまま進んでいたとしたら、どういった事態になってしまったのかと思うのですけれども、区でそうしたところ、想定しているところがあれば、伺いたいと思います。そうした補修をやるために住民が立ち退かされているという状況ですので、補修工事の内容をご説明いただければと思います。","respondent":"大石まちづくり立体化担当課長","answer":"今回７ｃｍ程度のへこみが発見されたですので、点検は予定どおり行ったのかなと考えています。","voiceIndex":60,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"調査掘進の間もあるかな。区はほかのところで起こっていることも把握されているかどうか、伺いたいと思います。ほかにも広島ですとか様々なところで起こっていて、振動やら騒音やら、生活がままならないということが起こっておりますので、品川でもそうしたことが起きてしまうのではないかと危惧されますけれども、いかがでしょうか。","respondent":"大石まちづくり立体化担当課長","answer":"ご質問の１点目ですが、今回のシールドが住宅街に出ていってしまったら、地上への影響があるのではないかですが、区といたしましては、そのような事象にならないように、ＪＲ東海に対して引き続き安全対策を求めているものです。","voiceIndex":62,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"今、外環道のところでも、陥没や空洞が発生した後もトンネル工事などを進める中で、川の沿岸で新たに地面がへこんだりとか小さな陥没が起こっているという状況ですので、さらに地盤が壊されているということになって、今補修をしている住民の方だけでなく、ほかの住民の方も暮らしに不安を抱えているということになってしまいますので、やはりこれは中止すべきだと思いますけれども。","respondent":"大石まちづくり立体化担当課長","answer":"中止することを求めるですが、区といたしましては、リニア中央新幹線は３大都市圏の大動脈輸送を二重系化し、こちら、ＪＲ東海が国土交通大臣から認可を受けているものですので、ＪＲ東海の責任の下に実施されている事業であることから、区は引き続き必要な安全対策を確実に行い。","voiceIndex":64,"id":"exchange-020"},{"speaker":"のだて委員","kind":"質問","question":"なので、やはり中止すべきだということだと思います。そして、そのために、朝の時間帯は通学時間、通勤時間でもあると思いますので、そうしたところで７時半から８時半までは運行を停止するということですが、夕方の下校時など、そうしたところは停止しない理由を区のほうでは聞いているのか、伺いたいと思います。そして、工事車両が６００台通行することで、道路の状況に悪影響はあるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"説明会の中で２４時間の施工を行っていくということは近隣住民の皆様にも周知しておりまして、その中で、２点目の質問になりますが、朝の７時半から８時半というのは、登校時間ということもありまして、運搬はしないというところになってあります。","voiceIndex":66,"id":"exchange-021"},{"speaker":"のだて委員","kind":"質問","question":"事業者のほうで工事車両が１時間当たりどれだけ出るのか説明しているという話でしたが、当初の工事説明会では１時間当たりというのは出ておりませんので、住民の方はあまりイメージできないのかなと思いますので、そうしたところも区として把握をしていただいて、やはり道路の状況にも影響は出るということですので、実際に請願では。","respondent":"大石まちづくり立体化担当課長","answer":"交通に影響が出ることに対しての区の認識ですが、先ほども申したとおり、区といたしましては、ＪＲ東海のほうは、しっかりと影響が出ないように、どういった形で出していくかというのは検討されていると思いますし。","voiceIndex":68,"id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区としても住民説明会を求めていただきたいと。やはりこの工事、２回もストップしているという中で、住民にはそれが直接は一度も説明されたことがないという状況ですから、ぜひ区としてもそれについて説明会を求めていただきたいと思いますが、いかがでしょうか。そうした姿勢でいいのかと思うのです。区としてもそうした対応でよいと考えているのか、これが丁寧な説明と言えるのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"区としてそのような対応でいいのかというご質問もありましたが、説明会の開催というのは当然事業者が最終的に判断するものでございまして、区といたしましては、そういった説明をして区民の不安払拭を果たすことが本来の目的ですので、説明会の開催ということにとらわれずに。","voiceIndex":70,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"不安を払拭することが重要なのだと。それはそのとおりで、心配な人がかけてくるだけで各計画地の方の不安が払拭されると、そう考えているのか、伺います。資料の中にも、必要の都度、お知らせをしているということで言われておりますけれども、その必要の都度とはどういうときなのか、伺います。","respondent":"大石まちづくり立体化担当課長","answer":"２点ご質問いただきました。不安払拭につながるのかというお話ですが、先ほども申したとおり、質疑を受けることに対して、会を開くまたは個別で対応するというところが本来の目的ではないと私たちは思ってあります。","voiceIndex":72,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、必要の都度というのは、進捗状況ですとか、工事をストップした場合も当たるのかどうか、そういう理解でいいのか、実際に今回お知らせをしているのか、伺いたいと思います。それで、不安払拭に向けて誠意を持って対応するよう求めているということなのですけれども、この間、工事が止まったりしているときに、実際に問い合わせても、まともな回答がないというのが実態なのです。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点、まともな回答がないというのが実態だというお話があったのですけれども、区といたしましては、そのようなことが実際に起きているかどうかというのは認識していないのですが、そのようなことがないように、ＪＲ東海にはしっかりと丁寧に取り組むよう。","voiceIndex":74,"id":"exchange-025"},{"speaker":"のだて委員","kind":"意見","question":"今回の工事が止まったことは配布していないということで、必要の都度、チラシを配ったり、住民の方にお知らせされていないなと思いますので、やはり説明会を実施すべきだと意見を述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"見ましたけれども、本当に分かりづらいです。どこを見ればいいのかというのが分からない。これはＪＲ東海の話ですから、区はそれを代弁しているということに過ぎないので強く言えないのですけれども、だけど、区としては、ＪＲ東海の周知方法が果たして区民の皆様方にどれだけ周知徹底されているのかというのは、やはり疑問を呈してほしいなと思うのですが、その辺の周知徹底についての認識を教えてください。","respondent":"大石まちづくり立体化担当課長","answer":"もう１点、ＪＲ東海のホームページが分かりづらいというお話でございましたが、区といたしましては、最終的には事業者の判断になろうかと思うのですけれども、しっかりと住民の皆様が検索しやすいようなやり方ですとか、すぐアクセスできるようなやり方というのは。","voiceIndex":78,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"周知徹底のところでは、ぜひ言っていただきたい。皆さんもぜひ見てください。分からないですよ。検索の仕方が悪いよと言われればそれまでなのですが、区民の方々が分かるようにという工夫はやはり努力すべきだと思うのです。結果はどうであれ、しっかり分かるようにしてくれという要望はやっていただきたいと思います。その辺のご意見をお聞きします。","respondent":"大石まちづくり立体化担当課長","answer":"陥没等々発生した場合にも同様の場所での周知なのかというお話でございましたが、先ほど申しましたのは、例えば調査掘進の再開であったり、そういった事象が発生したときに周知する範囲ですので、重大な事故だとか、そういった事象が発生した場合は。","voiceIndex":80,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"こういう問題が起きるかもしれないというようなのがあるかもしれないので、そこはしっかり聞いていただいて、説明する場所のエリアというのが本当に今の状況でいいのかどうかという判断は、やはり品川区のほうで持っていただきたいなと思います。なので、それは今回の請願が出たということをきっかけに、ぜひＪＲ東海には申し入れをしていただきたいと、意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"結論を出すでお願いします。不採択でお願いします。説明会のお話もありました。先ほど西本委員が言われましたホームページの見づらさというのは確かに十分配慮しなければいけない部分があると思いますので、引き続きＪＲ東海へは、さらなるそういった周知の徹底というか、もっと見やすさを求めるということは続けていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。いずれにしても、区民の生活を脅かすような、そういう工事はしてはならない。あくまでも安全第一で、そして地元の方々、区民の方々に丁寧な説明をしていただくように、区のほうでも取り計らっていただきたいと求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-031"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。リニア新幹線はそもそも様々な問題があり、必要ないと思いますが、シールドマシンのトンネル工事が何度もストップしています。建設を中止すべきです。説明会についても、二度も工事が止まっているということを含めて、住民に説明すべきですし、今回の工事ストップのこともチラシを配布していないということ、そして丁寧な説明もされていないと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"本日結論を出す、不採択でお願いします。請願項目の２番は、住民説明はこれでも足りないぐらいだと私は思っておりますので、お気持ちは私も非常に共感するところがあります。ただ、１番目のところは、建設中止というふうには今の状況としては言い難いなということで、本日は不採択ということにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"前回も同様の方から陳情が出されたとの説明がありました。現場を視察してほしいということで、１月下旬に現場視察の方向だということです。ぜひそこに森澤区長も参加していただけるように進めていっていただきたいと思いますが、いかがでしょうか。新たな意見が出ているという書きぶりかなと思ったのですけれども、こうした意見が出ていることを区はどのように捉えているのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"区長の参加ですが、まずは事務分掌にのっとって、都市開発課のほうで対応していきたいと考えています。勉強会の幹事役の方からのご意見ですが、コロナ禍がありまして、コロナが明けて、こういった形で客足が戻ってきたと。","voiceIndex":97,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"Ｃ地区のあるところは、東小路もあって、昔ながらの飲み屋街があるというところで、そうしたところが有名というか歴史的なところにもなっているということで、テレビなどでも紹介されますけれども、こうした東小路の歴史的・文化的価値を区はどのように考えているのか、伺います。","respondent":"中道都市開発課長","answer":"ですので、今はコロナが明けたばかりというところで、ご商売のほう、非常に忙しくされているということは聞いております。一方で、安全というところの今後の権利者の方々の認識というものを、区としては注視していきたいと考えております。","voiceIndex":99,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"東小路の価値ですね、そこを伺ったので、そこは特に認識がないということなのか、ご答弁いただければと思います。そうした中で再開発が進められようとしてきたわけですけれども、再開発でないと安全なまちづくりはできないということなのか、伺います。この間、繰り返し出されていますけれども、そうした必要な暮らしを奪うものだという自覚があるのかどうか、伺います。","respondent":"中道都市開発課長","answer":"再開発ですが、まずは地域の方々が今後どのようにまちづくりをしていきたいのか、いくのかというところを話し合っていただくことが非常に重要と考えています。","voiceIndex":101,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"まちの方々に話してほしいということなのですが、そうした中で、こうした再開発を永久に中止してほしいという声が出てきているということだと思います。この再開発によって暮らしが奪われてしまうということを品川区は認識しているのか、伺います。","respondent":"中道都市開発課長","answer":"再開発によって住み続けられなくなるですが、そこに住んでいる方々、権利を持っている方々につきましては、再開発事業というのは、その権利を今後の再開発が終わった後も維持することができますので、その中で、新しい建物の中で住み続けていただければと考えています。","voiceIndex":103,"id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"るる説明がありましたけれども、再開発というのが権利は残せるというお話でしたが、再開発が進んでいけば、住み続けたいと願っても強制的に所有権を奪われてしまうものだということを区は認識していると思いますが、そこを伺いたいと思います。","respondent":"中道都市開発課長","answer":"所有権を奪われてしまうというところなのですけれども、従前に権利を持っている方々というのは、権利変換の中で、従後も権利を持つことは可能という認識です。","voiceIndex":105,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"従後も権利を持つことはできるというお話ですが、それまでには１回権利を奪われると。実際には権利といいますか、所有権を奪われるということになります。その後、実際住み続けられるかといえば、住み続けられない、借家の方は特に皆さん出ていってしまうということになってしまいます。こうした再開発はやるべきではない、私も中止すべきだと思いますけれども、改めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"借家人の方々につきましても、家賃の部分につきましては、オーナーの方々とのお話合いの中で従後というのは決まってくるという認識ですが、当該地、一丁目一番地、そこに住み続けたいということではないかもしれませんけれども、周辺の地区に住み続けられるように。","voiceIndex":107,"id":"exchange-039"},{"speaker":"のだて委員","kind":"意見","question":"やはりその場に住み続けることはできないということですので、Ｃ地区での再開発はやめるべきだと述べておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-040"},{"speaker":"西本委員","kind":"質問","question":"このＣ地区に関しては、一応エリアというのは決まっているのですけれども、この中で分割的に考えることというのは可能なのでしょうか。ここはやはり一体的に考えなくてはいけないものなのか。そうなってくると、安全というひとくくりでもくくれないし、いろいろな思いがあるので、ここは分割していろいろと開発を進めるという制度はないのでしょうか。そこをお聞きします。","respondent":"中道都市開発課長","answer":"区がここの地域を指定したというところではございません。ですので、地域の方々がこれを拡大するのか縮小するのか、そういったところは今後の話合いを継続した中で、またさらに練られていくのかなと考えています。","voiceIndex":111,"id":"exchange-041"},{"speaker":"西本委員","kind":"提案","question":"まだ自由度があるということですよね。だけど、あのままはいかないよねと。火事もありましたしね。ただ、従来型だと補助金の問題があって、恐らく商店街振興、ここは所管ではないのではっきり分からないかもしれませんけれども、そういうものとの組合せという形で、提案できないものなのか、そういう仕組みがつくれないものなのかと思っているのですが、何かございませんか。現状を教えてください。","respondent":"中道都市開発課長","answer":"なので、住民の方が仮に縮小したいといって縮小になったときに、では、それで必ずしも市街地再開発事業ができるかというところは、またそこは検討が必要なのかなと考えています。","voiceIndex":113,"id":"exchange-042"},{"speaker":"西本委員","kind":"提案","question":"ごもっともなご答弁といいますか。提案ですよ。こっちで決めるわけではないですよ。なので、品川区としての役割というのはありますけれども、住民主体のというところは分かりますが、住民は制度的なことは分かりませんので、そこをアドバイスしながら、住民の皆さんがもっと広い視野に立ってまちづくりを考えていただけるような、そういう仕組みをぜひ推進していただきたいと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"Ｃ地区におきましては、現在、まちづくりというようなご相談は区のほうには来ていないところです。一方で、地域の方々が都市開発課に来られましたら、そこの部分につきましては丁寧に対応していきたいと考えております。","voiceIndex":115,"id":"exchange-043"},{"speaker":"西本委員","kind":"意見","question":"意見ですが、やはり広い視野に立ってください。再開発という意味合いも変わってきているはずです。ゼネコン型の再開発は、成功しているものばかりではありません。ぜひそういうところを参考にしていただいて、住民ともっと、このＣ地区については夢のあるような、そういう地域にしようよなんていうふうに持っていけたらいいなと強く思いますので、ぜひお願いをして、意見として申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"都市計画の法的には、市街化調整区域のようなところは一定の規制が入るわけですけれども、品川区内は市街化区域ですので、このＣ地区も同様の地域ですので、再開発は永久に中止を求めるということも、法律上、できないと思いますが、確認でご答弁をお願いしたいと思います。永久に中止をすることができるのかどうかということです。","respondent":"中道都市開発課長","answer":"再開発を永久に中止ですが、再開発は、先ほど再開発の意義といったところをご説明しましたけれども、そうした様々議論を経て、再開発に見合う計画をつくっていきますので、区のほうで永久的に中止という決定はできないと。","voiceIndex":119,"id":"exchange-045"},{"speaker":"田中委員","kind":"意見","question":"そういった視点からは、私は地域の方の安全・安心を守るという視点からは、強制的ではありませんけれども、でも、より地域の、まさにここの人権ということもありますように、人権を守る、生命・財産を守るという視点からのまちづくりは当然必要だと思いますので、たまたま９月下旬の火災はそれほどの被害はなかったわけですけれども、木造住宅が密集する地域としては。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-046"},{"speaker":"まつざわ副委員長","kind":"意見","question":"結論を出すでお願いいたします。不採択です。こういった陳情は私もよく建設委員会などでお聞かせいただきますけれども、そもそもまちづくりというのは、お話のとおり、住民同士の話合いというのが本来の在り方であって、行政はサポートする側と私は認識しております。その中で、品川区としては十分な話合いのサポートをしているという私の認識です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-047"},{"speaker":"若林委員","kind":"質問・要望","question":"来年１月に陳情者等と区のほうで現場視察されるということも今予定されているということで、こういうことも１つのきっかけにしながら、まさに将来のＣ地区のまちづくり、どのようなまちにしていくのか、こういうことを地域の方々みんなでお話をして、まだ決まっていない再開発、その方向に行くのか、別の方向に行くのか、まさに地元の方々でお話をしていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住み続けたい住民を追い出すこのＣ地区の再開発は中止すべきですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-049"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。先ほども質疑いたしましたが、行政として永久中止をするということはできないということでありますが、一方で、話合いもまた必要であると考えていますので、そういった視点からも不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"資料について伺いたいのですけれども、今後の予定として、クロス集計、また、自由記述欄の分析を実施するということです。クロス集計では、ルート直下での声ですとか、回答内容を公表するのかというところを伺いたいと思います。そして、１２月をめどに結果を公表予定だということですけれども、ここで公表する中身は、どういった中身になるのか、このときに自由記述欄についても公表されるのか、伺います。","respondent":"辻広報広聴課長","answer":"クロス集計の仕方なのですけれども、フェイスシートということで、その方の年代ですとか地域別のこともアンケートの中に入れておりますので、それを基に、設問ごとに、どの地域で、どういった意見が多いということを集計する予定です。そちらも公表する予定です。","voiceIndex":146,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"ある意味、目的といいますか、そのようなところを伺いたいと思います。クロス集計のところでは、どの地域で、どういう声があるかということを公表するということでしたので、ぜひクロス集計の分析をしたところも公表していっていただきたいと思います。そうすると、１２月にはクロス集計のところまでということでしたので、その後の公表は、どういったスケジュールになるのか、伺います。","respondent":"辻広報広聴課長","answer":"１１月以降のスケジュールですが、テキストマイニングを年内ぐらいまでに一定程度目途を立てられたら、年明けに全体のものを公表していくという、そのような予定になっております。","voiceIndex":148,"id":"exchange-052"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、陳情の中では、こうしたアンケートの経費の内訳を教えてほしいということで求められていますけれども、実際、公費で行われているものですので出していただきたいと思うのですが、予算の事項別明細を見ても、約１億円の委託費ということしか出ておりませんでしたので、ぜひご説明いただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"アンケートに寄せられた声は、区長が国に直接届けるということになるのか、ぜひ届けていただきたいと思いますけれども、いかがでしょうか。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"今度は、回答の受領、後納郵便で戻ってくる分で１,２６１万６,０００円という内訳になっておりますが、全体での流れですので、この中で郵便料金が幾らになるかというのは計算はできないところです。アンケート結果ならびに国への働きかけについてですが、基本的には、国との調整ということになろうかと思いますので、この場で区長が必ず参りますと、なかなか断言はできませんが、これまで、前区長が要望に行った際。","voiceIndex":151,"id":"exchange-054"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ区長にも直接行っていただいて、住民の暮らしを守る立場で、ぜひ国にも求めていただきたいというふうに思います。そうした被害を受けている人たちの意見を大切にしていただきたいというふうに思うのです。やはりそうした被害の下で、区民の安全安心な生活が壊されているということですので、やはりそれも国に伝えていただきたいと思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"羽田新飛行ルート運用開始以降、区民の方からは、区のほうに直接様々な声を寄せていただいているところです。区では、これまでもそうした声を直接国に届けておりました。","voiceIndex":154,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問・要望","question":"国にクロス集計も提出をするということで、ぜひそうした区民の直接の声を届けていただいて、羽田新ルートは、そういうことであれば、ぜひ中止をしていただきたい、そういう立場で求めていただきたいと思いますけれども、いかがでしょうか。そして、自由記述欄については、これは公開をするということでいいのか、そこを確認させていただきたいと思います。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"ただ、膨大な量で、個人情報が含まれているかとか、その辺りの観点のところもしっかり精査をした上でということになりますので、少々お時間をいただくことになるかなとは思っております。ただいま検討しています。アンケート結果の整理を今現在行っているわけですが、そうしたところをしっかり整理分析して、国のほうに区民負担軽減につながる取組をしっかり求めていきたいです。","voiceIndex":156,"id":"exchange-056"},{"speaker":"西本委員","kind":"質問・要望","question":"１つは、分析の方法として、テキストマイニングを使うというふうにおっしゃっていました。デジタル化はもうされているので、分析をする上ではデジタル化をしなければできないので、ですから、そのままできるはずなのです。その上で、区民の人たちの思いというのは、どこまで収集するのかということを確認させてください。区の考え方をまとめなければいけないと思いますが、いかがでしょうか。","respondent":"辻広報広聴課長、鈴木都市計画課長","answer":"１件ずつ確認しないと、それが公開するのに適した内容のものかというか、本当に出して大丈夫なのかというのは、目検で見なければいけないかなというふうに考えておりまして、一定程度の時間をいただくかなというふうに認識しております。行く前の区民への公表ですが、要望書になるのか、どうなのかということは、しっかり今、検討していますが、その内容については、対国に対してまずは行うべきですので、その要望の内容も含めて、実施状況については。","voiceIndex":160,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問・要望","question":"分析方法については、いろいろ検討されていると思いますので、区民の皆さんの気持ちがきちんと伝わるように、そうやって時間もかけずにお願いしたいと思います。やはりそこは、せめて議会で議論をするという場を設けてもらわないと、それを踏まえて、国のほうに申し上げるという形にしていただきたいと思いますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"今回行った区民アンケートの結果に基づいて、それを踏まえて、要望、働きかけを行っているということは繰り返しご答弁させていただいているところですので、何かそのアンケート結果から、先ほど勝手にというお話もありましたが。","voiceIndex":163,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問","question":"これだけのアンケートをとって、皆さんにご足労をかけて、その責任のとり方があるではないですか。その前にしっかりと品川区の中で議論しないと、その結果をどう捉えるかとか、どう考えていくかとか、どういうふうに表現していくのかとか、そういう話合いというのは、やはり議会があるのだから、議会で事前に、国に言う前に、きちんと議論する場が必要なのではないでしょうか、それはいかがですか。","respondent":"鈴木都市計画課長","answer":"正に区民アンケートの結果、区民の声に基づいて働きかけを行っていくですので、そこはしっかり区として検討して、しっかりつくり上げて働きかけを行っていきたいです。","voiceIndex":165,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"押し問答になりますので、強く強く要望したいと思います。１番目は、もう当たり前です。２番目、当たり前です。４番目、当たり前ですよね、これ、詳細を出さないと、みんなの税金を使っているわけですから、詳細に出さなければいけないと思います。この１から４番目までに対して、品川区は、いやいや、そういうことではありませんからやりませんとか、反論があれば、おっしゃってください。","respondent":"鈴木都市計画課長","answer":"委員お尋ねのこの陳情裏面の４点についてですが、１番については、正に今、結果について集計中だです。","voiceIndex":167,"id":"exchange-060"},{"speaker":"西本委員","kind":"質問・要望","question":"この内容は、本当に当たり前だと私は思います。分かりますか。それで、この団体の方々が１軒１軒回っているのです。自分たちで一生懸命気持ちを把握しようということで動いているという動きも考えれば、本当にこれはありがたいなと私は思っていますが、ぜひこれからのアンケートの集計、分析はしっかり考えていただきたいと意見を申し上げて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"それを踏まえて、今回の区民アンケートをこれから集計されて、結果が公表されるわけですけれども、では、その区民アンケートの声と議会サイドからの声が違った場合に、区長としてどちらを重ずるのかなどというような野暮な質問はいたしませんが、今後、区長がアンケート調査をして、その結果を、今も少し議論はありましたけれども、議会サイドに対して、それをどういう形で求めてこようとされているのか。","respondent":"辻広報広聴課長","answer":"今回は、区民アンケートということで、羽田新飛行ルートのことも含め、区民の方の生の声を全員の方に細かくお伺いしようという趣旨で実施したところです。その結果に関しまして、先ほど申し上げましたとおり、きちんと集計をしまして皆様にご報告する。","voiceIndex":171,"id":"exchange-062"},{"speaker":"田中委員","kind":"提案","question":"なので、今回の区民アンケート、区長のお立場としては、しっかり受け止めていただいて、それをどうするかということに関しては、その後の対応については、議会に対してどういうご提案があるのか、報告があるのか、そういったことも踏まえた中での対応は、４０分の１の議員としては対応していこうと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":173,"id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"これから採決になると思うのですけれども、ぜひそれぞれの会派の方々のご意見をしっかりとお聞かせいただきたいと思います。なぜかというと、１から４番、先ほど私は聞きましたけれども、これに対して、どういうところが不備があったのか、どういうところは賛成するのかということをしてあげないと、陳情者の方々にもご理解いただけないと思いますので、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-064"},{"speaker":"まつざわ副委員長","kind":"質問","question":"先ほどお話を聞きましたけれども、１番から４番のお話です。１番に関しては、集計中であって、これからアンケートの結果が出てからでも、そういったことは品川区としても理解しておりますし、２番に関しても、十分に議論を尽くして内容は公平に公表するということであります。３番に関しても、国へこの結果を報告するということもお話を聞いております。４番に関しては、広報広聴課長からも聞きました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-065"},{"speaker":"若林委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。その責任の中で、しっかりと国に対して区民の声を届けるということを最後までしっかりと行っていただきたい。その後のことについては、私たち、また区民も、様々な感想、意見は、それは申し述べる機会もあるのだろうというふうに思っておりますので、そういった意味で、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-066"},{"speaker":"木村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。本当に地域住民の皆さんにとってみれば大変なことでありますけれども、国がやろうとしていること、あらゆることに対して品川区は何ができるのか、それに対してはしっかりとこれから議論をしていくべきだと思っています。現在は不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":179,"id":"exchange-067"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。今回の区民アンケートは、住民の皆さんが住民投票をやってほしいということで署名をしてきた。その中で区長としては、そうではなくて、アンケートをするべきだということでやってきたもので、住民の運動の１つの成果だと私は思っておりますので、アンケートを実施することはいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-068"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、採択でお願いします。不採択の場合にその理由もということで、皆さんにお願いいたしました。今のところは私のあとに田中委員がいらっしゃいますけれども、聞いていますと、この１番から４番のこの４つの項目に関しては、皆さん賛同していると私は見受けられました。そう捉えました。本当は採択という形で認めていただきたいところではありますが、意見として最後に申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-069"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すべきということで、理由は先ほど申し上げましたけれども、区民アンケート調査結果を踏まえた意見は議員として述べるべきではない、取り扱うべきではないという視点から、不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":182,"id":"exchange-070"},{"speaker":"のだて委員","kind":"質問","question":"その下で、今、どんどん進められて、自分のところにも調査が入るのではないかということで不安を感じ、睡眠薬を服用されている。今、組合設立に向けてやっているということですが、令和４年７月に、この２つの再開発、都市計画決定をされたということで、今、１年以上たっているということになりますけれども、予定から進捗が遅れているのではないかと思うのですが、そうした理由を伺いたいと思います。","respondent":"中道都市開発課長","answer":"今まで準備組合が地域の方々に説明なりしておりますけれども、こうした中で権利を持っている方を追い出すといったことは発言はしておりません。その資料も区は確認しておりますので、そうした事実は特にないというふうな区の認識です。２番目の組合の設立などですが……。","voiceIndex":191,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"今、組合設立に向けての検討をしているというところで、実際に進めるかどうかというところも検討されているというご答弁でしたけれども、そうすると、進めない、中止をするということもあり得るのか、そういった検討はされているのかというところを伺いたいと思います。そうしたことがやはり追い出すことになると私は思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"もちろん都市再開発法の中で３分の２以上の同意がなければ、この事業は進まないですが、繰り返しになりますけれども、まちづくりに対してより多くの方の同意をもって進めていきたいというところで、今現在、お話合いまたは検討がされているところです。","voiceIndex":195,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"私は言えないと思いますけれども、そこを伺いたいと思います。先行して行われた２つの地区がありますけれども、この陳情の中では、本移転者ということで書いてあると思うのですが、これが地権者で戻ってきた人ということだと思いますけれども、区は、この人数を把握しているということですけれども、個人情報を理由に公開しないということで、なぜこれが個人情報に当たるのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"都市再開発法の中で手続が行われているものですので、区としましては、そこの部分は法令に遵守して進めていきたいというふうに考えてあります。法律の在り方につきましては、国のほうで議論されるべきものという認識です。","voiceIndex":199,"id":"exchange-073"},{"speaker":"若林委員","kind":"意見","question":"委員長、もう１回。今も傍聴人からの発言がずっと続いております。先ほど、委員長から退場に関するお話もございました。先ほど、私が手を挙げたきっかけは、議会に対して、正に看過できない発言だったと思います。ぜひ、この委員会の質疑が円滑に進みますように、適正な委員長としての職権を発揮していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":202,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"法令に遵守して再開発を進めていますということですけれども、法律なので、それを変更するのは確かに国でやることだと思いますけれども、その運用のところでは、区でも、ある程度できるところがあるのかなという気もしますので、そういったところは努力をしていただきたいと思いますし、そうすると、法律のほうに、この二者択一が、選べる自由がありますよということで書いてあるということなのか。","respondent":"中道都市開発課長","answer":"法令に遵守というところで運用の部分で努力をしていただきたいですが、区といたしましても、３分の２をクリアしたからすぐに事業を認可するというところではなくて、繰り返しになりますけれども。","voiceIndex":206,"id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"今、パルムのほうの地権者の数をご説明いただいたと思うのですけれども、駅前地区のほうも内訳がありましたら伺いたいと思います。その中で商店街が、パルムビジョン２０２２を作成されたということで、この中身、どういった内容が書かれているのか、伺いたいと思います。今後どうなっていくのかということがやはり心配されていると思うのですけれども、区の認識を伺いたいと思います。","respondent":"中道都市開発課長","answer":"再開発の中止という件ですが、まちづくりにつきましては、地域の方々で進められてきているものという認識ですので、区のほうで中止する考えはございません。","voiceIndex":208,"id":"exchange-076"},{"speaker":"のだて委員","kind":"確認","question":"組合とは交流をしているということで、合意されていると、区の認識のようですけれども、やはり正式には確認をされていないということで、やはり知らない人もたくさんいらっしゃるという下で、商店街もそうですし、住民の皆さんもそうですけれども、合意をしないうちにどんどん都市計画決定とか手続が進んでいくということが、やはり再開発の悪い部分。","respondent":"中道都市開発課長","answer":"発案者５名ですが、準備組合を設立する際は、総会を開いて、その中での合議制で準備組合を設立するというところ、または、その中での理事を務める方は地区内の権利者の方です。","voiceIndex":210,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"事務局をＥＬＣ株式会社はしていたということで、そうすると、発案者には入っていないということなのか、そこのところを確認させていただきたいと思います。","respondent":"中道都市開発課長","answer":"一方で、今現在、区は、まちづくりニュースなどを発行して、今現在の状況を、どのようにまちづくりが進んでいるかというのは、過去数年からずっと周知は行っておりますので、よりそういったところで地区の様々な方に周知されるように努力していきたいと考えています。","voiceIndex":212,"id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民の方が住み続けられないということになって、住民合意がない中で進められるからこそ、こうした請願・陳情などが、これは武蔵小山だけではないですけれども、様々出てくるということになっていると思いますので、こうしたまちづくりというのは、やはり住民合意をしっかり徹底していくということがまちづくりの基本だというふうに思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"アーケードがなくなるかもしれないという具体的な話が出てきましたけれども、アーケードはなくなるのですかということと、それから、地権者の中の３分の２が同意すれば再開発は進みますよね。それ以上にということで努力されているという話は分かりました。現時点で、この該当する地権者の方々の合意はどれだけとれているかという把握はされていますか。","respondent":"中道都市開発課長","answer":"アーケードの件につきましては、アーケードは、今現在、商店街が権利を持っているというところで、こういったまちづくりを行っていく中で、やはりアーケードを触っていきますので、そこの今後の取り組み方も、きちんと商店街組合と協議をしながら、今。","voiceIndex":216,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問・要望","question":"あの商店街は、やはりアーケードがあって本当にいいというところでもあるので、そこは地元の方々が意見交換しながら決めていくということだと思いますので、なるべく存続していただきたいなという、これは私の要望です。地権者の方が３分の２以上、本来は１００％賛同していただくというのが希望なのです。３分の２以上の方々が賛同しています。今後の進め方について、相関を教えてください。","respondent":"中道都市開発課長","answer":"すみません、一部修正といいますか、先ほど、３分の２以上の賛同という話をしましたが、やはりお話合いの中で、まちづくりに興味があるとか、そこはきちんと白黒つけている話ではないので、今現在、３分の２以上ありますということ、それをきちんと把握しているかというと。","voiceIndex":218,"id":"exchange-081"},{"speaker":"西本委員","kind":"質問・要望","question":"３分の２、まだはっきりした意思表示は確認されていないというところでありますが、ただ、これはしなければいけないでしょう、もうそろそろ。先ほども言いましたけれども、都計審ではもう決定が出ている部分もあるので、この地域については、建設委員会を含め、いろいろ議論をして、そういう方向性にというふうになっている状況ですから、あとはもう残されるのは何かというと、条件整備だと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-082"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"結論を出すでお願いします。午前中、大井町の話も出ましたけれども、繰り返しになってしまいますが、まちづくりというのは、住民の話合いが、もともとの基本でありまして、今回でも、昨年度４月から都市計画の決定から１年あいている中で、区としては、サポートできる範囲で、より多くの区民の声を聞くために動いているというお話も聞けました。引き続きできる範囲は丁寧にやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-083"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。商店街の合意形成も曖昧ですし、住民を追い出す小山三丁目第１地区、第２地区再開発は中止すべきだと考えますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":225,"id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。課長のこれまでの発言や委員会でのご様子を伺うと、こういうことを言うような方ではないと確信しておりますので、そういった意味でも陳情者の方の何か誤解から生じたものではないかという思いがしますので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、防災について様々書かれておりますけれども、品川区も、これまで不燃領域率が７０％になれば燃え広がらないということでご説明されてきたというふうに思いますけれども、その確認と、実際、この陳情の中で、戸越五丁目、六丁目、西大井六丁目は、不燃領域率が６０％または６５％を超えているところもあるというところで、燃えにくい街並みになってきているというふうに思うのですけれども。","respondent":"小川木密整備推進課長","answer":"今、こちらの陳情書の中にもあります各町目の不燃領域率に関しましては、６０％を超えるものもありますが、まだまだ道半ばというふうには認識しておりますので、７０％を目指して、引き続き建物の不燃化促進等について取り組んでいきたいというふうに考えてあります。","voiceIndex":236,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"そうした下で、やはり交通の円滑化のために住民の暮らしが壊されるということは、あってはならないことではないかというふうに思いますけれども、いかがでしょうか。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"最初のご質問ですが、やはり面的なまちづくりで影響が大きいというご質問等だと思いますが、こちらは、建物の不燃化を促進することで、個々の建物に関しても、燃えない、燃えにくい建物ができるわけですから、そういった意味では。やはり特定整備路線は密集地域、道路が狭い地域で進められているところもありますので、そうした狭い道路への交通流入も防ぐと。","voiceIndex":238,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問","question":"防災の面は、私の質問が悪かったのかもしれませんが、面的にと言ったのは、耐震化、不燃化をどんどん進めていけば、不燃領域率が７０％になって燃え広がらなくなるということで、面的な耐震化、不燃化を進めていくことこそ必要ではないかということで伺いましたので、ご答弁いただければと思います。","respondent":"小川木密整備推進課長、鈴木都市計画課長","answer":"面的なまちづくりの観点からですが、委員おっしゃられるとおり、面的なまちづくりの観点からも、この耐震化、また不燃化の促進は、非常に重要なまちづくりというふうな観点で捉えております。都市計画道路、道路ネットワークというものにつきましては、その道路単体の整備で円滑化を語るわけではございませんで、やはり都心部全体のネットワーク形成の中で交通の円滑化が整理されていくというところでございまして、当然ながら。","voiceIndex":241,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"この周辺の大きな道路、どこでも減ってきているという下で新たな道路は必要ないというふうに私は思います。立体的なパースとかも出してもらえないということで、住民への大きな被害もある中で、しっかりとした説明もされていないという状況ですけれども、区としては、こうした住民への被害、影響をどのように捉えているのか、伺いたいと思います。それまでは暫定活用が可能だということなのか、伺います。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"陳情にもあります買収用地の公園、福祉施設等の諸施設の設置ですが、基本的には、都市計画道路内、しかも事業中の道路内ですので、法的にも、一定程度の大きさの建物、一定程度というか。そこの用地に関しましては、今年度末までの許可期間をいただいておりまして、東京都との協議の中では、毎年度、１年間の許可の更新という形で使用するという形で取り交わしているものなので。","voiceIndex":244,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"商店街のところは、ぜひ継続的に暫定活用できるようにしていただきたいというふうに思いますし、実際この道路が、いつできるのかというところは、事業期間中、令和８年３月３１日ということでしたけれども、令和７年度中ということだと思いますが、そこまでにあと約２年ということですから、その下で、今、先ほどご説明いただいた用地取得率でも、１区間のみ５０％を超えているという状況です。","respondent":"鈴木都市計画課長","answer":"今後も、東京都と、あるいは地域と連携をして、防災性の取組を進めてまいりたいです。","voiceIndex":247,"id":"exchange-090"},{"speaker":"のだて委員","kind":"質問・要望","question":"ならないと思うのですけれども、そうした下で住民の暮らしが壊されていくということは、やはり区として住民の暮らしを守る責任があると思いますので、中止を求めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"そもそも論から教えてほしいのですが、この補助２９号線、これ、もともとは都市開発道路だったのですよね。そうではありませんでしたか。なので、その中で規制緩和といういろいろな優遇措置があったと思うのですが、まず、そこから、そして、この補助２９号線を、東京都の考え方なので品川区はどこまでお答えになれるか分からないのですけれども、選ばれた理由は何かお分かりだったら、教えてください。","respondent":"鈴木都市計画課長、小川木密整備推進課長","answer":"用地の買収につきましては、これは当然ながら、道路を整備していくわけですので、その中に最終的には、やはり皆さんに交渉に応じていただいて、土地を譲っていただいて、１００％の中で最終的に道路が開通していく。今後の整備地域の見直しにつきましては、上位計画の見直し等の中で、今後、検討してまいりたいというふうに考えてあります。","voiceIndex":252,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"補助２９号線が選ばれた理由が、多分そういうことだと私も認識しているのですが、都市計画道路ですか、それを指定したときに、その沿道の方々に対しての優遇措置があったと思うのですけれども、どうなのでしょうか。そういう認識は、皆さん、どうなのでしょうか。私は、住まわれている沿道の方は、ある程度ご理解していただいているのかなと思っているのですが、いかがでしょうか。","respondent":"長尾建築課長","answer":"都市計画道路での優遇措置というお話ですけれども、計画道路、都市計画決定の段階ですと、建築の制限はかかっているのですが、現在でいうと、木造であるとか、鉄骨造であるとか、３階建てまで。","voiceIndex":255,"id":"exchange-093"},{"speaker":"西本委員","kind":"確認","question":"ですから、私は、条件付で、ここの補助２９号線沿いに生活されている方は、そういう条件で過ごされていたのではないかなと思うのです。建築するときとか。それを確認したいのと、そういう指定がある、そしてまた今回、名前は違いますね、特定整備路線という名前は変わったにせよ、いずれは返してねということではなかったのかなというふうに思うのですが、いかがですか。","respondent":"長尾建築課長","answer":"都市計画道路の範囲内にかかっている土地で建物を計画される場合は、都市計画法の第５３条の許可手続が必ず必要になってきます。その中で、先ほどお伝えしたような建築計画の条件がクリアできているかというところが確認されています。","voiceIndex":257,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"この経過は、やはりきちんと説明したほうがいいと思います。忘れているのではないかと思うのです。品川区がやるべきものではないと思うのですが、そこはやはり東京都のほうにも、そこからの説明が必要なのではないかと思いますが、いかがですか。","respondent":"鈴木都市計画課長","answer":"１点、先ほど、私、昭和初期の都市計画決定とお話ししましたが、修正させていただいて、昭和２０年代の都市計画決定がなされて、委員ご指摘のとおり、もともと計画の位置づけが全くないところに、東京都として道路を入れますよということではございませんので。","voiceIndex":259,"id":"exchange-095"},{"speaker":"まつざわ副委員長","kind":"質問","question":"結論を出すでお願いします。不採択でお願いします。いろいろな説明の中で、区としても必要と考える特定整備路線、この中において、陳情項目には当てはまらないと考えています。それで、３つ目の暫定活用につきましては、やはりなかなか道路の工事が進まない中、暫定活用は引き続き続けていただけたらと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":262,"id":"exchange-096"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。住民を追い出し、生活を壊す補助２９号線などの特定整備路線は中止すべきですし、買収用地の活用も進めるべきだと思いますので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":265,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、不採択でお願いします。先ほども意見を申し上げましたけれども、原点に返って、なぜこの道路が選ばれたのかという歴史的経過が分からなくなっている部分があると思うので、しっかりそこを説明していただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-098"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すべきで、不採択でお願いします。特定整備路線の必要性は厚く感じておりますし、これは基本的には都の事業でありますので、都が主体的に事業を進めるべきだと思います。区の立場では、特段何を言えるはずもないのですが、区民の声を都に伝えていただく中で、一人でも多くの、一刻も早い地権者の理解を得て事業が完成するように、側面からご尽力いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":267,"id":"exchange-099"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の陳情で、説明会を求めてほしいということですけれども、先ほどご説明があった中で、チラシですとか、ニュースレターが、チラシは配布されている分もあるというところですけれども、実際、このチラシが計６回配布されたということですが、昨年の９月が最終ということで、それから配布されていないのかどうかというところと。","respondent":"鈴木都市計画課長","answer":"委員ご説明のとおり、国が新飛行ルートの運用を進めていくということを公表して以降、国のほうで、オープンハウス型説明会、それから、区内では１３地域センターで行っていただいたところですが、区では、これまでも様々な方法で区民の方への情報提供、周知。","voiceIndex":276,"id":"exchange-100"},{"speaker":"のだて委員","kind":"質問・要望","question":"運用実施の前には説明会をやってきたというところで、運用を始めたら、もう住民は関係ないと、言い過ぎかもしれませんけれども、そうしたことであるならば、それは許されないというふうに思いますので、ぜひ国としても説明していただきたいと思いますし、区としても、それを求めていただきたいというふうに思いますけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"今後の検討会の検討状況、今後、具体的な内容が明らかになっていくと思いますが、そうした中で、区民の方への説明は、やはりこれまでどおり、様々な手法を活用して、国のほうで丁寧に行っていただくように、区としては求めていきたいです。","voiceIndex":278,"id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、住民が知りたいのは、やはり品川区の上を飛ぶのか、被害がなくなるのかということが一番だと思いますので、そうしたところで、恐らく検討会の資料を見ても、それは分からないと思いますので、そうしたことが実際にやり取りができるように説明会を実施していただきたいというふうに思いますし、固定化回避検討会の中身としては、私は。","respondent":"鈴木都市計画課長","answer":"１点目の具体的な解決策というお話ですが、まず、国が今、実施している固定化回避検討会につきましては、現在行っている新飛行ルートを固定化せずに、違う方法がないかというところを技術的に検証していただいているところです。","voiceIndex":280,"id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうした下で、やはり都心を低空飛行するという新ルートは、やはりやめることが一番の解決策だと私は思いますので、ぜひ区としても、中止をするという立場に立っていただきたいというふうに思います。この陳情では、教室型説明会、今の状況がどうなっているのかということも含めてだというふうに思いますけれども、求めておりますので、ぜひ実施をしていくべきだと意見を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"周知方法について、この(2)「品川区の皆さまへ」というものがありますが、これはもちろん分かっております。それから、この第５回検討会から約１年間以上なされていないというこの事実をどう捉えていますか。いつまで待つのですか、１年間以上。放ったらかしですか、品川区。いいのですか、これ。１年以上ですよ。品川区は何もアクションしないのでしょうか。お答えください。","respondent":"鈴木都市計画課長","answer":"固定化回避、委員ご指摘のとおり、前回、第５回の検討会の資料の中でも、次年度、令和５年度の夏から秋にかけてというところで記載されておりますが、もうすぐ１２月に入ってしまうというところで、その辺は、東京都のほうで定期的に行われている関係区市の連絡会の中でも。","voiceIndex":284,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"チラシを確認していただきたいのです。うがった見方をしてしまうような状況をやっているなというふうに私は個人的に思っているところがあるので、ほかの区はどうなのでしょうか。それは少し不信感があるので、ぜひ確認をしてください。品川区はそれでいいのですかということです。どうなっているのですか。私たちは、その生活を何とかしなければならないという思いがあるわけではないですか。","respondent":"鈴木都市計画課長","answer":"固定化回避検討会の実施時期については、委員ご指摘のとおり、夏から秋にかけて実施したいというところから大分遅れが出ているというところは、区としてもしっかり認識しているところでございまして、その辺りは、第５回目が昨年８月に実施されて以降。","voiceIndex":286,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"今は品川区サイドのお話だったと思うのです。この羽田新ルートの担当は建設委員会です。そこはある程度もう決着をつけてもいいのではないですか。もう１年以上もたっているわけですから、やはり区議会として、早く進捗状況を知らせよというのは、議会から発言してもいいのではないかと私は意見として申し上げたいと考えています。皆さん、それを踏まえての審議をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":288,"id":"exchange-106"},{"speaker":"まつざわ副委員長","kind":"質問","question":"継続でお願いいたします。国としてのオープン型説明会、そしてまた、１３地区の地域センターでの説明があるとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":290,"id":"exchange-107"},{"speaker":"若林委員","kind":"意見","question":"継続でお願いしたいと思います。６回目の検討会がそろそろ開かれる時期、また、このたびは、先ほどもありましたけれども、区民アンケートに関連して、その声を羽田については、区が直接、国のほうに届けていくということもありますので、いわゆるこの説明の仕方については、しっかりと私どもも注視をしていきたい、こういう趣旨で継続で結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":291,"id":"exchange-108"},{"speaker":"木村委員","kind":"意見","question":"継続でお願いいたします。以前の空路に戻せというようなこともいろいろ言われておりますけれども、それと、現在との、私は両方うまくつくっていく、今のルート、新しいルート、そして以前のルートと、これをうまくかみ合わせた新しいルートをつくるべきではないかなと、これは勝手な私個人の意見でありますけれども、今回のこの陳情に対しては、継続でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":292,"id":"exchange-109"},{"speaker":"のだて委員","kind":"意見","question":"本日結論を出すということで、採択です。前回検討会が行われてから１年以上経過していますし、区民に説明がないということで、説明会を開くべきだということで採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出す、採択でお願いします。なので、品川区議会としても、早く説明をしろと、どういう状況か進捗状況を説明しろと強く申し上げるのは非常に大切なことではないかと思いますので、私は、今後、品川区としても強く態度を示していかなければならないということを強調させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":294,"id":"exchange-111"},{"speaker":"田中委員","kind":"意見","question":"本日結論を出すで、不採択でお願いしたいと思います。やはり全体の国政の立場で、こういう自治体間をまたぐような事業については、特に、空港に関しては国政マターだと思いますので、国会あるいは国土交通省においての判断だと思いますので、そちらにぜひ直接思いをお伝えいただけたらというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":295,"id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"この資料にも、お休み石がベンチということですけれども、これ、ちょっとひと休みできるということで設置をされているということで、区としても、このベンチの役割は認識をされているのかなというふうに思いますけれども、その点についてご答弁があれば、いただきたいと思いますが、今回、区内で２８９基、設置されているということで、先ほど、区民の声から。","respondent":"鈴木都市計画課長","answer":"１点目のお休み石をベンチとの認識を区として持っているかですが、先ほどご説明したとおり、やはり区民の方が、まちを歩く、移動する過程において、街中でひと休みできるようなスペースが必要だというところで設置を進めてきているところです。","voiceIndex":302,"id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"実際、どういったところに設置するのがいいのかなと考えると、急な長い坂のところとか、ずっと上り続けることがしんどいというところとかに設置していっているところもあるのかというふうに思うのですが、この間、住民から要望があったところは、そういったところもあるのか、どういう場所の傾向があるのか、伺えたらと思います。","respondent":"鈴木都市計画課長","answer":"平成８年度から行っていまして、実際、要望いただいて断った事例がどれほどあるかというのは、詳細にまでは、私、把握してないのですが、例えば区道で歩道がないところで、その道端に置いたら休めるのにという声をいただいても。","voiceIndex":304,"id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり様々な区民要望があって、この間、設置をしてきているということだと思いますけれども、先ほど、バス停のところにはどうかということで伺ったので、そこだけ伺えればと思いますが、やはり様々、場所の条件としては、課題があるところもあると思いますが、こうした安心して出歩けるという面では、高齢者だけではなくて、陳情にもあるとおり、小さいお子さんがいる方ですとか。","respondent":"鈴木都市計画課長","answer":"品川区独特の取組、独自の取組で、２８９基の区民の方が休んでいただける整備というのは、他区と比較しても、非常に、そうしたスポットの整備が行われてきたのかなという認識です。","voiceIndex":306,"id":"exchange-115"},{"speaker":"田中委員","kind":"質問","question":"積極的にお休み石等を設置をしていただいているということはすごく理解をしておりますが、設置する条件として改めてお伺いしたいのですが、６１基が公園、広場等にあるということで、ここは設置しやすい場所だなと思いますが、道路に２２８基ありますが、道路といっても、どんな道路でもいいわけではなくて、いわゆる歩道だと思うのですが、歩道であれば設置できるということで。","respondent":"鈴木都市計画課長","answer":"恐らく歩道がないところの設置の申請を行っても、そうした占用許可、やはり通行上支障があるということで、占用の許可が下りないのかなです。","voiceIndex":309,"id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味で、すごく積極的に設置いただいているということは理解している上で、先ほどの議論にもありましたが、バス停のところに設置をという、確かに声はあるかと思いますが、やはりバス停がどこに設置されているかが大前提で、要は、バス停が歩道にあるところであれば設置しやすいですし、歩道のないところにあるバス停には、これは設置はしたくても、していただきたいという要望があったとしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-117"},{"speaker":"木村委員","kind":"質問","question":"今、区内には、２８９基の椅子があるということをお聞きしました。これ以上は、品川区内では増えるという予定はないのか。何となくそういう人を見ると、私もほっとするわけですけれども、そういう方々のためにも、１基でも多くつけられるようなお考えを、今、２８９基と言っていましたけれども、それ以上増やす予定はないのか、そういう点についてもお聞かせください。","respondent":"鈴木都市計画課長","answer":"今後の設置増についてですが、基本的には、事業立ち上げ当初、一定、毎年計画的に増やしてきたというところの、例えば、今後、毎年５基、１０基という予定は今のところないのですが、基本的には、もうしばらく維持管理、修繕のほうに力を注いでいきたいですが、一方で。","voiceIndex":313,"id":"exchange-118"},{"speaker":"まつざわ副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。陳情には品川区は圧倒的なベンチ不足と書いてありますけれども、平成８年度から、他区以上に、このしながわお休み石という部分で２８９基、区民の皆様の要望から始めたこのお休み石の設置という部分に関しては、ベンチ不足ということはないと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":317,"id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"本日結論を出したいと思います。平成８年度からということで、思い返してみれば、本当に一時期、お休み石というご相談もたくさんいただいた記憶がありまして、つけられたところ、設置できなかったところ、本当に様々です。今後もこういう方向性で進んでいっていただきたいなと思いますけれども、ここには区のほうで精査をしというような表現もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問・要望","question":"今は、改築というか、それをしている時期だということで、やはり２８９基ありますので、当然それは、いずれにしても老朽化してきますから、それを改築しなければいけないということは当然ながらありつつも、必要があったら要求をしていただいて、できれば区民の皆様方と一緒に設置をするというのは、これからも続けていただきたいなというふうに思っております。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。内容は、趣旨採択で。区のご尽力は評価した上で、陳情者、設置条件がどういうところにできるかできないかということは理解されない上での、ただ、健康面、高齢者の方等々の対応ということで設置を求められておりますので、趣旨としては、その方向性に合っていると思いますので、趣旨採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-122"},{"speaker":"田中委員","kind":"意見","question":"苦渋の決断として、条件はどうしても、設置条件の中では最大限やっていただいているという判断をしますので、不採択で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":325,"id":"exchange-123"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"事故があったところは補修されたということで、よかったと思いますので、今後、気をつけていただきたいと思います。今回の転倒事故や和解に至る経緯を伺いたいと思います。損害賠償額については、慰謝料や休業損害等ということで書かれておりますが、その内訳を伺いたいと思います。","respondent":"森道路課長","answer":"令和３年９月から令和４年８月頃まで通院を繰り返されたというふうに聞いています。","voiceIndex":331,"id":"exchange-124"},{"speaker":"西本委員","kind":"質問","question":"今のご答弁で聞き逃したと思うのですけれども、事故が起きた、その相手方から申告があったという理解でいいですか。","respondent":"森道路課長","answer":"何割かという話は、保険会社のほうで設定をされて、その金額を区としては受けて、それでご提示したというような形になっています。","voiceIndex":334,"id":"exchange-125"},{"speaker":"西本委員","kind":"質問・要望","question":"結構報告されないで終わってしまっているケースが多いと思うので、積極的に何かあったら言ってくださいというのは、言い難いところがありますが、その辺の対応はどうされる、やはり言われたらやるという形なのでしょうか。その前に、区道の点検は常にやっていただきたいという思いはありますけれども、でもやはり、結構こういうケースは多いのではないかと思うのですが、対応の方法はいかがでしょうか。","respondent":"森道路課長","answer":"いただいた上で、区のほうでしっかりと対応を誠実にするところですけれども、必ずしも補償が出るということでもございません。","voiceIndex":336,"id":"exchange-126"},{"speaker":"田中委員","kind":"質問・要望","question":"我々健常者は、ちょっとした段差は避けられますけれども、高齢の方とか、車椅子の方は、ちょっとした段差も大きな障害になってしまう中で、今回のような事故が起きてしまうと、やはり歩道の在り方、レンガ敷きが、特に商店街の見栄えの観点で積極的に取り入れた時期もあったかと思うのですが、一方で、そういう事故があったりで、経過すると段差がより激しくなったり、あるいは。","respondent":"森道路課長","answer":"あるいは、レンガ状ではあるのですけれども、そういった段差がつかないような、アスファルト敷きに色をつけたり、レンガの模様をつけたりということもありますので、今後はそういった技術もしっかり使いながら、安全な歩道を整備していきたいと考えています。","voiceIndex":338,"id":"exchange-127"},{"speaker":"若林委員","kind":"質問","question":"参考までにお聞きしますが、例えば１m2辺り、今お話に出ているレンガ状のもの、インターロック、通常のアスファルト等の舗装、これ、維持管理費は大分違うのでしょう。","respondent":"森道路課長","answer":"すみません、管理費として、１m2辺りというものを計算してはいないので、明確にお答えはできないのですけれども、肌感覚といたしましては、インターロッキングブロックのほうが高かろうというふうに考えておりますし、道路管理をするだけの視点でいきますと。","voiceIndex":341,"id":"exchange-128"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4394#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":89659,"voices":346}},{"id":"r05-20231127-9","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"文教委員会","time":"午前１０時００分～午後 ３時３４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を92件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８０号議案、品川区児童相談所設置条例","agenda":"第８０号議案、品川区児童相談所設置条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"２点伺いますけれども、まず、資料の下の表で、令和６年度の一番右下、条例（案）上程というのがありますけれども、これは来年６月、どんな内容の条例になるのでしたかという確認が１つと、もう１つは、現在、建物は完成していまして、その中で、今年４月から準備業務を職員の方も入って行っていると思うのですけれども、その中で見えてきた現在の課題等というものについて伺いたいのですが、ハード。","respondent":"長谷川児童相談所開設準備課長","answer":"２点ご質問いただきました。１点目の、設置市事務移管に伴う条例提案の中身です。今、所管部署と協議をしておりますけれども、おおよそ１３本程度予定をしております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"質問","question":"この設置条例に関しては異論ないところなのですけれども、関連して、条例上は品川区児童相談所という名前だと思うのですが、江戸川区なんかだと、はあとポート、荒川区は、子ども家庭総合センターのように、副題というか、親しみやすいというか、そういう名前をつけているのですけれども、この条例とは関係ないというか、あれなのですけれども、そういうことについては検討されているのでしょうか。","respondent":"長谷川児童相談所開設準備課長","answer":"愛称に関するお問合せです。区として今後検討すべき事項であるとは認識していますが、しかしながら、現時点においては、制定するといったところで考えているわけではございません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"設置条例ということで、子供の森公園内の設置なのですけれども、これについては、子育て世代の利用者等から見直しを求める意見も上がった経緯も過去にはありまして、設置場所や決定の経過とか、住民の説明と進め方の在り方などについては課題があったと認識はしているのですけれども、虐待防止を含めた、きめの細かで切れ目のない子育て支援を実現する上で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すで、賛成です。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"}]},{"id":"topic-02","title":"第８１号議案、品川区立保育所条例の一部を改正する条例","agenda":"第８１号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"それと、暫定保育園のほうさん保育園のほうですけれども、こちらは１歳児園ということでよろしかったのでしょうかということと、あと、今年４月の荏原地域、６月の委員会で報告がありましたけれども、保育提供区域でいうところの荏原というところが、不承諾数が６３で、１歳児で半分の３１を占めているということで、この地域での待機児対策というのは十分ですという考えなのでしょうか。伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"３点ご質問いただきました。１点目です。一本橋保育園の民営化のタイミングですけれども、令和６年４月、来年度当初からの民営化を予定してございまして、改築工事実施後、移転をした後に民営化するというスケジュールで現在進めているところです。２点目です。","voiceIndex":22,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"期間限定の暫定施設として広報周知されていた内容ですので、賛成です。ただ、解体期間として、来年の４月から６月に予定されていると思われますが、こちらの解体工事の地域住民への配慮と周知を改めて徹底していただきたいと思います。こちらは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-006"},{"speaker":"安藤委員","kind":"意見","question":"反対なのですけれども、というのは、一本橋保育園のほう、施設の老朽化による改修、建て替えというのは必要なことなのですけれども、今回の改築というのは、ほかの民営化の園もそういう態度を示させていただいたのですが、区立保育園の民営化と。将来は、これは区も説明していますけれども、民設民営、完全に民間に渡すという流れの中での改築でありますので、認められないということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-007"}]},{"id":"topic-03","title":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","agenda":"第８４号議案、品川区いじめ防止対策推進条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"特に直接、条例には定めはないのですけれども、臨時委員にはどのような方を据えることを想定していらっしゃるのか伺いたいのが１つと、あと、これも条例に入れるのかどうかというのはあるのですが、やはり被害者とか家族にとっては、どんなことがあったのかというのは、すごく知る権利というのは尊重すべきだと思うのですけれども、その上で調査を行う対策委員会の存在というのは非常に大切だと思うのです。","respondent":"丸谷教育総合支援センター長","answer":"被害者、被害者のご家族のご推薦というようなことですけれども、いじめの事案に応じて、こちらの教育委員会のほうで、このケースであれば法律がよいだろう、場合によっては、このケースについては心理を厚く持たせたほうがいいだろうということで、こちらのほうでもある程度。","voiceIndex":36,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですね。被害者とか家族の知る権利というのはすごく重要視していただきたい、尊重していただきたいと、要望します。それと、ごめんなさい、正規の対策委員の職種についてお話がありましたけれども、これは規則とかにしっかり具体的に入っているものなのでしたか。そこだけ最後、勉強不足ですみません。確認させてください。","respondent":"丸谷教育総合支援センター長","answer":"条例の中ではなくて、規則のほうで規定をしています。","voiceIndex":38,"id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問","question":"１点だけ伺いたいのですけれども、「次に掲げる事項について調査審議し」となっております。その調査の権限の中に、例えば、当事者からの聞き取りとか、そういうものは含まれるのか、その点について伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"調査の中には、場合によっては、被害に遭われた児童・生徒、保護者については必ず聞き取るようにということでこれまでも調査を進めてきておりますので、今後も丁寧に進めてまいりたいと考えております。","voiceIndex":41,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"保護者のご意見というのもとても大切だと思いますけれども、できましたら当事者、それもやはり両方の立場の意見とか、事実関係とかを聞き取るようなところも含めていただきたいと思います。これについて何か既にお考えのことがあったら、ご見解を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そういったところで、心理の専門家や福祉の専門家、子どもに丁寧に対応できる委員というのを選定、進めていきたいと考えております。","voiceIndex":43,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひそのように進めていただきたいと思います。子どもたちの意見とか発言を誘導するようなことがあってはならないし、本当に公正な立場で、いじめをしてしまった側、いじめられたと思っている側の意見を丁寧に聴取できるような方をぜひ選定していただきたいと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"意見","question":"第１４条２項に(2)が加わったということですよね。２０条に規定するという。書いてあるのに、またここに、逆に、順番で言うと、１４条が先だからあれですけれども、何でそこに書いたのかというところ、当然してきたわけなのですけれども、その点を、法律の立てつけが不勉強で分からないのですけれども、そのことをお尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"確かにこれまでも２０条にそのことは記載があったところなのですけれども、今回改めて１４条に役割として２点しっかりと明記することで、対策委員会の役割を明確にしたです。","voiceIndex":47,"id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問","question":"役割をはっきりさせたということで、万が一、いじめの行為が起きたときには、しっかりと対策委員会で調査することを宣言したというか、決意を新たにしたというか、そういう認識でよろしいですか。","respondent":"丸谷教育総合支援センター長","answer":"今のことと加えまして、今回、臨時委員を置くということで規定を定めるものでございまして、その意味については、重大事態が起こった際に臨時委員を置くことができるということで、次のほうにつながるような記載が必要ということもございましたので。","voiceIndex":49,"id":"exchange-014"},{"speaker":"ゆきた委員","kind":"意見","question":"先日、文教委員会で視察した寝屋川市や他自治体でも、いじめ対策委員会の条例や規則で臨時委員を設置できるようにしている自治体も多いので、現実に即した対応だと思われますので、公明党としては賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望なのですけれども、今後は、子どもたちが楽しく安心して学びに向かえる学校づくり、あと、いじめに走る必要がない学校づくりなどの予防対策、また、小さないじめの芽や子どもたち同士のトラブル等が発生しても、子どもたち同士で話し合って自治的に解決できるような、子どもが主体の学校づくりというのをぜひ望みたいと思います。賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-016"}]},{"id":"topic-04","title":"第８６号議案、指定管理者の指定","agenda":"第８６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"改めて今回の公募によらなかった理由というところなのですけれども、特別な理由というところをもう少し中身といいますか、どんな理由なのかというのを伺いたいのが１つです。それと、そこの(3)番目の１期目の成果についてというところで、「強みを生かした保育・教育理念」と書いてあるのですけれども、それはどういう理念なのでしょうかというのを伺いたいと思います。","respondent":"立木保育課長","answer":"そうした中、社会福祉法人福栄会のほうにぷりすくーる西五反田の運営が移ったわけですけれども、移った後３年間の運営実績、こちらを毎年モニタリング等をさせていただいている中で、ＮＰＯ法人が培ってきたノウハウ、そちらを職員等。","voiceIndex":63,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"前の職員を引き継いでくる約束がありましたという話なのですけれども、それは別に福栄会だけに限らず、統合した事業者は、基本的には前の継続性とかを考えて、前の職員の方を雇ったりということは普通にあることなので、前回のときには公募すべきだったと私は改めて思うのですけれども、なぜ公募にしなかったのかというのを改めて伺いたいというのが１つ。伺いたいと思います。","respondent":"立木保育課長","answer":"認定こども園化につきましては、今現在は社会福祉法人化が実現いたしましたので、１つ課題としてはクリアされましたが、もう一つ、幼保連携型認定こども園に移行認可を受けるためには、今現在の施設ですと、園庭の部分が９０m2ほど不足しておりまして。","voiceIndex":65,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"５年目となる今回でいろいろやればよかったのではないですかと思うのですけれども、そこがますます分からなくなってしまったのですが、なぜ現在移行していないのであれば、急いで２年前に指定管理中に交代する必要があったのか、最後に伺いたいと思います。","respondent":"立木保育課長","answer":"認定こども園化に向けましては、区としましても、早期に実現をしたいと考えている中で、できる部分から取組をさせていただいたです。","voiceIndex":67,"id":"exchange-019"},{"speaker":"せお委員","kind":"確認","question":"幾つかお伺いしたいのですが、報告書の中で、委員の意見のところ、５ページです。すみません。もう１点だけ、細かいのですけれども、７ページの委員の意見のところの(1)で認証心理士と書いてあるのですけれども、これ、臨床心理士か公認心理師かとか思っているのですが、これ、私、ごめんなさい、認証心理士というところが知らないので、そこを確認したいのと、そこだけお願いします。","respondent":"立木保育課長","answer":"特別支援に関しての保護者の支援等に関しましては、今お話がありましたとおり、障害児者総合支援施設のほうは福栄会がやっておりますので、そういったところへの、例えば、なかなか難しいところではあるのですけれども、保護者の方への働きかけといいますか。","voiceIndex":70,"id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"ありがとうございました。先ほどの事故・けがの際のところなのですけれども、その内容をどのように、具体的に保育課で共有するのかというところをもう一回教えていただきたいのと、臨床心理士は園にいらっしゃるのか、それとも、区の巡回の方だけということなのか。そこもすみません、もう一度お聞かせいただければと思います。","respondent":"立木保育課長","answer":"報告書の様式がありますので、そちらのほうに詳細、発生原因ですとか、今後の対応についてというようなところをまとめてもらって、それを区のほうに提出してもらうというような形になります。","voiceIndex":72,"id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"障害児に関しては、保護者への支援をしていただいているということで、本当にありがたいのですけれども、やはり園の職員の認識と保護者の認識で少し違っているところがあったり、せっかく福栄会でグループというか、児童学園とつながっている、連携できるので、何かそういったところも仕組みがあればという。スムーズに連携できるようなところはお願いしたいというところで、そこはまた要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-022"},{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ。７ページの認定こども園化についてで、先ほどからの話だと、この７ページでは、いわゆる人員体制は確認できたとなっていて、それはいいのですが、先ほどの話だと、課題はそこではなくて、園庭の面積が大きな課題なわけですよね。その辺の確認だけさせてください。","respondent":"立木保育課長","answer":"これも指定管理者にどうこうできるところではなくて、区のほうがしっかりこれは対策を立てていかないといけないという部分ですので、それを今、ぷりすくーる西五反田と、あと、隣の区有地であります西五反田保育園。","voiceIndex":76,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"そんな中で、今回、指定管理者、福栄会がやることによって、その先のいろいろな一体化も含めて、それこそ高齢者施設、シルバーセンターとかという話なので、そういうのを含めてやると、福栄会が指定管理でやられているのが非常にいいという意味合いなのですか。","respondent":"立木保育課長","answer":"そうした中でどういう形がいいのかというのは、これから区がしっかり検証、検討していかないといけないと思っていますが、今現在、例えば福栄会がやっていただいているということで、それに合わせた形での改築なりということではなく。","voiceIndex":78,"id":"exchange-024"},{"speaker":"石田（し）委員","kind":"質問","question":"でも、せっかく福栄会がやるのであれば、彼らのノウハウもいっぱいあるだろうし、いろいろな知識も持っていると思うので、そこはうまく連携をしていただくのがいいのかと。そういった意味で質問を先ほど。ぜひそこはうまく連携していただければと。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-025"},{"speaker":"吉田副委員長","kind":"提案","question":"それで、事故・けがの際の保育課への共有については、私どもも確認しております。たしか誤食ですよね。１件ありました。それで、それに関連しますが、提案内容の評価が、４５０点満点のうち３８２点、それから、財務状況の評価で何でこれが満点にならないのかと思ったのですけれども、その辺の減点理由が何か、お話を伺えるようでしたら、伺いたいと思います。","respondent":"立木保育課長","answer":"財務状況のところですけれども、今、細かいところはあれなのですが、毎年決まった予算の中でやっていただいている中で、なかなか苦労してやってもらっているところもありまして、そういった中で、お金をよりうまく使ってもらうというところで。","voiceIndex":82,"id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"これまでもそういう発言をしていると思うのですけれども、資料提供をされるべきではないかと思います。それから、財務状況については、福栄会自身はすごく全体の財務状況などはホームページ上で公開されているということも承知しておりますけれども、これ、指定管理ですので、その辺について、満点にならないというのはよく理解できないので、今後、その辺についてはぜひ満点を出していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"確認","question":"この指定管理については異論ないところでありまして、お伺いしたいのは、幼保連携型認定こども園についての移行で、ほかの委員の方からもありましたけれども、隣の保育園との関係も含めて、それをすることによって、認定こども園へ移行ということを検討しているというのは、もう一回確認ですけれども、隣の保育園と一体化するかどうかは置いておいて。","respondent":"立木保育課長","answer":"具体的に、例えば、９０m2の確保の仕方なのですけれども、ぷりすくーる西五反田そのものを建て替える必要までは今のところないと思っておりまして、例えば、９０m2分を隣の敷地の一部を使うような形で何かできないかというようなところも含めたり、あとは、屋上の部分が、今。","voiceIndex":86,"id":"exchange-028"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"屋上の２方向は工事とか、いろいろ大変なことになるかと思うのですけれども、区が目指していると書いてありますので、そこを目指して、今お話のあったことも含めて、ぜひ検討を早急に進めていただければと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-029"},{"speaker":"ゆきた委員","kind":"確認","question":"理事者からご説明があったとおり、社会福祉法人の強みを生かせる点、人員体制についても確保されている内容を確認いたしましたので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-030"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"先ほど質問いたしましたが、安全確保とか、それから全体の財務状況というのは、やはり満点というのは難しいのかもしれないですけれども、満点を目指して、今後とも見直していただきたいという思いを込めて、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-031"},{"speaker":"安藤委員","kind":"意見","question":"賛成です。令和２年度の期間途中の指定管理交代の必然性についての区の説明については、まだ納得できない点はありますが、通う子どもの保育・教育環境が大切ですので、施設の性格上、継続というのは理解できますので、賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-032"}]},{"id":"topic-05","title":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第７６号議案、令和５年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと、マイスクールのほうは、こちら、対象の学年を伺いたいと思います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私からは、国立・私立に通っている方の人数ですが、小学校で約１,２００名、中学校で約３,０００名と把握しています。新しく開設するマイスクールの対象の学年ですけれども、資料２の(2)にありますとおり、区立小・中・義務教育学校に通う３年生から９年生の児童・生徒と考えております。","voiceIndex":103,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"学校給食のほうですが、区長が所信表明で、保育・給食・医療子育て３つの無償化については、いずれも所得制限を設けることなく、全ての子育て家庭の負担を減らすべく実施してまいりますと述べていらっしゃるわけですが、本当は国がやるべきだと思いますが、このように表明をされているわけですから、全ての私立、国立、都立、分け隔てなく、学校に通う区民の児童・生徒へも。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"特別支援学校以外に、国立・私立学校への支援の拡大ですが、こちら、教育委員会といたしましては、学校教育法のほうで、少し省略はいたしますが、学校の設置者はその学校の経費を負担するというものが定められておりますので。マイスクールの、今回、４つ目の施設となるわけですけれども、エリア的にもまだ不十分という認識もありますので、マイスクールの場所が増えていくといった段階で、１、２年生も通える範囲になるということがあれば。","voiceIndex":106,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"国の動きを注視していくということですが、注視だけしていないで、当初、品川区が無償化を踏み出したときというのは、２３区でもかなり少数だったのですけれども、２３区全部踏み出したという感じではなかったかと思うので、やはり実施することが周りとか国を大きく動かしていくということになりますので、ぜひ品川区から、もちろん国に実践、示していくという意味でも、注視だけではなくて、自ら国立、私立。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"荏原地区は今後、これ、いろいろとご検討願いたいというのは、要望で終了させてもらいますけれども、２点お尋ねします。既に終わっているかと思うのですけれども、当然これ、理解は得られていると思うのですが、この町会長会議の中でどういう質問があったのか、質疑があったのかというのをお尋ねしたいと思います。これ、何か違いが、横文字になって、どういう仕切りになっているのかと思って、その確認です。","respondent":"丸谷教育総合支援センター長","answer":"地域説明、町会長会議が１１月１０日にございまして、町会長に説明をしてまいりました。ほぼというか、子どもたちのための施設になるならということで、賛成をしていただいたという認識です。","voiceIndex":111,"id":"exchange-036"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"我々も一生懸命やりますけれども、そこは要望しておきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ただ、中には学校に、例えば週１回とか２回とか、別室に通えるといったような児童・生徒も多く含まれておりますので、学校と児童・生徒、家庭との連携の中で対応しているものと、また、今後は、例えば、校内に別室指導の支援員を、今、荏原五中で配置をしておりますけれども。","voiceIndex":115,"id":"exchange-037"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"仮にそのようなスペース的に、いわゆる敷地というか、その確保が難しくて、なかなか造れないのであれば、場所的な部分に関しては、私は例えば塾とかは区内にたくさんあるわけですよね。その教室、いわゆる学校の時間帯というのは、そんなに塾というのは繁盛というか、していないわけですよね。忙しくない時間帯ではないですか。これは要望で終わります。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":117,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つは、西大井の指導体制なのですけれども、室長は現状は八潮などだと元校長先生でしょうか。ただ、その指導される方、指導員というか、実際に児童・生徒に接する方は、教員では、正規のもちろん東京都の教員ではないわけなのですけれども、どういった方が指導する体制になるのかということ、あと、何人ぐらい、３０人ですから、八潮と同じぐらいなのでしょうか。その点もお願いします。","respondent":"丸谷教育総合支援センター長","answer":"人数の規模ですけれども、今まさにその辺りを調整しているところでございまして、八潮と同等の人数を想定して募集をかけていきたいと考えております。","voiceIndex":119,"id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"ありがとうございました。ですから、余計にやはり正規教員でないということは、なかなか、逆に言うと、いろいろ校長先生の指導とかがあったとしても、余計に厳しいところがあるのではないかと思っています。集団でやるということは本当にプラスで、移動教室にも行ったり、そういったことをやるので、体制自体はいいと思うのです。ただ、そこの適応指導教室のことについて、最後、お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"国のほうでも設置については求めているところですので、今後、国の動き等も十分に注視しながら、また、他地区でも不登校特例校を設置している動きが徐々に見られているというところも我々認識していますので、今後どういう形で進められるかというのは引き続き注視しながら。","voiceIndex":123,"id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。国や他区の動きを十分注視して、特例校についてはぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"私から２点お伺いしたいのですが、給食費のほうなのですけれども、実施方法のところで、申請方法、申請書および奨励費の結果とあるのですけれども、奨励費というのは、区や都が準備しているのは存じ上げているのですが、私立や国立というのはあるものなのか。私が無知なだけなのですけれども、奨励費の結果というところを具体的に教えていただければと思います。","respondent":"柏木学務課長、丸谷教育総合支援センター長","answer":"私から、奨励費の件ですが、こちら、特別支援学校への就学奨励に関する法律というのがございまして、そちらでは公立、私立、国立がこの対象になるということで定められておりますので、私立、国立も奨励費があるということになります。とはいえ、学校施設ではございませんので、その施設に合った形での活動ということを工夫してやっていきたいと。今後、カリキュラムの検討等を進めていく中で考えていきたいと思います。","voiceIndex":127,"id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問","question":"このたびのマイスクールのほうなのですけれども、この間、決算特別委員会のときに、うちの会派の議員から、１、２年生に不登校が増えているということに対しての、１、２年生を対象としたところも増やしてほしいという趣旨の質問をいたしました。","respondent":"丸谷教育総合支援センター長","answer":"１、２年生の不登校児童への対応ということですけれども、マイスクールについては、現状、場所が４か所しかないということと、遠方から通う児童も出てくるということで、体力的にどうなのかというところで、今回も見送っております。","voiceIndex":132,"id":"exchange-043"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"できたら、それこそ地域を考えると、荏原地区へというのは、区全体として求めるべきことと考えていますが、それと併せて、それがすぐ実現が不可能であれば、学校の中で具体的にそういうことをどう進めるかというのを学校任せにしないで、ぜひ全体として検討していただければと思います。もし何か見解があったら、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"不登校児童・生徒の問題については、単独の学校の問題ではなくて、区全体、もっと言えば、国全体の課題だと考えておりますので、国や都の動きも注視しつつ、品川区としてできることを引き続き検討して進めてまいりたいと考えております。","voiceIndex":134,"id":"exchange-044"},{"speaker":"ゆきた委員","kind":"意見","question":"特別支援学校給食費事業について、公明党として大変歓迎したい内容だと感じていますので、賛成です。ただ１点、品川区として、国立・私立の特別支援学級に入学した際の学籍までは把握していると聞いております。マイスクール西大井については、こちらも賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":138,"id":"exchange-045"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"特別支援学校給食費については求めてきたところですので、賛成をいたします。それから、マイスクールについては、先ほど要望もいたしました。まだ本当はもっともっとと思うところはあるのですけれども、この拡大が進んだということでは、一歩前進として評価をいたしますので、賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-046"}]},{"id":"topic-06","title":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","agenda":"第８２号議案、品川区特定教育・保育施設および特定地域型保育事業の運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"参考までに、今回の文言整理に関わる、就学前の子どもに関する教育、保育等の総合的な提供の推進に関する法律、この改正の内容は何だったのか伺いたいのと、また、今回、条例改正によって、区の事業の内容に何か変化が伴ってくるものなのか、伺いたいと思います。","respondent":"石井保育支援課長","answer":"今回の改正は政令指定都市に係る部分ですので、区の事業内容等に変更があるものではございません。","voiceIndex":148,"id":"exchange-047"}]},{"id":"topic-07","title":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和５年請願第１５号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"親同士というか、そういった園と利用者、子どもがつながっていくというのはすごく大事なことだと思うのですけれども、ご説明はちらっとあったかとは思うのですが、区として、連合会の活動についてどういう認識というか、評価されているのか。実際、連合会の活動というのはどういうことが行われているのか、もう少し説明していただければと思います。","respondent":"石井保育支援課長","answer":"活動についての区としての受け止めなのですけれども、やはりこういった中で、保護者ですとか教職員相互の連携を図りながら、各園で実際にやっていただいている教育活動と相まって、幼児教育の下支えとしてとても貢献していただいているという認識です。","voiceIndex":163,"id":"exchange-048"},{"speaker":"吉田副委員長","kind":"質問","question":"本日結論を出すということで、採択を主張したいと思います。幼児期のこういう集団の中での教育というのは、いわゆる学校に入ってからの教育以前の、非認知機能を育てるという意味でも、この時期の集団教育は大変大切だと認識しております。なかなか厳しい運営だというのを伺っておりますので、この請願については採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":168,"id":"exchange-049"}]},{"id":"topic-08","title":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","agenda":"令和５年陳情第４５号、品川区立学校図書館の充実に関する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それで、図書館運営支援スタッフの委託契約の内容について最初に伺いたいのですが、週に何日、何時から何時までという契約なのでしょうか。契約期間は何年間なのか。資格要件はどうなのか。仕事の内容は、大まかな、こういった仕事をやってもらいますという内容を伺いたいと思います。今実際に働いているスタッフの方というのは、正規雇用になるのか、非正規雇用になっているのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"仕事内容につきましては、細かくは、開いていない場合は開館事務だとか、閉じる場合の最後の閉館事務、貸出し処理、返却処理、本の配架、カウンター周辺業務、それから、本のリクエストに対する業務、レファレンスや授業支援業務、それから、教職員の相談対応、資料の登録。","voiceIndex":180,"id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。何時から何時という勤務時間の定めというのはなかったのかというのを伺いたいのと、あと、仕様書は単年度ということで、あと、契約内容とかも、私は例えば、週に１５時間というのも、必要に応じて、５年間の途中であっても、これは変更していいのではないかというか、こちらのほうで持ちかけて、それでのんでいただければ、変更も可能なのではないかと思います。どれも大事だと思います。","respondent":"吉田品川図書館長","answer":"具体的には、児童・生徒や教員に対する間接的支援、児童・生徒に対する直接的支援、それから、教育目標を達成するための教育指導への支援という大きな３点、これが役割として果たされるところと認識しています。","voiceIndex":182,"id":"exchange-051"},{"speaker":"安藤委員","kind":"質問・要望","question":"司書教諭というのが今出ていましたけれども、そちらのほうについても伺いたいと思うのですが、学校には、専任ではないのですけれども、司書教諭という方が定められておりますが、その司書教諭の担当課というのはどちらなのかというのが分かりませんが、ぜひそちらのほうで答えていただきたいのですけれども、司書教諭という方は、図書館スタッフと連携して。","respondent":"中谷指導課長","answer":"司書教諭が司書のスタッフの方とどう連携しているかというところですけれども、やはり図書館の専門性が非常に高いという意味では、司書の役割というのは大変重要だと考えていますので、そこの専門的な見地を活かした上での。","voiceIndex":184,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。陳情にもありますけれども、「小・中の教科書では、学校図書館の利用活用・情報活用教育にページがさかれ、授業での活用がもとめられている」ということなのですけれども、そういった点で、区教委としては、この学習指導要領にあるこういった図書館の新たな発展的な役割に照らして、図書館司書、運営スタッフの存在意義というのをどのように考えていらっしゃるのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"その辺の総合的なところで、司書を含めて、学校図書館の運営をしていければと考えているところです。","voiceIndex":186,"id":"exchange-053"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりましたけれども、やはり図書館のスタッフが充実することで、もっと図書館を使った授業というのもすごく充実できると思うのです。指導要領の内容の実施に責任を持っているというのは指導課だと思うのですけれども、そちらのほうから見て、図書館司書、スタッフの役割、存在というのはどのように考えていらっしゃるのか、教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"支援スタッフとどう連携をして、子どもたちへの指導の充実に充てることができるかということが非常に重要になってくるところだと思いますので、たとえ毎日配置がなかったとしても、勤務されている曜日にスタッフとしっかりと連携をしながら。","voiceIndex":188,"id":"exchange-054"},{"speaker":"安藤委員","kind":"質問","question":"ここもまた大事だと思っていまして、子どもの居場所としての図書館の役割、教室には行けないけれども、図書館が開いていれば、集団活動が苦手な子とか、自分の世界で本を読むのが好きだったりすることもあるので、すごく大事だと思うのですけれども、週に２.５日という配置では、そういった子どもが学校に行ったときに、居場所になるような図書館が開いていないという場所、よくあると思うのですけれども。","respondent":"吉田品川図書館長","answer":"学校図書館の開館状況ですけれども、基本的には、支援スタッフのほかにも学校の先生、それから図書委員等含めまして、基本的には開いているものです。","voiceIndex":190,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。ですから、少なくとも週に５日、朝から放課後までは開けておけるという状況が、仕事量からいっても必要だと私は思っています。ただ、私はこの状況ですと、居場所という点でも不十分だと思うのですけれども、居場所として、現状の２.５日で十分と言えるのでしょうか。私は言えないと思うのですけれども、いかがでしょうか。ここも伺いたいと思います。","respondent":"吉田品川図書館長","answer":"学校図書館の利用につきましては、各学校の利用の特色等もあります。各学校から毎年アンケートをいただいている内容も踏まえまして、今後も機会をうかがいながら対応を検討してまいります。","voiceIndex":192,"id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ随時、臨機応変に契約は見直していただきたいのですけれども、今回、一番下になるのですが、見直しということで、５年に一度の、今年見直しをかけまして、今年度から新たな契約がスタートしているわけですが、この新たな契約を結ぶに当たって、様々、要望もありました。議会でも議論がありました。結局、日数、時数は変わらなかったのですけれども、担当課としてはどういう検討を行ったのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"なので、これは頑張っていただきたいと思いますし、契約自体が柔軟に、契約期間としては１年ということでもあるので、相手方にとってみれば、日数が増えるということは、それだけお仕事が増えるということでもありますので、決してマイナスな変更ではないと思いますし、ぜひ来年度からでも、契約の内容、相手方を変えろとは言いません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-058"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこをまず１点教えていただきたいのと、今の話の中で、実質２.５日ぐらい、週１５時間だとそうなると。仮に陳情されている方たちが言われている、毎日いる図書館、５日間になると、どのくらいの予算になっていくのか、分かる範囲で教えていただきたいのと、実際に今、契約をされている委託業者の方たちに、仮に５日間の体制をつくってくださいといったときに、実際、その業者が人的も含めて可能なのか。","respondent":"吉田品川図書館長","answer":"そういう方の中には、これ以上増やせないという方もいらっしゃるのだと伺っておるので、場合によっては、人が替わってしまう、新たに雇用しなければならない、もしくは、今いる人を替えなければならないという状況が発生するということは、昨年度。","voiceIndex":199,"id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何でかというと、１０年後には、下手したら、これからの社会の流れからすれば、本自体が存在しているのかどうかというような話にも発展する可能性があるわけです。五、六店舗あったのです。ただ、一方で、ご答弁いただいた現実的な課題があるというのが今分かったので、そこをどうやって工夫して充実をさせていくかというのは、ぜひ引き続き検討していただいて、いい案を見つけていただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-060"},{"speaker":"ゆきた委員","kind":"質問","question":"ただいま理事者のほうから、学校図書館支援スタッフの委託業者の募集要件で、司書資格を取り入れたというお話があったと思いますが、そのほかにも品川区の学校図書館運営をする上で、質の向上を図る上で、現状の中でどういった工夫、取組をなされているのか、もしあれば、教えていただければと思います。","respondent":"吉田品川図書館長","answer":"質の向上への取組につきましては、年にそう多い回数ではございませんけれども、全体における研修だとか、あとは、各事業者における研修制度、これを毎月やっている事業者もあります。そのようなところで、質の向上を図るというところを現在進めているところでもあります。","voiceIndex":203,"id":"exchange-061"},{"speaker":"吉田副委員長","kind":"質問","question":"他区の状況といいますか、他区の学校の図書館の状況とか、司書の配置状況とか、把握しておられるのでしょうか。もし把握しておられるようでしたら、少し特徴的な、例えば、何々区とか何々市は既に５日間配置しているとか、そうでもない、配置が少ない区もあるとか、品川区の、自治体における、どれぐらいの配置状況なのか把握しておられたら、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"一番多いところは１,５００時間を超えているようなところもありますし、品川区の２倍程度のところも当然あります。品川区は、大体１０番目から１３番目ぐらい、７３５時間につきましてはそのぐらい、真ん中辺りです。","voiceIndex":206,"id":"exchange-062"},{"speaker":"吉田副委員長","kind":"確認","question":"少し曖昧な聞き方で。真ん中ぐらいというのは、要するに２３区に限ってということでしょうか。それを１個確認させてください。","respondent":"吉田品川図書館長","answer":"大変失礼いたしました。２３区中、大体１０番目から１３番目辺りのところの年間委託時間数です。","voiceIndex":208,"id":"exchange-063"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"子どもの教育にかけるということですので、ぜひこの辺は手厚くしていただきたいと思っているのですけれども、ごめんなさい、私、こういう契約の契約金額の算定の仕方がよく分かっておりませんで、総合評価の中で、事業者のほうから積み上げとか、そういうので出てきて、それで決めてしまうということなのでしょうか。","respondent":"吉田品川図書館長","answer":"大きくは４つぐらいに、契約の金額の内訳が分かれます。人件費の部分、これは各事業者における人件費の部分と、支援スタッフにつきましては、ほとんどが人件費の部分になりますので、そちらの金額が、提案された金額がほぼ人件費の中にという形で受け止めているところです。","voiceIndex":210,"id":"exchange-064"},{"speaker":"吉田副委員長","kind":"確認","question":"そうしますと、契約はほとんど人件費ということになるという理解でよろしいでしょうか。確認させてください。","respondent":"吉田品川図書館長","answer":"契約の金額につきましては、ほぼ人件費の金額になります。","voiceIndex":212,"id":"exchange-065"},{"speaker":"吉田副委員長","kind":"質問","question":"人件費と時間数というのはすごく密接に関係してくると思うのですけれども、それは１人当たり何時間の、１時間当たりは幾らぐらいというような形でフィックスされてしまっているという契約のやり方なのでしょうか。ごめんなさい。契約金額、結構大切かと思うので、教えてください。","respondent":"吉田品川図書館長","answer":"会社によっても、当然、単価というのか、１人当たりの金額は異なっている部分でありまして、今回、５つ契約がありますけれども、それに当たっても、それぞれ金額はまちまちです。","voiceIndex":214,"id":"exchange-066"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"分かりました。もちろん人材の母数がたくさんいらっしゃれば、それにこしたことはないのですけれども、そういう現状もある中で、多少、ほかの自治体との競争といいますか、ぜひよい司書、資格はともかく、そういう経験のある方に来ていただきたいと思うのですけれども、その辺についての契約をするときの品川区としての要望とかをどのように話し合っておられるのか、伺いたいと思います。","respondent":"吉田品川図書館長","answer":"先ほどもあった顔見知りのスタッフがいてというようなところもありますので、そういう優しいスタッフというのでしょうか、図書館も含めて、いろいろな意味で知見のあるスタッフというのを準備するよう、事業者にはお願いしています。","voiceIndex":216,"id":"exchange-067"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ぜひ図書館の司書の充実、司書の充実だけではないような気もするのですけれども、その一つとして、図書館が子どもたちにとって行きたい場所、いい場所になるためには、その一つの条件として、司書の配置というのはすごく重要だと思いますので、ぜひ今後前向きに考えていただきたいと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-068"},{"speaker":"せお委員","kind":"質問・要望","question":"児童・生徒が、望む方が誰もが通える、安心・安全に通える区立学校をまずつくっていくことが大事だと思っていますので、もちろん司書の方は今ゼロではないので、こういったところを充実させるというよりかは、先ほどご答弁でも、予算約２.５倍ということのお話もありましたので、そういった予算を、まずは特別な支援が必要なお子さんの支援員などを充実させていただきたいという思いもありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-069"},{"speaker":"ゆきた委員","kind":"確認","question":"学校司書には資格が必要ではない中で、品川区で今年度の募集要件として、司書資格を条件として募集要項に取り入れている点や、学校図書館運営支援スタッフは、司書資格を持つスタッフが５６名中４９名、先ほど８７.５％の方が子どもたちの情報活用教育を支援し、資格司書がいることで、不足部分を補っている点から、質の向上に向けて施策を前に進めていることを確認いたしましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-070"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"それで、ぜひ図書館司書は増やす方向で今後検討していただきたいと考えていますが、やはり今、５年間の総合評価の中の途中の年であるということで、契約は毎年ということですけれども、そこで急に金額を大幅に増やすということは確かに難しいかと思います。私の過去の発言録をたどれば、私の個人の発言については矛盾した発言になっておりますが、そこへのご批判は甘んじて受け止めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":222,"id":"exchange-071"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですが、実現、クリアすべき課題というのは、それはたくさんあると思う。それはどんな課題でもそうだと思うのです。私は学校教育の充実と、子どもにとって何よりも大事なことだと思いますので、ここで採択をして、議会の意思を示して、政治決断を促すべきなのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":223,"id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出す。何学級以上の小学校が幾つとありますけれども、小中一貫校は、２校分なので２人配置されていると伺っています。ですから、そういったことを含めて、２０学級以上云々というのがありますけれども、段階的にというか、毎日というところの趣旨は、いきなりというのはなかなか厳しい部分ではないかと思いますので、今回のこの陳情に関しては不採択としていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"結論を出すで、不採択です。ただ、この充実という部分に関しては、しっかり私は地域の方たちとの連携も含めて、やれることはまだいろいろあるのかと思いますので、その辺に関してはぜひやっていただきたいと思いながらも、今回、この陳情に関しては不採択でよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-074"}]},{"id":"topic-09","title":"教育目標および基本方針の改訂","agenda":"教育目標および基本方針の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これ、教育目標および基本方針の改訂については、いつの教育委員会で審議されて、もう決定済みなのかということというか、そこら辺の教育委員会の中での審議状況などを聞かせていただきたいというのが１つと、それと、この教育目標および基本方針というところに、いつも言っているのですけれども、子どもの権利条約という文言が一言も入っていないというのはいつも違和感があるのですが。","respondent":"宮尾庶務課長","answer":"当然、子どもの権利を尊重するという考え方は、私ども教育委員会には共通して持っている考え方ですが、少なくともこの目標、方針に関しては、特段、改めての表記というのはしていないというものです。","voiceIndex":232,"id":"exchange-075"},{"speaker":"安藤委員","kind":"提案","question":"最後、もう１点質問しますけれども、少なくとも人権というところがあるではないですか。だから、私は、基本方針の１、ここの人権のところに、少なくとも子どもの権利条約という、国際条約ですから、入るべきなのではないかと思うのですけれども、ここだけは最後１点、ぜひ検討していただきたいのですが、ご答弁を伺いたいと思います。","respondent":"宮尾庶務課長","answer":"今回につきましては、繰り返しになりますが、現行のものを継承するというような考え方に沿って行ってきたものですが、子どもの権利条約というところにつきましては、こちらの人権教育を含め、様々な場面で、考え方としては、我々、基本として持っておりますので。","voiceIndex":234,"id":"exchange-076"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。それから、小中一貫教育要領は、一般質問のご答弁にもありましたけれども、これ、２２年に改訂してから、私の記憶では、改訂というか、変更があまり進められてないと思うのですが、そちらについても今後、どのようにされていくのでしょうかということです。","respondent":"中谷指導課長","answer":"すぐにこれに決めていこうというようなスケジュール感ではなく、まず、議論をするというところを軸に置かせていただいておるのですけれども、こちらも行く行くは改訂ということで、中長期的に見る中での見込みとして、そのようなスケジュールで進めしています。","voiceIndex":239,"id":"exchange-077"},{"speaker":"高橋（し）委員","kind":"質問","question":"小中一貫教育要領も一緒にということでよろしいのですか。","respondent":"丸谷教育総合支援センター長","answer":"補足となりますけれども、小中一貫教育要領は平成２２年度に改訂を行いまして、その後、学習指導要領が改訂になった平成２９年、そこに合わせて、品川区立学校教育要領という、名称も新たに変えまして、現在、それを基に教育活動を進めているところです。","voiceIndex":241,"id":"exchange-078"}]},{"id":"topic-10","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の裏面ですが、子育てネウボラ相談、児童センターの中の相談員の方がということですけれども、これ、主な相談の内容というのですか、どんな相談がされるのかというのを知りたいということが１つと、あと、左下のその他の事業の乳幼児ショートステイというのは、令和４年度から始めているわけですけれども、この実績はそれぞれ何件ぐらいあるのでしょうかということと、あと。","respondent":"染谷子ども家庭支援センター長","answer":"センターという建物につきましては、現在、子ども家庭支援センターが１か所と、それから保健センターが３か所、区の中にあるかと思うのですけれども、その中で施設を一体的に運営するパターンと、施設自体は別々ではあるけれども、組織運営上一体的に運営するという。","voiceIndex":252,"id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところというのは、これ、いわゆる子ども家庭支援センターという名前がなくなって、子ども家庭センターになるということなのでしょうかということを確認します。それと、かなりいろいろな事業が、相当利用が伸びているということで、やはりすごく求められている事業ですし、その時々で気軽に相談できるところがある。こういった事業を通して、お考えがあるところを聞かせていただきたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そういった中で、ご自身のお子さんの発育、発達の状況が、ほかのお子さんと比べてどうなのかとか、そういったところに関するいろいろな情報を、意見交換、情報共有したりとかする場が非常に減っているというようなことをお話として伺いますので、そういったところでも。","voiceIndex":254,"id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"先に要望して、最後に質問したいのですが、やはり分かりやすく名称をという話がありましたけれども、抱えないで、あなたは一人ではないのですよと。最後、質問はこれで終わりにしますが、おむつの宅配の事業を新規でやるではないですか。それはこのどこら辺に位置づくのですかというところを最後に教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"おむつの宅配の事業につきましては、保健センター側で実施している事業にはなりますけれども、先ほどご説明をしたバースデーサポートをこちらで実施する、１歳の誕生日を迎えるタイミングで、おむつの宅配については、０歳児が対象になってくる事業かと思いますので。","voiceIndex":256,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問・要望","question":"子ども家庭センターの場合ですと、保健センターという関わりもあると思いますし、やはり子育てしている方からすれば、所管はあまり関係ないので、ぜひこういう切れ目のないネットワークをつくるという中の、０歳の境というのは、どちらが指導するのか分かりませんけれども、しっかりと続けて、横串を刺すといいますか、そういったこともお願いしたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-082"},{"speaker":"ゆきた委員","kind":"質問","question":"妊娠期面談では、オンライン面談が品川区ではありますが、児童センターのネウボラ相談員とのオンラインでの相談は、以前からも文教委員会の中で話が出ていますが、児童センターの子育て相談員とのオンライン面談について、区のお考えがあれば改めてお聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"子育てネウボラ相談員のオンライン面談につきましては、今回、令和７年度の開設を予定しております子ども家庭センターの検討を進める中で、地域子育て相談機関の役割は非常に大きくなってくるかと思いますので、その検討をする中でも。","voiceIndex":260,"id":"exchange-083"},{"speaker":"ゆきた委員","kind":"質問","question":"ぜひ前向きに取り組んでいただければと思います。そこで、例えば、出張型のネウボラという今話があったと思うのですけれども、この出張型のネウボラが、各地域の保育園で定期的に巡回して、保育園のちょっとしたスペースで相談できる場があればという声もありますけれども、この件について、急なのですけれども、区のお考えがあれば、お聞きできればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そういったところ、子育てネウボラ相談員が保育園に出向いて相談をお受けするのか、それとも、そこの保育園自体を相談機関とするのかといったところの考え方があるかと思いますけれども、なるべく多くの方がご相談いただけるような体制というのは。","voiceIndex":262,"id":"exchange-084"},{"speaker":"高橋（し）委員","kind":"意見","question":"切れ目のない子育て支援ですので、そこで切れ目が、妊産婦と子育てネウボラと切れてしまうといけないので、今お話あったように、情報共有は現状では仕方ないのかもしれませんが、できるだけ同じ担当の方というのがうまくいければいいかと思うので、ぜひ今構築していくというお話だったので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-085"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ここに書かれている、例えば、ネウボラ相談だったり、家事・育児支援の利用だったり、件数も上がっていて、成果が出ていると思うのですけれども、これ、いわゆる利用されている方たちというのは、どこでこの情報を入手してここにたどり着いているのかというのを把握されているのか教えていただきたいのと、把握されているのであれば、どの媒体なのかあれですけれども。","respondent":"染谷子ども家庭支援センター長","answer":"例年、利用された方にお答えいただいているアンケートの中で、産後の家事育児支援の利用助成、本事業を知ったきっかけが何かというところの回答につきましては、一番多いのが、母子手帳交付時にお渡ししているパンフレット、こちらで知ったという方が４５％いらっしゃいます。","voiceIndex":269,"id":"exchange-086"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"いきなりずっとホームページを毎日見ないですから、隣の高橋しんじ委員みたいにずっとホームページをチェックして、今日こんな情報がというのはないです、そんな普通の人が。なので、ぜひいろいろな、過剰になるぐらい、特にＳＮＳ世代の人たちなので、やっていただけたら、もっと皆さんがやっていることが役に立つものになってくるのかと思うので、その辺はぜひ徹底していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-087"},{"speaker":"せお委員","kind":"質問","question":"裏面の令和７年度の子ども家庭センターのことなのですけれども、この子ども家庭センターの主な機能の特に1)2)なのですが、相談全般という感じですよね。皆さん時間がない中で、そこが本当に大変で、それはシステムの構築とか、どういった検討になっているのかというのをあえてお聞きしたいです。そちらをお願いします。","respondent":"染谷子ども家庭支援センター長","answer":"現状、保健センター、それから子ども家庭支援センターのほうでご相談をお受けする中でも、やはり医療ですとか、障害者福祉の分野のほうにおつなぎをするようなケースもございまして、そういった場合につきましては、適宜、ご本人の保護者の方のご了承をいただくか、もしくは。","voiceIndex":281,"id":"exchange-088"},{"speaker":"せお委員","kind":"質問・要望","question":"全然違う話で、先ほど来から皆さんのいろいろな支援があって、それぞれ大事なのですけれども、少し分かりにくい部分があったりとかというので、保護者の方からご要望いただいたのが、フローチャートみたいなものがあるというというお話があって、フローチャートまではいかないかもしれないのですけれども、今こういう状態だとか、イエス、ノーとかでやっていただけると、本当に皆さん。","respondent":"染谷子ども家庭支援センター長","answer":"フローチャートという形なのかどうかというところも含めて、検討させていただければと考えています。","voiceIndex":283,"id":"exchange-089"},{"speaker":"吉田副委員長","kind":"質問","question":"先ほどのせお委員のご質問と重なるのですけれども、いろいろ、ネウボラネットワークというのは、制度としては本当に切れ目なくきちんと用意されている。それと同じように、ほかの、直接今関係なくても、割といろいろなところから相談が来るような方たちが欲しいと思ったら、配布できるようなところまでは検討していただけたらいいと思っているのですけれども、いかがでしょうか。","respondent":"染谷子ども家庭支援センター長、藤村子ども育成課長","answer":"先ほど令和７年度開設の子ども家庭センターの説明の中で、一体的運営ということで、具体的には、まずは母子保健と児童福祉の分野ですけれども、こちらを統括するセンター長。先ほど別の委員から、紙のものとデジタルでハイブリッドでというようなお話をいただいたところなのですけれども、紙でお配りしているものが少し多いというようなお話もありますので、そちらについても対応するために、アプリの中で。","voiceIndex":286,"id":"exchange-090"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"どうもきちんとした印刷されたものを見て、それでホームページとかを確認して出ていると、ここは信用できるところだなみたいなのがあって、やはり両方、どちらかになるというのは難しいのだということは、ずっと議論の対象になっていたのですけれども、ぜひその辺の心理といいますか、それも踏まえた上で、より多くの方たちが適切な情報を受け止められるように努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":289,"id":"exchange-091"},{"speaker":"つる委員長","kind":"質問・要望","question":"本当に親としての反省だとか、家庭教育の課題だとか、様々、本当にそういう意味では機能しているということを実感するところと、保護者としての反省だとか、これは複雑な家庭環境とか、家庭問題があるので、詳細は避けますが、今回、子ども家庭センターの中に教育委員会や学校も入った、本当に幅広な体制なので、今、確認させていただいた、そういう常日頃、相談に乗っていただく方に。","respondent":"染谷子ども家庭支援センター長","answer":"都といたしましては、３歳以上のお子さんにつきましては、例えば、幼稚園ですとか保育園ですとか、３歳以上になると、いずれかの所属ですとかに接点を持つというところがありまして、それ以前のお子さんに関しては所属がないという家庭も結構ある中で。","voiceIndex":294,"id":"exchange-092"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5114#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":81669,"voices":298}},{"id":"r05-20231127-5","meetingId":"r05-cm11","date":"2023年11月27日","dateIso":"2023-11-27","committee":"総務委員会","time":"午前１０時００分～午前１１時１３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","agenda":"冒頭に申し上げましたとおり、取り上げる順番を変更して行います。 まず、(2)第８５号議案、浜川小学校校舎・幼稚園園舎改築その他工事請負契約の変更","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"一般質問でもさせていただきましたが、公共建築物ならびに設備工事に関して、適宜インフレスライド条項を適用してやっています。今回のこの議案に対して反対はしませんが、ただ、他の産業も、やはり物価高、それから人件費高騰ということで、建設業者、設備業者と同じような状況になっていますので、今後、そういう産業、また、そういう事業者に対しても平等な対応を行政としてとるべきだと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"これはこれでいいと思っていますけれども、お伺いしたいのは、多分これは大変ご苦労いただいて、皆さんも業者の方といろいろ交渉していただいて、なるべく当初の金額からあまり上がらないような形で交渉していただいているのだろうと思っています。上がるときは、いろいろ資料をとっても、相当上がる上がるばかり出てきているのだろうと思っています。","respondent":"小林施設整備課長","answer":"使用資材の単価のご質問ですので、私のほうから一括してご説明いたしますが、今、委員からご指摘がありましたとおり、品川区の単価につきましては、基本的には東京都の単価を使わせていただいておりまして、その情報につきましては、月に１回必ず。","voiceIndex":7,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"意見","question":"ここで５％というと、多分利益がそっくり上がっている感じ。多分これぐらいの規模になると、５％取るのもやっとだと思います。だけど、それはそれで非常にぎりぎりの話をしているのだろうから、そういうお互いぎりぎりの中でやっているので、ぜひそこら辺はよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"すみません、あともう１点だけですけれども、一般の工事業者・建設業者は、民間では、最初に見積り、請負契約をしたら、そのまま値上げしてくれるということはほぼありません。ですから、清水建設が大きな売上減になったとか利益がすごく落ちた、様々な建設業界でそういうことが起きているということは、私はやはり自治体としてもそれは捉えていてほしいと思います。それだけ民間は苦労してやっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"スチームコンベクションオーブン他の買入れ、民間では非常に高額なものだと聞いております。ただ、いろいろな利点があって、合理化も、人件費も削減できるということですが、かなり高額だと思うのですが、今の様々な小中学校においても、このような設備というのはどんどん導入されているのでしょうか。お聞かせください。","respondent":"柏木学務課長","answer":"給食設備の関係ですが、今回契約しております機器につきましては、学校給食法に基づき定められている学校給食衛生管理基準にのっとりまして整備しているものですので、ほかの学校についても同様のものが整備されているものです。","voiceIndex":24,"id":"exchange-005"}]},{"id":"topic-02","title":"第７７号議案 品川区組織条例の一部を改正する条例","agenda":"第７７号議案 品川区組織条例の一部を改正する条例","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"総務部が区長室となり、税務課が企画経営部に移管されますけれども、区税に関することという中で、ふるさと納税に関することを行っていくと思うのですけれども、具体的にはどのようなことを職員の方はされるのでしょうか。","respondent":"佐藤（憲）企画課長","answer":"先日の決算特別委員会でも様々ご指摘を受けている面もありますので、既に検討や、来年度予算の検討もしているところですが、来年度、企画経営部というところで、企画経営部長の配下として、企画課と財政課がいる部の中に税務課も来ていただいて。","voiceIndex":47,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"それから職員の方も、仕事ですからそれぞれ割り振られたところはやるのでしょうけれども、こういうふうに細かく分けてきた根本的な理由を教えてください。そして、それぞれ改正してから課がかなり増えているのかなということは、それぞれそこに課長が今度配置されるわけですから、その課長もやはり相当増えて、何か所くらい増えたのか。","respondent":"佐藤（憲）企画課長","answer":"条例改正の理由にもありますが、新たな課題ということで、少子化、経済支援、コロナ後の体制強化、ＤＸ推進等々、行政課題は様々増えて多様化しておりますので、そういった課題に適切に対応していくために、組織を再編して、来年度以降、適切に対応していきたいと考えております。","voiceIndex":51,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、細分化されて区民サービスという意味では力を発揮されるのかもしれませんが、片や、そういう課長級が増えてくると人件費が逆に増えてくるという、片一方は区民サービスだけど、片一方は、品川区でも行財政改革をやっていますけれども、こういうふうに予算が増えていくという、そこら辺もいろいろ検討しながらやっているのですか。その辺、教えてください。","respondent":"佐藤（憲）企画課長","answer":"そういった状況でもありますので、コロナ後の様々な課題、区民のニーズも多様化しておりますので、そこに対応するために、人件費率も見ながら、適切に人員増も図りつつ、行革も行いながらバランスよく進めていきたいと考えております。","voiceIndex":53,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ区民に分かりやすい、迷わないような取組は、今までどおりしっかりやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-009"},{"speaker":"松本委員","kind":"意見","question":"今の須貝委員のところに追加で、数字が出てこなかったのであれなのですが、人件費はどれぐらい増えるのか、多分そろそろある程度出ているのかなと思うのですけれども、そこの数字をお示しいただければなと思います。","respondent":"佐藤（憲）企画課長","answer":"課長級ポスト増に伴う人件費ですが、詳細な資料を今持っていないのですが、１人１,０００万円として、ポストが８増ですので、８,０００万円。そこまで詳細な数字が今手元にないです。申し訳ございません。","voiceIndex":57,"id":"exchange-010"},{"speaker":"松本委員","kind":"質問","question":"これは総務委員会でせりざわ委員長のご専門のところかと思いますけれども、やはりふるさと納税をどうするのかというのが一つ大事なところかと思っておりまして、移管は移管として１つの効果かと思いますが、ただ、移管するだけで、果たしてこれまでなかなか戦略的な対応がとれていなかったふるさと納税が、この間も世田谷区のほうでまた別の動きというか新しい動きとかがいろいろ出てきている中で。","respondent":"佐藤（憲）企画課長","answer":"ご案内のとおりこれまで総務部に配置していたところで、税務課としては基本的にふるさと納税には反対しつつもというところのスタンスでやっていたところですが、企画経営部に移管して、先ほどお伝えしたとおり、全庁的な視点と、税務課、企画経営部だけではなく。","voiceIndex":60,"id":"exchange-011"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば地域産業と連携するという視点とかもふるさと納税の場合はあると思うのですけれども、そこは企画経営部という、どちらかというと全体を見ることができるので、そちら側で各所管課と調整するような枠組みを考えていらっしゃるということでよろしいでしょうか。","respondent":"佐藤（憲）企画課長","answer":"ふるさと納税に関するご質問ですが、地域産業、あと福祉施策ですか、子ども食堂のように区民の方がより参加しやすいものについても横串を刺して、企画経営部が中心になって進めていきたいと考えております。","voiceIndex":62,"id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"人件費の部分はそれでそうだと思うのですけれども、課の数というのは、２３区、他の区と比べたらどうなのでしょうか。今回、新設する課が８あるということで、課は増えると思いますが、それは他区と比べると、どういうふうに考えたらいいでしょうか。","respondent":"佐藤（憲）企画課長","answer":"他自治体と比べた課の数というところです。今はっきりした数字でお示しできないのですが、２３区の課長職の情報については、我々の方でも分析しておりますが、ざっくりな感覚で申し上げるのですが、品川区の課の数は比較的少ない自治体なのかなと考えています。","voiceIndex":64,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問","question":"課が８課増えて、部長級も、清掃事務所のところが部長級から課長級になったということで、今、部長をやられている方はどうなるのかなというのが一つと、あと、人材育成についてですけれども、８課増えるというところでいうと、課長級をやってもらう人の人材を確保するのはどうするのかというので、今、既に区のほうでも課題だというところで、さらにまた増えていくといったときに。","respondent":"佐藤（憲）企画課長","answer":"３点目の人材育成をどうするのかですが、これは従来から人事課のほうでもお話しされていますけれども、人材育成基本方針を今改定している中で、また、予算編成も今しておりますが、研修の在り方をどうしていけばより人が育っていくのかということを含めて。","voiceIndex":67,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"１点、総務部が区長室というふうに名称が変わって、今でも組織としてはトップは区長でとやっている中で、ここに区長室というものが入ってくることの意義とか、区長室の中に様々な部分が、特に広報なんかは、ブランディングにおいて区長が全面に出ながら様々発信していくとかというところでは、区長のところに大きく課が寄っているように見えるのですけれども。","respondent":"佐藤（憲）企画課長","answer":"区長室は、その組織をベースに、これまで以上に区長が先頭に立って進める組織として想定しております。今回は情報発信やコンプライアンス対応の強化を図る組織を新たに配下といたしまして、区長の意向をより踏まえた区長視点で動く組織として想定しているところです。","voiceIndex":69,"id":"exchange-015"},{"speaker":"大倉委員","kind":"提案","question":"柔軟に、どのぐらい、スクラップアンドビルドとかを進めていくというところでは、そういう意味では、区長も、提案を様々していきながら、区長の判断で動いていく可能性も大いにあるというところや、これは一定期間、事業として効果を得られたので、これはもう終わりにしましょうとかという判断も、区長がスピード感を持ってとか、何かの判断をしながら進めていくという認識でいいのかだけ教えてください。","respondent":"佐藤（憲）企画課長","answer":"区長室設置に伴うスクラップアンドビルドと、区長の判断で進めていくですが、事業のスクラップアンドビルドは今年度から事務事業評価を行っておりますので、企画部のほうで主体的に取りまとめをしながら進めていくという基本線は変わらないところであるのですけれども。","voiceIndex":71,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ、大倉委員が切り出してくれたのですが、人事課長にお聞きしたいのですけれども、我々が聞いているのは、課長の成り手がいないという話、よく庁内でそういう話が出ていると聞くのですが、こうやって増やしていくのは大丈夫なのですか。そうすると、今後さらに次の担い手、次の課長、またその次の課長というのが、今度そろわなくなったら、また縮小するようなことになっていくのですか。","respondent":"崎村人事課長","answer":"管理職の担い手の確保といったところについては、来年度から役職定年制が導入されるということもありますので、管理職選考の受験勧奨ということについては、人事課としても非常に強く意識して実施していますし、先ほど企画課長からご答弁させていただきましたけれども。","voiceIndex":74,"id":"exchange-017"},{"speaker":"松本委員","kind":"意見","question":"すごく細かいところですけれども、資料を見ると、人権啓発課のフォントが小さくなっているのですが、これは何か意図があるのか。１０ポイントぐらいなのが９ポイントぐらいになっているのは、何か意図があるのか、全くないのか。","respondent":"佐藤（憲）企画課長","answer":"人権啓発課のところですが、見づらいポイントで大変申し訳なかったのですが、現在、組織のほうは引き続き検討中といいますか、今回は、条例改正のところで分掌事務と部名についてですが、課に関しては今検討中でございまして。","voiceIndex":77,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問","question":"その目的は何ですかといったときに、区民の幸福（しあわせ）ですということなのだろうと思います。全国でもそんなにないと思っていて、初めてみたいなことをやるときに、これ、初めては別に何でもいいのです、私は初めては結構好きなほうなので、やっていただくのは構わないけれども、ウェルビーイングという部分と、区民の方にもっと期待してください、この組織改正でというのを、もう少し説明してほしいな。","respondent":"佐藤（憲）企画課長","answer":"今回、組織のご提案ですけれども、ウェルビーイングをどういう系統にして、戦略的にどう進めていくというところに関しましても、区として、企画経営部として、見せ方も含めて検討して、しっかりお伝えしていかなければならないと考えていますので、適宜適切にまたお示ししながら。","voiceIndex":80,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか具体的に答弁いただきたいのは、区民向けに期待してくださいとここで強く言うのか、区長が言っているのも分かって、さっき言ったように分かっているのだけれども、期待してくださいというのを全面に押し出すということでやっていきますよということ。せっかくこうやっていいことをやるのに、もう少し丁寧にやってもらわないと、あまりに軽視し過ぎではないかなと思っていて、そこら辺も答えてほしいな。","respondent":"佐藤（憲）企画課長","answer":"一方、委員ご質問の議会に向けてですが、先ほどの答弁と重なる部分がありますけれども、体系的にどう進めていくのかというところは今しっかり検討していますので、そういったものがしっかり固まった時点で、第１回定例会の施政方針になるのかどうかはあれですけれども。","voiceIndex":82,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはいいのだけれども、将来にわたって、２年後、３年後見ていてくださいと。私は職員の方々が、ウェルビーイングでも、同じ意識を持ってやらないと、とてもではないけれどもできないし、それがこういう心得とかそういうことだと、私は多分、少なくとも１年、半年でもいいけれども、まず止まるような気がしてならないので、そこは答弁は要らないので、ぜひそういう人材育成をしてほしいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-021"},{"speaker":"塚本副委員長","kind":"質問","question":"そういう中でいうと、ＳＤＧｓ推進だとか、さっきちょっと話題になっていた廃棄物の資源循環推進担当課長とか、こういうのは、どこかがゴールとか、いつ終わるとかというところではなくて、経常的にあるような作業というか仕事だと思うのですけれども、担当ということにするのか、何の課というふうにするのかというところの判断は、どういう考えに基づいているのかというのを最初にお伺いしたいと思います。","respondent":"佐藤（憲）企画課長","answer":"課長と担当課長の違いだと思いますが、委員からご紹介がありましたプロジェクト型というのもありますけれども、その課題により迅速かつスピード感を持って形にするというところに関しても担当課長というところで、部下を何人かつけながらも。","voiceIndex":86,"id":"exchange-022"},{"speaker":"塚本副委員長","kind":"意見","question":"そうすると、先ほどの石田秀男委員のお話とも関連しますが、ミッションが終わったときに、次のステップというところで、コストみたいな話になりがちです。その辺のところは、現在、どのぐらい検討されていますか。","respondent":"佐藤（憲）企画課長","answer":"今回ご提案している担当課長も含めまして、コロナ禍で生じた新たな課題、様々な課題に行政としてしっかり対応していくというところですので、まずは着手して、来年度、様々な実施計画ごとの改定も予定されていますので、その中で進捗を確認しながら。","voiceIndex":88,"id":"exchange-023"},{"speaker":"塚本副委員長","kind":"質問","question":"イメージとしてはここが区長直轄の事業というか政策を担っていくのだというふうにも普通は捉えるわけですけれども、そういうことで、いわゆる区民に対するメッセージ、区長としてここを直轄で力を入れて推進していくのだというメッセージが込められているという捉え方でよろしいですか。","respondent":"佐藤（憲）企画課長","answer":"区長直轄といいますか、区長の権限は区長部局全てにわたるところでございまして、今回、情報発信やコンプライアンスの組織も配置して、区長がそういった区長室というところで掌握をより高め、区長の意向をより踏まえて、区長視点で動く組織ですので、区長室だけ特化して直轄とか。","voiceIndex":90,"id":"exchange-024"},{"speaker":"塚本副委員長","kind":"質問","question":"ちょっと細かいというか、突っ込んだ話になりますが、例えば区政運営会議とかをやっているではないですか。そういう方々もやはり今までと同じように、区政運営会議とか何とかということで、意思決定の手続というか、スキームというか、そういうものは総務部時代とあまり変わらないのか、やはりそこは区長室なのだから、区長裁決で進めていくみたいな感じになるのかというのは、いかがでしょうか。","respondent":"佐藤（憲）企画課長","answer":"今まで区政運営会議という形で月２回ほど実施しておりまして、その運営の仕方を変える予定はございません。","voiceIndex":92,"id":"exchange-025"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"毎回言っていると思うのですが、インフレスライド条項は、今回も第１回・第２回変更ということになります。こういう仕組みがあるならば、他の産業においても平等な対応をしていただけたらありがたいなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-026"}]},{"id":"topic-04","title":"専決処分の報告について（報告第３５号）","agenda":"専決処分の報告について（報告第３５号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライドは、他の産業にも平等な対応をしていただきたい。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-027"}]},{"id":"topic-05","title":"専決処分の報告について（報告第３６号）","agenda":"専決処分の報告について（報告第３６号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"インフレスライド条項は、ここに適用されているなら、他の産業にも平等な対応をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-028"}]},{"id":"topic-06","title":"専決処分の報告について（報告第３８号）","agenda":"専決処分の報告について（報告第３８号）","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"今回は排水施設の設置の取りやめによる変更もありますが、やはりインフレスライドに対しては他の産業においても平等な対応をしていただきたい。今回、ほとんどみんなインフレスライドで請負契約が変更されるというのは本当にまれな例だと思いますが、早く解消していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2282#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24468,"voices":130}},{"id":"r05-20231128-6","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"区民委員会","time":"午前１０時０７分～午前１１時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"施設予約システムのリニューアルに伴う運用変更等","agenda":"施設予約システムのリニューアルに伴う運用変更等","exchanges":[{"speaker":"横山委員","kind":"質問","question":"ご説明、ありがとうございました。何点か伺っていきたいと思うのですけれども、オンラインクレジットカード決済を導入するということで、利便性が向上してすばらしいなと思っているところなのですけれども、こちらは手数料といいますか、ランニングコストみたいな部分が今までとこれからでどういった形で変わってくるのかというところを教えてください。","respondent":"横田情報推進課長","answer":"ある意味、機能の一つとしてこういうものができたということになります。続きまして、５月１３日から１４日ですが、システムのリプレースということで、最終的なデータ移行などを行いますので、そのときはシステムの利用停止ということを予定しております。","voiceIndex":7,"id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"メールの件は、お休み等、何かあったときに送信ができるというのは、区のほうから利用者にという形で、一方向でそういったことができる機能がシステムとしてできるという認識で合っていますでしょうか。確認だけお願いします。","respondent":"横田情報推進課長","answer":"おっしゃるとおりです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問","question":"理解いたしました。様々な機能が付加されてすばらしいなと思うのですけれども、例えば、５月１３日から１４日の切替えのときにキャンセルをしたくて、それが１か月前のぎりぎりといったようなケースも、もしかしたらあるかもしれないのですけれども、利用停止の間の対応というのは区としてどうされるのかというところをちょっとお聞きしたかったので、そちらの補足をお願いできればと思います。","respondent":"横田情報推進課長","answer":"今現在この辺りはどうすべきかとちょうど詰めているところでして、決まり次第またご報告させていただければと思いますので、よろしくお願いします。","voiceIndex":11,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"皆さん、最近ホームページからですとか、ＤＸ化に慣れている方もいらっしゃるかと思うのですけれども、もし何かあったときに、お電話の対応ですとか、メールでの対応ですとか、利用停止の期間も含めて、どうやってフォローするかというところもしっかりと留意していただいて、ぜひ今後の周知、そして５月からの新しいシステムの切替えというところでランディングさせていただきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"実際利用している側として、具体的なというか、細かいことを伺いたいのですけれども、今私も集会場とかをお借りして、きゅりあんの会議室等をお借りしたときに、オンラインで予約をして、中小企業センター等にお支払いに行くという手続きを踏んでいたのですけれども、これからはクレジットカード決済ができるということなのですけれども。","respondent":"篠田文化観光課長、横田情報推進課長","answer":"現金のお取扱いに関しては、クレジットカードでのお支払いができるというのが一つ新しい取組であります。当然クレジットカードをお持ちでないお客様もいらっしゃいますから、現金の取扱いは、今後も変える予定はございません。領収書の件ですが、今手元に資料がございませんので、確認してまたご報告します。","voiceIndex":14,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"会計上の話で恐縮なのですけれども、現金であれば当然、現金に名前はついていませんから、団体の名前でしっかりと領収書が出るのですけれども、これがカードになった場合に、個人名が出ると、会計上またちょっとややこしいことになる可能性があるので、その辺りは利用者側の都合に合わせた形でしっかり領収書が出るような仕組みにしていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"えのした委員","kind":"意見","question":"学校施設も予約でオンライン化することで、より一層区民の利便性向上につながると思っていますけれども、２の主な変更点の(2)、オンラインクレジットカード決済を導入する。","respondent":"横田情報推進課長","answer":"今後につきましては、システム事業者とかキャッシュレス事業者と区で、３者でできるような形で調整していく予定になっております。時期については未定なのですが、そのように考えています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れましたので、安心しました。そういった取組を進めていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"山本委員","kind":"質問","question":"システムを抜本的に見直されたというところでいうと、当時の課題がいろいろあって、それを踏まえて変えていかれるというアプローチをされたのだと理解しているのですが、どういった形で抜本的見直しなのかというのをちょっとお伺いしたいというところと、あとクレジットカード決済を導入して。","respondent":"横田情報推進課長","answer":"３点目のキャッシュレス対応ですが、取り急ぎ５大国際ブランドのクレジットカードに対応しつつも、今後ＱＲコードといったものにも対応できるように少し改善していければというふうに考えております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"山本委員","kind":"質問・要望","question":"このようにお伺いできてとてもよかったなと思います。そういうふうに対応していただいているということを、変更をご案内するときにも、ぜひ併せてご案内いただいて、区として住民目線でそういった見直しを図っているということを言っていただくことが、区民の方に寄り添って対応しているということを示していくことになると思うので、そういったことをしていただきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"せらく委員","kind":"質問","question":"支払い方法についてなのですけれども、オンラインクレジットカード決済を導入して、現金払いも残しながら、今ある口座振替というのも残されるのでしょうかということをお聞きしたいのと、あとこちらのシステムリニューアルが、令和４年度にリニューアルの会社をプロポーザルで決定されたということなのですけれども、令和４年度の時点でリニューアルの予算が組まれていたということなのか、お聞きしたいです。","respondent":"三井スポーツ推進課長、宮澤地域活動課長","answer":"公園の施設につきましては、口座振替の登録をしておりますので、今後も残していく予定にしております。令和４年度にプロポーザルで事業者を選定しましたが、このリニューアルに向けた予算については、令和５年度に予算を計上しております。ですので、契約は令和５年度になってから契約をしたです。","voiceIndex":24,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"施設予約システムですけれども、まず何で中小企業センターは、ここに参加していないのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"ですので、中小企業センターも含めて、幅広く施設予約システムの対象施設だというふうに認識しています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"藤原委員","kind":"質問・要望","question":"すみません。よく分からないです。中小企業センターも施設がありますよね。入っているのだけれども、最初の説明で入っていないとか、でも入っているのですとか、よく分からないので、具体的に教えていただきたいです。","respondent":"宮澤地域活動課長","answer":"すみません。私の最初の説明が分かりづらかったかと思います。この予約システム自体は１１課にまたがって様々な所管がこのシステムを統一で運用しております。その中に中小企業センターも入っております。","voiceIndex":29,"id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"地域活動課長が説明してくれれば、もうそれで分かるでしょうということだったということですか。次がすぐに入ればいいですけれども、そうすると、７日前にいろいろ計画したりとなるのは、ある意味、主催者側からは本当に厳しい面もあると思うのですけれども、その辺についてどういう声があったのか、背景でこういうふうになったのか、また分けたのかという点についても説明していただけますか。","respondent":"宮澤地域活動課長、篠田文化観光課長、三井スポーツ推進課長","answer":"施設につきましては、中小企業センターも含めて説明させていただいたというところで、失礼いたしました。２つ目のところです。使わなくなったのだけれども、７日前までで全額返ってくるのだったらということで、そういった連絡をなかなかいただけないということも考えられます。区立体育館につきましても、特別な取扱いが残っているところについては指定管理者施設ということで、施設利用料収入に影響が出るということ。","voiceIndex":31,"id":"exchange-014"}]},{"id":"topic-02","title":"住民基本台帳事務における「特定個人情報保護評価」の実施","agenda":"住民基本台帳事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"えのした委員","kind":"確認","question":"今の個人情報保護委員会、品川区のホームページに「特定個人情報保護評価について」と、令和３年にページができていて、そこからその委員会のサイトに飛ぶようになっているのですけれども、この第三者点検というのは、例えば、そういった委員会が点検するのか、どのような団体が点検するのか、そこだけ確認させてください。","respondent":"吉野戸籍住民課長","answer":"こちらは個人情報保護委員会とは直接全く関わってはいないところなのですけれども、品川区個人情報保護審議会の委員になります。実際に特定個人情報保護評価の概要と説明も、この評価が正しいかどうかというところで、第三者委員の方に評価していただくような形になります。","voiceIndex":44,"id":"exchange-015"},{"speaker":"えのした委員","kind":"確認","question":"品川区にもそういった委員会があるということで、確認が取れました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-016"},{"speaker":"せらく委員","kind":"質問","question":"１２月１日からパブリックコメントの実施という予定なのですけれども、区民意見の聴取ということで、何に対しての区民の意見を聴取するのかよく分からなくて、教えていただければと思います。","respondent":"吉野戸籍住民課長","answer":"実際にこのファイルがどのように使われていて、皆さんの情報をどのように使っています、リスクに対してはこういったリスクに対応していますというところが全て書かれたものになりますので、見ていただくことは本当にたくさんあるかなと考えています。","voiceIndex":48,"id":"exchange-017"},{"speaker":"せらく委員","kind":"質問","question":"評価書をご覧いただいて、その上で意見を聴取するという形になるのですか。","respondent":"吉野戸籍住民課長","answer":"そのとおりです。","voiceIndex":50,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"全体像が分かりにくいところがあったので、ちょっと確認させていただけたらと思うのですけれども、まず、そもそも国から令和７年度中でしたか、２０２５年度中にガバメントクラウドを活用した標準準拠システムの移行を目指して、移行作業が円滑かつ安全に実施されるということを求めているのかなと思うのですけれども、その中で住民基本台帳事務における特定個人情報保護評価を、今回の評価書を修正する。","respondent":"吉野戸籍住民課長","answer":"それ以外に、例えば、大きなシステム改修であったり、今回これは標準化、ガバメントクラウドへの移行なのですけれども、こういったものが５年前にあったというところで、今回はこういった評価をやらなければいけないという形になっております。","voiceIndex":52,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問","question":"今のご説明だと、もともと評価書というものが品川区のホームページに公開されていますよね。それが５年前につくられたので、評価のタイミングであるという理解でよろしいですか。","respondent":"吉野戸籍住民課長","answer":"実際には前回の評価は令和２年ではあるのですけれども、今回の標準化システムは令和７年１月に開発をしなければいけませんので、それに合わせて少し前倒しで全体の評価をやっているという次第です。","voiceIndex":54,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問","question":"システムの移行に向けて、５年に１回というものではなくて、システムの移行に対して修正する部分もあったりして、前倒しをする必要があるので、令和２年に行ったばかりですけれども、このタイミングで修正を実施するということで、修正内容としては、移行のために修正しなければならないことがあるので、今後修正の細かい項目というのを、今、精査したり、検討していただいているのかなと思うのですけれども。","respondent":"吉野戸籍住民課長","answer":"今回はシステムの改修があるので実施するということになります。それがなければ、５年に１回で、そのときには内容が変わっていなくても、必ず５年に１回はあります。ただ修正がある場合には、その都度実施することになります。","voiceIndex":56,"id":"exchange-021"},{"speaker":"横山委員","kind":"質問","question":"そうしましたらシステム移行に伴って、品川区だけではなくて、ほかの自治体もいろいろ修正しなければならない事項というのが恐らくあると思うのですけれども、その辺りは国等から指導であったり、相談しながら、項目と修正項目を見直していただいている作業を、今進めていらっしゃるということなのでしょうか。","respondent":"吉野戸籍住民課長","answer":"そういったデータ項目がこう変わりましたとか、そういった内容が全て網羅されたような形になります。そういった意味でいきますと、全体の項目が出ているようなイメージになります。","voiceIndex":58,"id":"exchange-022"},{"speaker":"横山委員","kind":"質問","question":"そうすると、ガバメントクラウド等の利用によって、システム全体が移行することによって、特定個人情報保護評価の考え方とか、内容が大きく変わるということではなくて、例えば、ファイルの場所みたいな、細かいところで修正がいろいろ必要なので、置き換えというか、今はガバメントクラウドを利用していないので、例えばＡというところに書いてあるけれども、ガバメントクラウドを利用することになると。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおりでして、今回主な修正項目を３に記載しています。","voiceIndex":60,"id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今、個人情報保護という言葉が独り歩きして、決算特別委員会のときも申し上げましたが、住民基本台帳法上の情報を町会・自治会等に提供するのが難しくなったというようなこともありますけれども、関心は非常に高いという中で、区としてはこういうことをしっかり、適正なプロセスにのっとって手続きを進めているということを示すいい機会でもありますので、そこについては、同じ答弁になってしまいますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、標準準拠システムに移行していくことで、令和７年度に向けてやっていくことで、特定個人情報保護評価を実施しなければいけないと。いいですよとか、全然駄目ですよとか、評価書に対しての評価がまた返ってくる形になるのか、そして評価書も含めてパブリックコメントもするということなのですけれども、それは全てが公開されるということでいいのか、伺います。","respondent":"吉野戸籍住民課長","answer":"窓口でどういった会社でどういった内容を委託していくのかというのを記載しております。特定個人情報保護評価の回答なのですけれども、問題ありませんというような回答をいただいてから、公表する形になります。","voiceIndex":65,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"分かりました。先ほどあくつ委員からもありましたけれども、前回は０件で、そうだろうなという思いです。特定個人情報保護評価をするに当たってはパブリックコメントもやらなければならないというふうに入っているものなのですか。取りあえずやっていますという感が否めないのですけれども、そこの確認と、もうちょっと分かりやすくできる工夫というのを区として検討しないのか、伺いたいと思います。","respondent":"吉野戸籍住民課長","answer":"住民基本台帳は４０万人というところで、３０万人以上の場合はこういった第三者点検とパブリックコメントは実施しなければならないということが規定されております。それ以外に関しましては、任意になっております。","voiceIndex":67,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"なかなか分かりづらい部分でもありますけれども、本当に個人情報は大事な部分で、そしてそれが国のシステム標準化で変わっていくことになるので、そこは丁寧にしていただきたいなと私も要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-027"}]},{"id":"topic-03","title":"顔認証マイナンバーカードの開始","agenda":"顔認証マイナンバーカードの開始","exchanges":[{"speaker":"横山委員","kind":"確認","question":"１点だけ伺わせてください。顔認証マイナンバーカードで、うまく認識できないというような事例があるのかなと思うのですけれども、どういう事例があるのかというのと、その場合の対策についてどのように考えられているのかというのを確認させてください。","respondent":"吉野戸籍住民課長","answer":"医療機関等で実際に使うときに、顔の写真を撮って、それと整合がつかないときがありまして、それでうまく読み取れないというような形になります。そういった方がもし健康保険証として利用される場合には、顔認証の場合には、券面の写真と住所を確認して目視での確認になります。","voiceIndex":74,"id":"exchange-028"},{"speaker":"横山委員","kind":"質問","question":"私の聞いた事例だと、髪の毛がちょっと目にかかっていたりするとこのシステムは認識しづらいみたいな形で、そういったところもあるような話を聞きますので、うまく認識できない事例というのをちょっと捉えていただいて、なるべく認識しやすいような写真を使っていただくとか、そういったご案内というのもしていただくといいのかなと思っているのですが、その辺りはいかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"確かに最初にカードをつくるときに、正面であったり、例えば車椅子であったりが映ってしまう場合もあるのですが、そういったときでもやはり顔の目と鼻と口の部分が認識できればできるような形になっておりますけれども、実際にいざ認証するときに。","voiceIndex":76,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"顔認証マイナンバーカードの仕組みなのですけれども、現在保持している人で希望する方となっているのですが、新しいカードを発行するのではなくて、今あるカードを、総務省が発行している資料、ちょっと前の８月の資料ですけれども、それを見ると、暗証番号をロックするというような形を今考えていますということで、いわゆる暗証番号等を使わなくても、医療機関、薬局に情報提供することができるようになる。","respondent":"吉野戸籍住民課長","answer":"今回のカードが実装する意味なのですけれども、病気や体が不自由な方、マイナンバーカードの暗証番号の管理がとても不安な方がいらっしゃるという声が上がりまして、そういったところを解消するために、顔認証マイナンバーカードが導入されたという経緯になっております。","voiceIndex":78,"id":"exchange-030"},{"speaker":"あくつ委員","kind":"意見","question":"経緯は分かるのですけれども、仕組みとしてこれから先、１１月２７日と書いてあるから、あれ、もうスタートしているのかなと私もホームページを見たら、特に何も載っていなかったので、先ほど訂正があったのですけれども、これから希望する方というのは、例えば私が顔認証マイナンバーカードを使いたいと思ったときには、現在持っているマイナンバーカードを持って行って。","respondent":"吉野戸籍住民課長","answer":"失礼いたしました。先ほどの開始時期の、対応可能窓口のところで書かせていただいたのですけれども、顔認証カードの交付であったり、あと切替えのところです。","voiceIndex":80,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"印字をするということは分かったのですけれども、先ほど私が申し上げたような、いわゆる電子的なロックをかけるということではないということですか。","respondent":"吉野戸籍住民課長","answer":"電子証明書を使えなくするロックをかけます。","voiceIndex":82,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"その手続きについては即日でできるし、簡易だということは今、確認させていただきました。今日の所管からは少し広がった話になってしまいますが、今回国からこういうような通知が来ておりますけれども、品川区として、昨年は行政書士を活用した申請サポート事業を行いましたけれども、今年、来年度を含めて、そういったこともご検討されているのか教えてください。","respondent":"吉野戸籍住民課長","answer":"今回の顔認証マイナンバーカードなのですけれども、施設の施設長、高齢者施設であったり、障害者施設の方からも、暗証番号の管理がとても難しいというお声が上がった経緯もあると考えています。","voiceIndex":84,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"確認","question":"それともう一点だけ確認です。これは高齢者とか障害者の所管になってしまうのですけれども、こういったところについて周知ができているのかどうかというところを最後に確認させてください。","respondent":"吉野戸籍住民課長","answer":"委員ご指摘の疎明資料なのですけれども、出頭困難な方に対しましては、施設長であったり、ケアマネージャーの方に署名していただくと顔写真で代理申請、それから代理受領というのが可能ですので、そういったところは高齢者等の担当と連携を取りながらやっているところです。","voiceIndex":86,"id":"exchange-034"},{"speaker":"えのした委員","kind":"質問・要望","question":"ご説明、どうもありがとうあります。例えば、機械が停止したり、故障したというときに、目視による顔確認、ただデジタルなのに、ＤＸなのに目視なのかというところもあるので、ご担当者が万が一間違えたとか、責任だったり、リスクだったりがあると思うのですけれども、その辺は区独自で何か対策として考えていることなどがあればお聞かせいただきたいです。","respondent":"吉野戸籍住民課長","answer":"先ほどお伝えしたとおり、これ自体は国のシステムとつながっておりますので、区として機器を提供するとか、そういった独自のものは、現在は考えておりません。","voiceIndex":88,"id":"exchange-035"},{"speaker":"えのした委員","kind":"確認","question":"窓口での目視の場合に、やはり人間がすることですから、ヒューマンエラーではないですけれども、違う方と見間違えるということは、そうないとは思うのですけれども、万が一のことを考えた場合に、区としてその辺は何か、１人だけで確認するのではなくて、２人で確認するとか、何かそういったことは。","respondent":"吉野戸籍住民課長","answer":"委員のご指摘のとおり、本人確認というのはとても大切なことですので、私どもの窓口では確かに１人ではなくて、数人で確認しております。医療機関のほうにもそういった呼びかけをしていきたいと考えています。","voiceIndex":90,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2976#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":24135,"voices":97}},{"id":"r05-20231128-7","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"厚生委員会","time":"午前１０時０８分～午後 ３時２７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を85件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","agenda":"を聴取したいと思います。 初めに、(1)「品川区障害者計画及び第７期品川区障害福祉計画・第３期障害児福祉計画（素案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"おぎの委員","kind":"意見","question":"私もこの策定委員会、３回の開催を、途中退室という時もあったのですけれども、３回とも非常に興味深く傍聴させていただきました。私のほうから２点だけありまして、ページが飛びますので１点ずつお聞かせいただきます。３月に、こちらの障害者計画等を作成するための報告書、こちらのほうをいただいたのですけれども、こちらの１７ページ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問","question":"そうですね。障害者計画等策定のための基礎調査報告書。大丈夫でしょうか。","respondent":"川崎障害者施策推進課長","answer":"アンケートのほうですね。","voiceIndex":6,"id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問","question":"大田区では、「おおた障がい政策推進プラン」として、障害者計画、障害福祉計画、障害児福祉計画のほかに別枠として、大田区発達障がい児・者支援計画と、発達障害だけ切り離してカテゴリーが、令和３年から始まっていますので、人数の増減等を見ながら、そういった発達障害の方というのももう少しクローズアップして、計画等もまた次期に盛り込んでいっていただけたらいいなと思いますが、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今、委員がおっしゃった報告書というのは、基礎調査報告書のことですね。令和４年度に実施した基礎調査の報告、アンケートの結果になります。今回クロス集計等をしまして、様々な障害がある方の障害の特性というものを、具体的に示しています。","voiceIndex":8,"id":"exchange-003"},{"speaker":"おぎの委員","kind":"意見","question":"発達障害の方が増えてきていると、ご家族やお母様なども、どうしようといっていろいろ情報を探していると思います。こちらの報告書のほうでも、７８ページの行動援護のところで「「今後利用したい」が、〔居宅介護〕が１２.１％〔行動援護〕が１０.７％と１割台で高く」という評価も出ておりますけれど、これはニーズがあるのかなと思うのですが。","respondent":"川崎障害者施策推進課長","answer":"行動援護のところですけれども、令和３年、４年、５年と実績がゼロになっているというのは、利用実績がなかったということでゼロという記載になります。今後、令和６年度以降は、利用者１を見込んでいるという形で、記載となっております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"おぎの委員","kind":"質問","question":"こちら、利用者１名を見込んで８６時間ということなのですが、８６時間確保できる準備等はできているのでしょうか。","respondent":"松山障害者支援課長","answer":"行動援護の令和６年度からの見込量についてのご質問です。行動援護を指定されている事業所はおりますので、利用される方がお一人いらっしゃれば、この程度の時間数の見込みというのは、通常のサービス量から見込んだものですので、お一人利用されれば８６時間がほぼ目安だろうと。","voiceIndex":12,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"意見","question":"今までこういったことがなかったので、０時間であったと理解いたしました。そして、今後、今のところは希望の人数があまり多くないので、８６時間という準備でされているということで、承知いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"ひがし委員","kind":"確認","question":"今は利用を希望されている人がいなくて、利用していないからゼロとなっていて、ただ、報告書を読んでいると、「今後利用したい」という方は１０.７％いらっしゃって、その方々がもし希望された場合は８６時間分の提供の枠を、既に準備ができているということなのか、それとも、令和６年度に向けてサービスを提供できる見込みということなのか、というところは確認したいかなと思いました。いかがでしょうか。","respondent":"松山障害者支援課長","answer":"今、令和６年度からということになっていますけれども、実際希望される方がいらっしゃって、相談員にご希望を伝えていただいて、事業者との契約ということが整えば、この時間数は今年度であっても提供されるものです。","voiceIndex":16,"id":"exchange-007"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その点が確認できて、安心しました。時間は見込みということも分かりますし、利用される方々が時間を決めて、この８６時間に持っていくというわけではなく、その枠がきちんと確保できていて、希望されるときに使えるのかというところを確認したかったのかなと思いましたので、私も付け加えて質問させていただきました。","respondent":"川崎障害者施策推進課長","answer":"ただ、やはりボリュームがありますので、配布も含めて検討はします。今後ですけれども、ホームページ、広報しながわ等で周知をします。今のところ、別途説明会という予定はございません。","voiceIndex":18,"id":"exchange-008"},{"speaker":"ひがし委員","kind":"質問・要望","question":"パブリックコメントで区民の声を聞くといっても、現場に行かないと見られないとか、しかもボリュームが多いというふうになると、できる方が限られてしまうかなと思うと、発達障害の方々のお母様とか、なかなか行かれないという声が拾えないのかなと思うので、そういう方法も、今はまだ検討していないということだったのですけれど、今後検討していただければいいなと思いますし、強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、いろいろな思いがあると思うのです。パブリックコメントというのはそういうものを吸い上げる、いい機会なのではないかと思うのです。区としてこういう方向でやりますよというところが全然分からないで、意見を言うというのもなかなか難しいですし、そういう点ではぜひ説明会は、切実な要求だけに、ぜひやっていただきたいと思うのですけれど、ご検討いただけないでしょうかというのが１点です。","respondent":"川崎障害者施策推進課長","answer":"他区の周知方法なども今後の参考にしながら、十分に検討はしていきたいと思います。２つ目の団体数ですけれども、１３団体にヒアリングをいたします。３つ目の方法ですけれども、基礎調査の際にヒアリングをしたときと同様のスタイルで、実施することになります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問","question":"基礎調査の時のヒアリングの中身を、教えていただけないでしょうか。今、私が言ったような形での、説明みたいな形でパブリックコメントが広く出せるような、そういう形なのか、それとも、何というのですか、団体の中心の方にだけ集まっていただいて意見を聞くという感じなのか、そこら辺のやり方についてお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"主には団体の中心の方と、ヒアリングをするという形になるかと思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは団体の方の希望ということにもなると思うのですけれど、会員の方も含めて説明をしていただいて、パブリックコメントも皆さんが出せるようにというふうな希望があったら、ぜひその希望に応えるようにしていただきたいと思います。だから１ページ抜けてしまったのかなと思ったのですけど。これがもし抜けたのであれば、追加していただいたほうがいいかなと思ったのが、１点です。","respondent":"川崎障害者施策推進課長","answer":"ご指摘ありがとうあります。確認させていただいて、もしこちらが抜けていたら、早急に対応いたします。ありがとうございました。","voiceIndex":26,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"同行援護についても、これは同行援護のヘルパーさんがいないために、なかなか使える時間が使えないというようなところを、区としてもその養成をしてこれから拡大していきますという方向を出していると思うのですけれど、それが、８２ページの「見込量確保のための方策」という四角枠の中にはそういうふうに書かれているのですけれども、それなのにこれまでよりも減ってしまう見込量で。","respondent":"川崎障害者施策推進課長","answer":"２つを比較して、将来サービスの見込量が多いほうを、採用しております。ただ、見込量としてはサービスの上限を定めるものではありませんので、一人ひとりへの個別支援というのが最も重要なことでありますので、そこは丁寧に進めていきたいと考えております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうは言っても、こういう形でここは見込量と確保の方策ということになるわけですので、これまでよりも減ってしまう見込量というのは、しかも令和３年度、４年度というのはかなりコロナの影響も受けている、その受けているところよりも減ってしまう見込量というのは、要望があれば受けていきますよということなのか、でも、そうしたら何のための見込量なのかということになってくるのではないかと思うので。","respondent":"川崎障害者施策推進課長","answer":"今回、将来推計を出して、サービスの見込量が多いほうを採用しておりますが、あくまでも見込みになりますので、それを超えたらもちろん、その方に対しての対応というのはしていくことになります。","voiceIndex":30,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問・要望","question":"放課後デイは２３日まで使えることに、前は１０日までだったのですけれど、かなり議会のほうでも声を上げて、２３日まで使えるということになったのですけれど、実際そういうふうに使えていないのですけれど、でも、それは区としても積極的に誘致して充実を図るということであれば、ここのところもう少し、これでは多分希望に添えないと思うので。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"実際のところ、放課後等デイサービスの事業所数が足りていない状況ですので、区としては誘致に取り組むというところで、今、相談も来ていますので、そちらの個別相談への対応も含めて民間の参入が結構ありますので。放課後等デイサービスも含め、サービスの給付については現在国のほうで、令和６年度の報酬改定の見直しが検討されております。","voiceIndex":32,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"質問","question":"それで、本当に事業所の質というのがこれからいろいろ問われてくると思うのですけれど、そういうときに、事業所連絡会をやっていきますよみたいな、そういう方向がこの計画の中にもあったと思うのですけれど、今、事業所連絡会というのは具体的に、どのようなところがどういう形でされているのか、そういうものに区も関わって、事業所の質を上げていくことにつながっていくのではないかと思うのですけれど。","respondent":"松山障害者支援課長","answer":"相談事業所連絡会は本当に定期的に、頻度を高くして行っているものです。障害児向けの事業所連絡会というのを、区と心身障害者福祉会館、障害児者総合支援施設、その３者が協力をしまして、区内の障害児向けの事業所に呼びかけをして、事業所連絡会というのを開催しています。","voiceIndex":35,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問","question":"事業所連絡会というのは大きなところだけでなく、民間の、例えば放課後デイの連絡会のようなものであったり、民間事業所の連絡会というのを、私も他区でいろいろ話を伺ったとき、そういうふうなものをやって質を上げるような形にしているということも、お話を伺ったことがあるのですけれど、そういう民間での連絡会、例えば民間の放課後デイの事業所に集まっていただいて、共有をしながら。","respondent":"松山障害者支援課長","answer":"ご説明申し上げます。事業所絡会については、区立、民間を問わず全ての事業所に参加していただいております。ただし、児童発達支援、放課後等デイサービス、一緒に行っておりますので、それぞれにきめ細やかに行う方法も一つかと考えています。これから検討してまいります。","voiceIndex":38,"id":"exchange-017"},{"speaker":"やなぎさわ委員","kind":"意見","question":"３０ページの就労機会の拡充のところですが。後期、令和３年から５年で超短時間就労促進事業、令和５年から開始されていると思うのですけれど、これに関して、どこでどういうふうに行っているか、告知あるいは現時点でどれくらいの方が利用されているか、素案の中に特になかったと思うのですけれど、その点、情報をお知らせしてあげてほしいのですが。","respondent":"松山障害者支援課長","answer":"この中には特に、この数値目標というのは、国から示されている成果目標あるいはそれぞれのサービスの目標を示したものですので、超短時間就労促進事業につきましては、まだ今年度スタートしたばかりということで、来年度モデル実施の予定なので。","voiceIndex":41,"id":"exchange-018"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。恐らく需要が見込まれる事業だと思いますので、周知を含めてぜひお願いいたします。ほかの委員の前の質問と重なるところがあるかもしれませんけれども、パブリックコメントの周知に関してなのですけれども。例えば区の旧ツイッターとか、そういったＳＮＳでの発信の予定というのは、特に今のところは検討中ということでしょうか。","respondent":"川崎障害者施策推進課長","answer":"そこも含めて十分検討します。","voiceIndex":43,"id":"exchange-019"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど鈴木委員のご指摘もあったのですけれど、見込額というのを割り返すと、そんなに変わってないという状況が結構散見されるので、別にそれ以上、見込みより増えても対応できないわけではないというのは、先ほどご答弁で確認はできたのですけれども、区民の側からすると、少しそういう感覚にならないのかなと思うので、できれば、そこら辺のことも含めて数字とかもう少し。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問","question":"医療的ケア児のことで伺いたいのですけれど、１９ページには医療的ケア児は３０人と書かれているのですけれど、同じこの計画の４３ページの、「医療的ケアについての困りごと【障害児】」というところで、ｎが５４となっているのですよね。だから、ケア児だけで５４人ということになるのではないかと思うのですけれど、この５４と３０の数というのはどう捉えたらいいのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"４３ページ以降、基礎調査のところの人数ですけれども、これは病院に入院させている方もいらっしゃいますし、区としては把握し切れていない方の人数というのも含まれております。","voiceIndex":47,"id":"exchange-021"},{"speaker":"こしば副委員長","kind":"質問・要望","question":"委員の私たちもないのです。持ち合わせてないのですよ。恐らくホームページで、先ほどおぎの委員も提示されていましたけれども、ほかの委員は把握できていないところもあるので。それであれば委員会の事前に、１週間前とか２日前か、分からないですけれども、全員にそれはしっかり事務局と相談した上で、共有していただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"質問","question":"議員がいろいろとどのような資料を基にして、どう質問するかというのは、もうそれぞれ、いろいろな資料を基にしながら、ここにこういうことが書いてありましたよとかいうのは、何というのですか、事前にいろいろ調べて質問に臨むので、それを全部、全てここに書いてあったこういうもので質問しますので、皆さん、共有してくださいというふうには、なかなかならないと思うのですよね。これまでも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-023"},{"speaker":"鈴木委員","kind":"質問","question":"こういうもので、ということは、もう少し皆さんにも分かるような形で、質問の仕方にするようにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-024"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そうしますと、医療的ケア児というので、区がこの人が医療的ケア児だと、顔も分かるというところでは３０人だけれども、しかし、区として顔と名前が一致するということでないところでは、少なくとも５４人は医療的ケアの方がいらっしゃると、そういう捉え方でいいのかという確認を、お願いしたいと思います。","respondent":"川崎障害者施策推進課長、松山障害者支援課長","answer":"今後も実態の把握には努めてまいりたいと思います。移動支援事業につきましては、昨日指定管理者の指定のところでも、移動支援を増やしていくという方法をご説明させていただいたのですけれども、この計画自体も、第３回策定委員会で委員の皆様のご意見を伺いつつ。","voiceIndex":67,"id":"exchange-025"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、全体的にサービス見込量というのはこれから３年間、今までより少なくなると、何となく希望があまり持てないような気がしてしまうのですけれど、これから検討して、この数字は変わり得るということはあるのでしょうか。","respondent":"松山障害者支援課長","answer":"第３回の策定委員会で、委員の皆様にご審議いただいた結果ではあります。ですので、この数値で素案としてお出ししていくことになります。ただ、やはりコロナがありまして、実際に見込量を、令和２年、３年と下回ってしまった事業、サービスもあります。","voiceIndex":70,"id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"３０ページの「しながわ見守りホットライン」なのですけれど、ここに寄せられた虐待の情報というのは、計画の中には書かれてないと思うのですけれど、この件数というのは何件ぐらいあるのか、また、そういうのをここの中にも、何といいますか記述していただくと、それが見えるのではないかと思うのですけれど、いかがでしょうか。","respondent":"松山障害者支援課長、川崎障害者施策推進課長","answer":"区の法定雇用率は、確かに委員おっしゃるように２.６％になっておりますが、それは人事課所管のものですので、数字としては把握しているものではございません。令和３年度末の人数は１２８名、これが総合実施計画上に記載されている人数ですが、これを令和８年度までに２２８名に増やすということで、区内にホームを開設して、スピード感を持って進めていく、そのような形で取り組んでいます。","voiceIndex":72,"id":"exchange-027"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろありがとうございました。ぜひ、障害者の皆さんからご意見を伺っていただきながら、本当に障害者福祉が前進するような形で取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-028"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれど、素案の８ページの第２章、タイトルは「障害児者の現状」と書いているのですけれど、書いてあることは障害児に限らず、成人の障害者のことにも触れているのですけれど、なぜタイトルが障害児者にしてあるのか、伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"こちらの障害児者の現状は、こちらの棒グラフを見ていただくと分かりますとおり、年齢別にも分かれておりますので、障害児、障害者、大人と子どもの推計というものが載っている形ですので、現状把握として掲載しております。","voiceIndex":77,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"あえて障害児者をクローズアップしたいから、この書き方にしたということでよろしいですか。","respondent":"川崎障害者施策推進課長","answer":"今回、障害者計画という、障害者の基本計画に当たる部分の策定となりますので、障害者全般に関わる部分になりますので、このように障害児者を取り上げているということになります。","voiceIndex":79,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"ひきこもりということがありますけれど、ひきこもりは様々な原因があり、なかなか、なぜそういう状態になったのかというのは様々なパターンがあるかと思うのですけれども、一方で発達障害が原因であることもあります。そうしたとき、このひきこもりという用語は、入れないのでしょうか。ひきこもりについて、どうお考えなのか伺いたいと思います。","respondent":"松山障害者支援課長","answer":"委員おっしゃるとおり、ひきこもりになる要因、それぞれの状態は非常に様々ですので、もちろんひきこもりの方の中には発達障害の方もいらっしゃる、また精神障害の方もいらっしゃる、そのほか様々な要因の方もいらっしゃいますので。","voiceIndex":81,"id":"exchange-031"},{"speaker":"おぎの委員","kind":"意見","question":"すみません、最後に１点だけ、災害のところだけお聞かせください。２７ページの人工呼吸器使用者の、自家発電装置というのを令和４年度から追加して入っているのですけれども、これは実際のところ、支給した実績等はありますか。","respondent":"松山障害者支援課長","answer":"在宅人工呼吸器の方への自家発電装置につきましては、令和４年度には１件ございまして、５年度につきましては、少しずつ広がっているところです。数件以上は支給した実績があります。","voiceIndex":84,"id":"exchange-032"},{"speaker":"おぎの委員","kind":"質問・要望","question":"告知のほうも進めていただきたいと思います。実際に災害が起きたときというのは、人工呼吸器の方が自己避難する場所というのは、どちらを想定されているのでしょうか。","respondent":"松山障害者支援課長","answer":"それぞれの個々人によって、災害時の避難計画というのはご本人やご家族と相談しながら作っていくものです。人工呼吸器の方は、移動にリスクも伴いますので、在宅をご希望されている方が多い状況です。","voiceIndex":86,"id":"exchange-033"}]},{"id":"topic-02","title":"戸越四丁目区有地の今後の活用","agenda":"戸越四丁目区有地の今後の活用","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"対象となる障害で、重度の方を受け入れられるようなものを検討して公募するのか、そこら辺はどういう、性別にしても、対象の障害種別も含めて、どのようなグループホームになるのかも伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"ただ、今は、最終的なボリュームチェックの結果を待っておりますので、その結果次第で確定となります。こちらの運営につきましては、資料の米印にありますとおり、選定事業者にて実施予定ということで、民設民営で選定を行っていくことになります。","voiceIndex":92,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"そうすると、３０年定期借地のような形でなっていくのでしょうかね。それから、公募するのは来年度ということになると思うのですけれど、公募をしてもなかなか事業者が来ないというか、難しい状況が今まであったと思うのですけれど、どういう形で公募をされるのか、どこに声をかけていくのか、そこら辺の公募の仕方、応募していただけるような公募の仕方はどう考えられているのか、も伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今後の区有地の考え方ですけれども、やはり区有地は区全体の行政需要を考慮し、検討を進めていくことになりますので、全体の中で今後も、連携する企画課含めて検討していくことになります。","voiceIndex":94,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問","question":"ということは今、様々、区有地の洗い出しというところで、何に使うかというのは区全体として考えるとしても、区有地で活用できる土地というのはほかにも、見つかっているというか、見つけなくてもあるのかもしれないですけれど、そこら辺の可能性はほかにもまだあると考えていいのか、その点だけ伺います。","respondent":"川崎障害者施策推進課長","answer":"一方で、やはり民有地の活用というのも必要にはなっていきますので、土地を所有しているオーナー様への働きかけというのも十分検討しながら、実際に今年度、個別相談会というのも実施させていただきましたので。","voiceIndex":96,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、民有地を品川区が取得して、それで区有地として貸出して、定期借地みたいな形でする、そういうことも考えているということですか。民有地を品川区が取得して、グループホームの整備に充てていくと。それとも、そうではなくて自分の土地を使って自分で建ててくださいよと、そういうことだけなのか、そのことだけ確認をお願いします。","respondent":"川崎障害者施策推進課長","answer":"現在は、障害当事者のご家族の方で土地をお持ちの方に向けた相談会ということで、具体的な話が進んでいるということになっております。","voiceIndex":98,"id":"exchange-037"},{"speaker":"やなぎさわ委員","kind":"確認","question":"改めて確認なのですけれど、運営主体は民営になるのか、区でやるかというのは、まだ決まってないということですね。","respondent":"川崎障害者施策推進課長","answer":"民間事業者にて実施をすることになります。","voiceIndex":101,"id":"exchange-038"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そのように考えると、大丈夫なのかなという不安、どれぐらいの応募があるのかなという不安もあるので、そういった面でいうと、民間活力だけでなく、区の力も活用することもぜひ考えていただきたいと思いますし、民間に依頼するならそれこそ、前回もそうでしたけれど、３０年とかの定期借地の期間が終わったら更地にして返すみたいな、いや。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":103,"id":"exchange-039"},{"speaker":"ひがし委員","kind":"質問","question":"この戸越四丁目の区有地の今後の活用で、グループホームになるということで、福祉の領域で使えるということはうれしいなと思います。２日間ぐらいで予約多数だったのかなと考えると、開設したいと思う方々が結構参加されたのかなというふうに想像されるのですが、この実態というところで、参加された方々の人数はどのぐらいだったのか聞けたらと思うのですが、いかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"こちらの相談会は、５組の方を対象に予約制で行いました。委員おっしゃるとおり、開始から１時間で埋まってしまいまして、１０月２５日にはホームページのほうで予約受付は終了しましたというふうに掲載しています。","voiceIndex":105,"id":"exchange-040"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回申込みが多かったということを踏まえると、今後も開催はぜひ検討していただきたいと思うのですが、その点について、検討状況を教えてください。","respondent":"川崎障害者施策推進課長","answer":"私どもも今回は試験的に初めて行いまして、反響があったということで、そこについては開設したい方々がいらっしゃるのだという実態をつかむことができました。今後も、この件については前向きに検討していきたいと考えております。","voiceIndex":107,"id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問","question":"今の障害者グループホームの開設に関する個別相談会というのは、５組来られたというのは、品川区の補助金が受けられますよということも含めた相談会ということなのでしょうか。","respondent":"川崎障害者施策推進課長","answer":"今まで公的補助を使った事業者ですけれども、グループホーム金子山と、令和４年度の民間でのグループホームの運営者と、今、２件です。","voiceIndex":111,"id":"exchange-042"},{"speaker":"鈴木委員","kind":"意見","question":"民設民営でのグループホームは結構幾つもできていると思うのですけれど、この補助金が活用されない、壁というか何かそういうものがあって、２件しか使われてないという、もっとたくさんできていると思うのですよね、それなのに補助金が使われていない理由というのは、どのようなものがあるのかお聞かせください。","respondent":"川崎障害者施策推進課長","answer":"は東京都のほうで補助金の申請をする必要がありますので、そのタイミングも含めて、品川区の整備費補助のタイミングとずれてしまうということも、１つあります。自己資金などで建てられるという方もいらっしゃる、それは事実です。","voiceIndex":113,"id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"今の質問に追加でお伺いしたいのですけれど、手持ちの資金でやるというのは、例えば補助金を受けると何か制約ができてしまうから、あえて自分たちの自己資金でやるという、そういう事務所が多いというか、いるということでしょうか。","respondent":"川崎障害者施策推進課長","answer":"区の補助金を使うということは、東京都の申請もありますので、手続に時間がかかるというのもあります。早急に建てたいという方、そこで２段階の申請を早めて建てたいという方は、ご自身の蓄えで作られるという方もいらっしゃいます。","voiceIndex":116,"id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私が今お伺いした、いろいろ条件が出てしまうとかいうことではなく、スピード感という方が多いということで、よろしいですか。","respondent":"川崎障害者施策推進課長","answer":"そのとおりです。","voiceIndex":118,"id":"exchange-045"}]},{"id":"topic-03","title":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","agenda":"「第九期品川区介護保険事業計画概要（案）」に係るパブリックコメントの実施","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"やはり介護というのは本当に多くの区民の関心事ですし、やはり切実な思いも抱えていますので、様々要望があると思いますので、要望を聞く機会としても、説明会をぜひ持っていただきたいと思います。その点、いかがでしょうか。２３区の中でも幾つもの区が説明会をやっていると思うのですが、その２３区の説明会の状況というのも、分かったらお聞かせいただけたらと思います。","respondent":"菅野高齢者福祉課長","answer":"２３区の他区の状況ですけれども、近隣区におきましては、例えば大田区が１２月に２回ほど予定をしている、渋谷区も１２月に４回ほど予定しているというところで、説明会を実施する区もあれば、説明会を実施していないだろうという区もあるというところなので。","voiceIndex":125,"id":"exchange-046"},{"speaker":"鈴木委員","kind":"質問・要望","question":"たしか世田谷区とかほかの目黒区とか、私、今回調べていないのですが、前回調べたときには、近隣区どこでもやっていると思ったのですが、そこら辺のところはつかまれていないでしょうか。それで、やはりパブリックコメントを多くの区民からいただくためにも、説明会はぜひやっていただきたいと思うのですが、ちなみに３年前のパブリックコメントは何件ぐらい来たか、それも分かったら教えてください。","respondent":"菅野高齢者福祉課長","answer":"説明会、ご指摘の世田谷区と目黒区につきましては、今、こちらで捉えている範囲では、世田谷区は、パブリックコメントが９月７日から９月２７日までで終了しておりまして、説明会については、ホームページ上はなかったので、実施していないのかなというところです。","voiceIndex":127,"id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"説明会をやらない理由というのは何かあるのか。少しそこら辺のところも、何でやらないかというあたり、ぜひ区のこういうのをやっていますよというアピールの場でも、私は、啓発の場というところでも説明会というのは活用できますし、それで皆さんからご要望を伺う場としても、知らせてご意見を伺う場としても、説明会はぜひお願いしたいと思うのですが、改めてお願いします。","respondent":"菅野高齢者福祉課長","answer":"この中でも審議しているということと、あとは今回のパブリックコメントも実施するというところで、いろいろな角度からお声もいただいているというところで、今のところ説明会の予定はないとお答えします。","voiceIndex":129,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、一部のその２０人の方では全てを反映できるかというと、なかなか難しいと思いますし、これは毎回申し上げているのですが、ぜひ私は、品川区はほとんどの計画に対して説明会は開かないという方向で来ていますが、やはり区民に情報公開とか情報提供をして、そして区民の意見を聞く、住民参加という点からもぜひ説明会は、こういう大きな計画、３年に１回ですから。","respondent":"菅野高齢者福祉課長","answer":"それを合わせると１５０床ぐらいあるではないかというところなのですが、ここの見込みの出し方につきましては、今までの実績、令和３年とか令和４年の実績なども、推計値で国の「見える化」システムというシステムがあるのですけれども。","voiceIndex":131,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問","question":"だから、本当にお金のある人でないとなかなか入れないというところは要支援から入れて、そして、そのところが介護財政をより使っているという状況では、私は公平性という観点から、有料老人ホームを誘導するというのはどうなのかなという思いがあるのですが、有料老人ホームを誘導するというよりも、誰もが低廉で入れる特別養護老人ホームをつくることのほうが。","respondent":"菅野高齢者福祉課長","answer":"それはそれなりのニーズがあるというところで、有料老人ホームを運営する会社も、品川区につくりたいというところで計画を立てるのだと思いますので、そのあたりの多様なニーズというところで、必ずしも皆さん、特別養護老人ホームに入りたいというニーズではないと思いますので。","voiceIndex":133,"id":"exchange-050"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ちなみに、これは令和４年の介護保険制度の運営状況の資料ですが、特別養護老人ホームは約３７億４,３００万円、有料老人ホーム（特定施設）は約４０億９,７００万円ということで、これだけ多く使っていますので、また特別養護老人ホームは、計画してから、今回の３か所にしても本当に６年、７年とかかっていますので、私は、有料老人ホームを誘導するというよりも。","respondent":"菅野高齢者福祉課長","answer":"それ以外の、各こちらの数字につきましては、都内でも老人保健施設は比較的入れるところがあるというふうにも聞いておりますので、そういうところに入っていただくなどして、短い期間、基本的には３か月、長くて６か月という施設なのですけれども、在宅の療養に向けて。","voiceIndex":135,"id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区は在宅介護支援センターが２０か所ということでありますけれども、仕組みとして少し教えていただきたいのが、在宅介護支援センターの委託に係る財源というのはどういうところから出てくるのかと、それから、２０か所で幾らぐらい在宅介護支援センターに委託料が出ているのか、その点を伺います。","respondent":"菅野高齢者福祉課長","answer":"１点目の、老人保健施設の今後の整備計画というところですが、こちら、区としては今のところ明確な予定はございません。","voiceIndex":137,"id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからあと、ブラッシュアップのところで、７番の介護・福祉職員の確保といって、ここのところというのは（２）番でも、担い手の確保・育成というのはやはりすごい課題で、どこでも本当に大変な深刻な状況があると思うのですが、これは介護職員の待遇改善なしにはできないと思うのですが、その待遇改善に向けて、国も若干増やすという方向を出していますが、それはあまりにも少な過ぎると思うのですが。","respondent":"菅野高齢者福祉課長","answer":"介護の処遇改善ということにつきましては、様々なところで国としても全体的な問題とはなっておりますので、給料の値上げとか、そういった部分はご指摘をいただているところなのですが、やはり区としては、給与の原資となるものは介護報酬外から賄われるものというところが。","voiceIndex":139,"id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"介護職員の確保・育成というのが本当に根本的な問題ではないかなと思うのですが、介護報酬となるとやはり保険料にも反映してきてしまうということで、前に処遇改善交付金という形で国から出されたことがありましたので、そういう形もぜひ区からも求めていただきたいと思います。取りあえず、では一旦。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問","question":"以前、第２回の定例会で我が会派の松永よしひろ議員から質問があったと思うのですが、まず、高齢化が進む中で介護職員の人材確保に力を入れてほしいという内容で、品川区の現状についてという質問をさせていただいたときに、「品川区は介護士が不足しているのですか」という趣旨の質問に対して、「現在、品川区内介護施設における介護士については、今のところ不足しているという声は届いていませんが、今後。","respondent":"菅野高齢者福祉課長","answer":"いずれにせよ、区内においては、例えば実際たまに散見されるのですけれども、介護人材がいないがためにサービス提供ができないとか、そういった事態までには今のところ陥っていないと、そういうところは共通していると認識しているところです。","voiceIndex":144,"id":"exchange-055"},{"speaker":"ひがし委員","kind":"質問・要望","question":"そこで、中を見ていくと、品川区の介護福祉専門学校の設置とか、そこの定員のところに力を入れていたり、その他の研修とかにも力を入れていると決算特別委員会のときにもお話をいただいていたと思うのですが、やはり給料の問題とか職場の環境も、品川区内の事業所については、品川区としても、政策、何か支援の方法を模索していくべきかなと思いますので、その点については要望にはなるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-056"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほど鈴木委員の質問ですけれども、パブリックコメント、前回６件で、多い、少ないみたいな話もありまして、その際に公募の区民の方も入られていると。そこで区民の方の意見も吸い上げているよと、多分そういったことなのかなと思ったのですけれども、この公募の区民の方というのは５名ですかね。何か応募基準というか、どういった形で公募されたのか、詳しくお聞かせいただければと思います。","respondent":"菅野高齢者福祉課長","answer":"介護保険制度推進委員の公募区民についてのご質問に、お答えします。こちらについては、公募委員の方は４名となっております。第１号被保険者と第２号被保険者の方で、３名の方が６５歳以上、１名の方は６４歳以下で構成されております。","voiceIndex":148,"id":"exchange-057"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。当然、品川区の介護保険制度のことなので、介護事業所も大きく関わってくるお話かなと思うのですが、介護事業所というのはその委員会の中に何名ほど入られているのでしょうか。","respondent":"菅野高齢者福祉課長","answer":"事業者代表者としましては、医師会の会長、歯科医師会の会長などのほか、事業者代表として社会福祉法人の理事の方、あとはホームヘルスなどの会社をやっていますＮＰＯ法人を運営している方の理事の方２名。","voiceIndex":150,"id":"exchange-058"},{"speaker":"やなぎさわ委員","kind":"質問","question":"商店街の会長とか、そういう方も当然必要ですけれども、どちらかというとやはり実際事業をされているというか、運営されている方がより委員に入ったほうが、いろいろな意見が出ていいのかなと思うので、ぜひそういったメンバー構成というのを少し検討していただければなと思うのと、少し話が戻ってしまうのですが、公募の区民の方はたしか６５歳以上とか以下で区切られているというのは。","respondent":"菅野高齢者福祉課長","answer":"特に、そのあたり、何名という縛りはございませんので、毎年４名というところで選ばせてもらっています。ちなみに第１号被保険者というのは、６５歳以上ということになります。","voiceIndex":152,"id":"exchange-059"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく第１号被保険者が多かったりする理由は、私が思うに、開催の日にちというか時間帯とかですよね。大体というか、ほぼ全て平日の午後に開催されているではないですか。そうすると、普通に働かれているけれども品川区の介護保険制度とかに興味があったり、発言をいろいろ中に入ってしたいなという方が、参加できないですよね。そういった取組とかはいかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"もちろん、今、やなぎさわ委員がおっしゃったみたい、公募区民の方が第１号、６５歳以上の方が多いのは、ふだんお仕事をされている方がなかなか入れないような、そういう会議体の時間帯になっているのではないかというところで、そのあたりのところは。","voiceIndex":154,"id":"exchange-060"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど人材不足で介護提供ができないまでには至っていないというご見解でした。これは一般質問でおぎの委員も質問されていたのですが、外国人の採用に向けた支援というところは、大体こういった介護人材の文言には必ずと言っていいほど品川区では入っているのですが、これも変わらず積極的に採用支援は行っていくような取組の理解でよろしいですか。","respondent":"菅野高齢者福祉課長","answer":"例えば迎える側の施設も、最初はすごく抵抗があったりしたのですけれども、ある施設の施設長が外国人の方を採用すると踏み切ったときに、やはりすごくきめ細やかに真面目に働いてくれるという実態があって、ほかの施設も、うちも。","voiceIndex":156,"id":"exchange-061"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"むしろインバウンドで外国人の方がたくさん来るような、少し賃金の安い国というか、物価の安い国にどんどんなってしまっていっているので、当然、そういった来てくれる方がいるならというのはあるのですが、そこだけに頼らずに、やはり国内のそういった人材確保、人材育成をぜひ積極的に、そこを第一に、どうしてもというような次の手段だなというふうには。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"質問・要望","question":"認知症の対応なども、そういうことで豊かに進めていただきたいと思うのですが、そこのところは、やはりこれからも在宅支援でずっと行くということなのか、私は在宅支援にあとの２つの職種を入れていただければ、そこで地域包括という看板もつくれるし、地域包括に変わることができるわけですから、その配置さえしていただければできると思うので、ぜひ在宅介護支援センターに保健師や社会福祉士を配置して。","respondent":"菅野高齢者福祉課長","answer":"委員ご指摘の保健師の人数が規定より不足しているのではないかとか、そういった課題を抱えているところもあるのかもしれないのですけれども、何よりも２０か所の各在宅介護支援センターと高齢者福祉課、オンラインで情報も結んでおりまして。","voiceIndex":160,"id":"exchange-063"},{"speaker":"鈴木委員","kind":"質問・要望","question":"保険料は１７ページ、１８ページのところで、今、６,１００円のところが７,１００円程度で推計ということで、実際は６,５００円から７,０００円程度を見込んでいますということで、この７,１００円というと、１,０００円も上がってしまうのかというすごい値上げなのですけれども、６,５００円から７,０００円というのもどうなっていくのかというところなのですが、少し伺いたいのは。","respondent":"菅野高齢者福祉課長","answer":"というのは、今後のこの計画の概要のところも見ていただきますと、第九期が６,５００円から７,０００円になっているのですが、今後２０３０年、２０４０年を見ると、高齢者の数がどんどん増えていくところもありますので、今、安ければいいのかという部分も。","voiceIndex":162,"id":"exchange-064"},{"speaker":"鈴木委員","kind":"質問","question":"基金をどれだけ残すかというのはどう考えるかということだと思うのですが、この基金というのは６５歳以上の人の保険料そのものですよね。それなので、やはり６５歳以上の人に返せるときに返すべきものだと思うのです。これは本当に積立てておいて自由に使うというよりは、国の方針としてもそういう方向が出されていると思います。先ほど伺った市町村特別給付のことも、ご答弁をお願いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"例えば要支援者夜間対応サービスや通院等外出介助サービス、そして、指定地域密着型ケアハウスサービス、こちらについてが市町村特別給付というところで、ここについてはやはり委員ご指摘のとおり第１号被保険者の保険料を財源としておりますので。","voiceIndex":164,"id":"exchange-065"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それなので、私は、この市町村特別給付は一般財源でぜひやっていただきたいということで、求めておきたいと思います。だから、そういう形で、６５歳以上の人の保険料がこれだけどんどん高くなって、本当に介護保険が始まったところからすると約２倍になるわけですから、そういうところでは、保険料を引き上げる、丸々保険料だけで賄う市町村特別給付は、ぜひ一般財源に変えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ちなみに区では大体３.５％から３.７％前後で近年推移しております。こちらにつきましては、全国の市町村会議等におきまして、５％一律でというところは毎年要求しているところです。","voiceIndex":167,"id":"exchange-066"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ぜひそれを強力に求めていただきたいと思います。もう２５％丸々来て、その上にプラス５％としていただけるようにということで、国にも引き続いて強力に求めてください。それなので、これはぜひもっと多段階にして、それで、応能負担というところでしていただきたいと思うのですが、今の段階での品川区の考えを伺えたらと思います。区の考えをお願いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その部分も踏まえまして、区としては１４段階で、前回、前々回は段階の設定をしているのですけれども、そこについての見直しも含めて、今検討を図っているところです。","voiceIndex":169,"id":"exchange-067"},{"speaker":"鈴木委員","kind":"質問・要望","question":"分かりました。それなので、品川区で言えば６,１００円の保険料が、渋谷区で言えば４,７６８円としているのです。今の段階で品川区は一番高額所得者に安い保険料になっていますので、これは他区の状況も見ながら、ぜひ多段階化、応能負担を進めていただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":172,"id":"exchange-068"},{"speaker":"おぎの委員","kind":"質問・要望","question":"質疑ではなく、これ、要望というか意見なのですが、先ほどやなぎさわ委員が言っていました１３ページの外国人の採用の件の話ですが、こちら、私、２０１１年の震災の直前まで台湾におりまして、台湾は、早くから介護に関して外国人人材の導入に踏み切っておりました。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-069"}]},{"id":"topic-04","title":"後期高齢者医療制度令和６・７年度保険料率の改定","agenda":"後期高齢者医療制度令和６・７年度保険料率の改定","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"少し今の説明でよく分からないところがあったので、何点か伺いたいのですが、一番左側の（６）の剰余金ですが、２５０億円を剰余金として見込んだというのは、剰余金の分だけは保険料の算定の中に入れて安くなるという考え方でいいのでしょうか。それから、右側の所得割のところが、旧ただし書き所得の５８万円以下と５８万円超というところで、２段階になったというのが今回変わったところなのでしょうか。","respondent":"池田国保医療年金課長","answer":"剰余金につきましては、前回、令和４・５年度の算定の際の１８７億円を見込んで計算をさせていただいたところは、今、令和６・７年度については２５０億円を見込んだということになっています。","voiceIndex":179,"id":"exchange-070"},{"speaker":"鈴木委員","kind":"質問","question":"前の資料を見ると、１人当たりの平均保険料額というので見ると、令和４・５年のときは前の期に比べてプラス３,７８９円、その前は３,９２６円、その前は１,６３５円となっているのですが、そのことからすると、何かこの８,９３２円というのは、この８０万円とか、それぞれに合わせてというところでの資料を持ち合わせていないのでよく分からないのですが。","respondent":"池田国保医療年金課長","answer":"委員がお話しされた金額でなく、私たちは率でお話しをさせていただいたところで、率としては、令和４・５年の保険料を決める際が一番高く上がっているところではあります。額としてというところになるかと思うのですけれども、額につきましても……。少し待ってください。","voiceIndex":181,"id":"exchange-071"}]},{"id":"topic-05","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"こしば副委員長","kind":"質問","question":"八尾市の例を出してしまうのですけれども、八尾市ですと、各部署といいますか、窓口のところに、区民の方のちょっとした変化といいますか、言葉もそうでしょうけれども、そういった少しの変化に気づけるようなチェックリストというのを設けていまして、それがなかなかより具体的に書かれていまして、そういったものを品川区で取り組まれているのかどうかも踏まえて教えてもらえますか。","respondent":"坂野保健予防課長","answer":"やはり眠れていないというのは非常に危険なサインということで、そこは確認してくださいねというのは、お話はしているところです。","voiceIndex":195,"id":"exchange-072"},{"speaker":"おぎの委員","kind":"質問","question":"こちらの心の健康相談訪問事業のところですが、電話相談の件数が思ったよりすごく多いなというのがありまして、この電話を受けている職員の方というのは大体何人ぐらいで、１回の通話はどれくらいお話しされているのでしょうか。","respondent":"榎本荏原保健センター所長","answer":"職員の数は、保健センターにおります保健師と心理職、それから精神保健相談員という者がおりますが、その職種が中心になって、こころの健康相談のときは対応しております。","voiceIndex":198,"id":"exchange-073"},{"speaker":"おぎの委員","kind":"意見","question":"予想していたよりも非常に多い件数で、驚いています。顔が見えない相手にでもお話を本当に聞いてほしいとか、最後の訴える場になっているかもしれないので、本当に丁寧に当たっていただいているのだなというのが分かりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"前回の行政視察のときも思いましたし、今回、認知症をテーマに少し調べ物をしているときとかもすごく思ったのですが、何かキャラクターというのはすごくアイキャッチとしていいなと思っていて、ほかの区だと、例えば八尾市だときくにゃんだったり、あと奈良のキャラクター、ラブキー君とか、何かそれぞれ自殺の対策に力を入れていますといって、キャラクターで結構統一してポスターとかに入れることで。","respondent":"坂野保健予防課長","answer":"実は自殺対策で作っているカレンダーには、シナモロールですか、あれを使っております。ただ、キャラクターの権利の関係があって、なかなかほかに横展開ができていない部分があるので、また何かありましたら勉強していきたいなと思います。","voiceIndex":202,"id":"exchange-075"},{"speaker":"ひがし委員","kind":"意見","question":"品川区の自殺対策のホームページを見てみると、この黒の猫ちゃんがちょこちょこと出てくるので、何かこれがキャラクターなのかなと思ったり、サイトとかに飛ぶとところどころで出てくるので、これがキャラクターなのかなと思うけれども、特に名前も出てきていないし、ほかのところを見ると、こころの電話帳とか対策のマニュアルとかには載ってこないので、統一感としてはやはり何か１個あるといいのかなと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-076"},{"speaker":"鈴木委員","kind":"質問","question":"精神保健事業のほうでメンタルチームサポート事業について伺いたいのですが、本当に精神の問題を抱えた方というのはすごく多くて、しかもかなり深刻で複雑という方も多いと思うのですが、このメンタルチームサポート事業にどういう形でつながっていくのか伺いたいと思います。その中身についてもう少し教えてください。","respondent":"榎本荏原保健センター所長","answer":"多職種のところですが、保健センターにおります、保健師、心理職、それから精神保健相談員を中心としながら、その対象者の方によりまして、例えばですけれども、退院後支援で入院した後の支援をする場合などは、入院中でしたら病院の主治医と看護師さんと連絡を取って。","voiceIndex":206,"id":"exchange-077"},{"speaker":"鈴木委員","kind":"質問","question":"この多職種チームというのは、例えば１か月何回カンファレンスをやるとか、そういう形でというよりは、具体的に事例があったときに集まって、みんなで相談をしながらやりましょうみたいな、そういう形になっているのか、少しそこら辺、何というのですか、本来であれば医療機関につながってほしいなと思いながらもなかなか医療機関につながらなくて。","respondent":"榎本荏原保健センター所長","answer":"先ほどかなり広範囲のいろいろな方の職種というか、連携のところをご説明いたしましたけれども、その場面ではかなり多くの方が集まって会議をやることになりますけれども、中心になっておりますのは、先ほどご質問があった例えば医療機関につながっていない方の場合などは。","voiceIndex":208,"id":"exchange-078"},{"speaker":"鈴木委員","kind":"質問","question":"今、訪問看護ステーションも、かなり精神に特化したところでの訪問看護ステーションというのがすごく増えてきていて、訪問看護ステーションから訪問をしていただくことで、うつの方だったり、それから統合失調症で妄想のある方なども、かなり、何というのですか、落ち着くという、そういう対応をしていただいているなと思っているのですが。","respondent":"榎本荏原保健センター所長","answer":"精神に特化した訪問看護ステーションのことがありますが、精神疾患への対応に非常に慣れていらっしゃるというのもありますし、かなり密に連携して支援をしているという状況があります。","voiceIndex":210,"id":"exchange-079"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に精神で苦しんでいる方というのはたくさんいらっしゃって、そういうところが様々進んできている部分というのがあると思うのですが、そこが、何というのですかね、うまくつながっていないところもあったりするのではないかなという思いがしていまして、そういう点では、こういう事業があるよというところもぜひ周知もしていただきたいと思いますし、この訪問看護ステーションも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-080"},{"speaker":"筒井委員","kind":"質問","question":"自殺者が今、３０代、４０代の方が増えているということで、そうした年代の方にとっては、インターネットゲートキーパーという手法は非常にいいのかなと考えていますけれども、今、品川区のホームページで少し検索しますと、ＮＰＯ法人ＯＶＡというところが出てきているのですけれども、ここでインターネットゲートキーパー、相談機関のバナー広告を出すというシステムは。","respondent":"坂野保健予防課長","answer":"今、お話があったように、インターネットゲートキーパー事業はＮＰＯ法人のＯＶＡに区が委託をして行っています。そこである程度ご相談が、やり取りができて、それで、これはもう継続的な支援がこの先必要だからと、区のほうに戻ってくるようなケースも何例かあります。","voiceIndex":214,"id":"exchange-081"},{"speaker":"筒井委員","kind":"質問","question":"要は相談件数を見ると多いのですけれども、下の表を見ると、躁うつ病とかギャンブル依存とか具体的な診断が出ているのですが、その相談件数の中から、あなたはギャンブル依存症ですよとか躁うつ病ですよという具体的な診断に至るのは、やはりどうしても絞られていくか、具体的な診断に至るケースというのは、どうしても数字的には少なくなるということでよろしいのですか。","respondent":"榎本荏原保健センター所長","answer":"参考資料のほうのこころの健康相談の件数と、一番下のところの専門医による相談のところ。","voiceIndex":216,"id":"exchange-082"},{"speaker":"筒井委員","kind":"質問","question":"相談を受けて、その方がお話を聞いていただけたということでご納得されて、それで終わるというケースもあるのですか。","respondent":"榎本荏原保健センター所長","answer":"もちろんその後何かあったらご相談くださいということでお伝えはしますけれども、そういった１回とか２回ぐらい、数回ぐらいで終わる場合もありますし、もうかなり、何年という形でご支援している方もいらっしゃいます。","voiceIndex":222,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"品川区の自殺率については非常に優秀で、品川区の成果が出ているのかなと非常に感心するのですけれども、区で行っている自殺対策は何個かあると思うのですが、その中でこれがすごい、特に効果が出ているなみたいな、そういった実感がもしあるようなものがあればお教えてしていただきたいと思いますが、いかがでしょう。","respondent":"坂野保健予防課長","answer":"逆に、広くに効いてくるであろうというのは、今もやっていますけれども普及啓発事業とかゲートキーパー研修とかは、１つのケースでの効果はそんなに深くはないのかもしれないのですけれども、ただ広い範囲に効いているということで。","voiceIndex":225,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"すみません、約３,０００件、全部回って、その中で夜逃げしている人もいたり、病気とか、あとひきこもりとか、そういったところで様々な困難な事情が複合的にあったりということで、つまりその中に、その先に自殺にもつながるような方もいたというのをそういった調査によって明らかにできたというところで、このお話は非常に、我々委員もそうですし、参加された全員が多分感心したような事例だと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-085"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3678#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":70414,"voices":236}},{"id":"r05-20231128-8","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"建設委員会","time":"午前１０時０８分～午後 ０時０８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年１月区営住宅入居者募集","agenda":"令和６年１月区営住宅入居者募集","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"最近の応募状況を伺いたいのと、いつも配布期間と申込み期間がずれているのですけれども、その理由を伺いたいと思います。それで、区営住宅の中で結構空き室があるという話も伺うのですが、今、空き室が何戸あるのか伺います。","respondent":"竹田住宅課長","answer":"最近の倍率です。令和５年７月に実施しました募集では、全体で５０.７倍、令和５年１月実施が４２.２倍、令和４年７月が４７.０倍となっております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"応募倍率が直近で言うと５０倍になっていると。区営住宅のニーズが高いなと感じるところですけれども、そうすると、空き室のところは半年間ずつ、空いたところは全て募集をかけているという捉えでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"空いたところは全部募集をかけているかということなのですが、例えば、居住者の方がお亡くなりになって、残置物があった場合、相続人の方にお引取りをお願いするのですけれども、それをなかなかしていただけない等々の理由がございまして。","voiceIndex":7,"id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"期間についても、郵送が遅れる場合があるということですけれども、受付期間が今回１月２９日ということで、そうすると、応募する方も、そこまで受け取れるのかなと思ってしまう方もいると思いますので、そこはしっかり説明していただくのと、できれば受付期間まで配布をしていただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"そこは空き室になるわけではないですか。それと、募集住宅の９戸なのですけれども、これと空き室との関係がよく分からないです。要は、空いたから募集という話ではないのですか。だから、９戸というのは完全に空いているということなのか、ということは、９戸というのが空き室と理解していいのか、はっきり空き室のことをおっしゃらなかったので、何かその理由があるのかなと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"ですから、近々に退去されたものというのは、原状回復が終わっていませんので、１月に入居されるまでに原状回復が終わらない可能性もありますので、そういったものは今回の募集にはかけないで、次回送りにしているというところがあります。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"分かりました。そうすると、申込みの抽選までに空き室が、ここの募集住宅数には入っていないけれども、入れそうだという場合には、それも加えた形の募集という意味合いでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"先ほど申し上げたとおり、残置物の問題とか、業者に原状回復費の見積りを取ったところ、こういう金額です、そのうち自己負担は幾らです、区の負担は幾らですということでご案内差し上げるのですが、そちらの金額にご納得いただけないケースとか、様々ありますので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたかったのは、残物とかいろいろあって、手続があってと言ったけれども、この申込みにもし間に合えば、その戸数も、例えば１戸でも２戸でも可能だったら、それに加えられるわけではないですか。そういう意味合いでいいのですか。それとも、この段階で９戸しか駄目ということなのか、問題解決できたら、ここに加えることができるのかというところを知りたかったのです。","respondent":"竹田住宅課長","answer":"退去されたお部屋なのですけれども、放置されているお部屋も多いという状況で、例えば今年あった事例ですと、入居者がお亡くなりになっているのですけれども、相続人の方が、私が物置として使っているとご主張されて、そういう趣旨のお部屋ではないですから。","voiceIndex":15,"id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"質問が悪かったのかもしれません。だから、２１戸についてはまだ時間がかかって、ここには恐らく間に合わないだろうと。そうすると、１戸とか２戸増えれば、競争率が下がるではないですか。１人でも多くの方に入ってほしいから、そういう準備ができた段階で、決まるのが２月ですよね。その間に１戸でも２戸でも入れる可能性があるのだったら、それも加えていきますということでの理解でよろしいですか。","respondent":"中村都市環境部長","answer":"ただ、今回の９戸が１０戸に、１戸２戸増えるかどうかというのは分かりませんが、もし可能であればというところですが、考え方としましては、入居できるのに、ただ単に放置しているといったところはなく、可能な限り入っていただくといった考えで運営しております。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","agenda":"しながわ水族館リニューアル整備運営準備事業事業者の選定結果","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"初めに、外部有識者の方の意見書が出されたということで、ぜひこれは資料として出していただきたかったということで、今後は出していただきたいということで要望しておきたいと思います。それで、今回３名、人選をされているということで、この３名を人選された理由を伺いたいと思います。今回、公募して１者しか来なかったということで、区としてはこのことをどのように捉えているのか、伺います。","respondent":"高梨公園課長","answer":"東海先生につきましては、令和２年度に実施したしながわ水族館顧客満足度満点プロジェクトということで、しながわ水族館のこれからの在り方についての検討等でもご尽力をいただいている先生でございまして。","voiceIndex":23,"id":"exchange-008"},{"speaker":"のだて委員","kind":"提案","question":"運営準備事業者は、今回、助言・準備をする事業者ということですけれども、選定理由のところに、本委託の受託者として適していると書いてあるのは、そうするとどういうことなのか、伺いたいと思います。今回、それも含めて附帯意見をつけたということで、その附帯意見は、検討していく分についてのことなのかどうかも併せて伺います。","respondent":"高梨公園課長","answer":"得点率６７％の評価といったところですが、一定、比較対象がいない中での採点といったところで、難しい部分が審査会の各委員の中でもあったのかなとは感じているところですけれども、それぞれ委員から、しっかりと区が示しているリニューアルの方向性についての理念であったり。","voiceIndex":25,"id":"exchange-009"},{"speaker":"西本委員","kind":"提案","question":"それに対して、選定理由の中で、例えば１個目は、条件に合致した提案内容というのだけれども、この数字を見たら、そうですかと言いたくなるのです。本当は１００％に近い状況が、合致しているというのではないですか。イルカのショーはいつまでやられるのかというのをもう一度確認したいし、代わりになる等のイメージアップをするために、何か提案があったのかというのをお聞きしたいと思います。","respondent":"高梨公園課長","answer":"取組姿勢のところですが、主に当日、提案説明・ヒアリングでの事業者の受け答えの部分で、配点をしていただいたところ、採点をしていただいた部分であると考えています。","voiceIndex":28,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区が取り組んでいるというのは大きなメリットだし、努力の成果だと私は思うので、財政面からすると、運営は厳しいと思いますが、それを起爆剤にして、観光であったりというように広げられるということがありますので、ここだけ考えるのではなくて、ほかの部とも、文化観光のほうとか、一緒に考えていただきたいと思いますので、いい水族館を継続していただくように強くお願いしたいという思いで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"私も同じような視点からなので、重複を避けながらお伺いしたいと思いますが、まず、公募結果、１者しかなかったということで、本来であれば複数あって比較したかったけれどもというご答弁もありましたが、そもそもの公募要件とか公募条件がどうだったのかとか、あるいは公募の仕方が、ホームページか何かに掲載しただけで、それに対してを求めたのか、全国で水族館は、数もそうあるわけではないので。","respondent":"高梨公園課長","answer":"ご提案のありました、それぞれというか、水族館の事業者に個別に、区からこういったプロポーザルの実施について申し入れたといったことは、行ってございません。","voiceIndex":32,"id":"exchange-012"},{"speaker":"田中委員","kind":"提案","question":"審査結果のことについてなのですが、６７％というのは若干低いような印象を持ってしまうところがあるのですが、今回のご提案された内容はこういうことなのですが、例えば、区側から採点の低いものに対して改善を求めるようなことが、先方に伝えられ、受け止めてもらえるのかどうか、その点はいかがでしょうか。","respondent":"高梨公園課長","answer":"現段階におきましては、事業者にそれを伝えてございまして、事業者もしっかりとそれを真摯に受け止めて、今後協議をしてつくり上げていきたいという回答を得ているところです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"田中委員","kind":"提案","question":"審査結果のうちの一番下の、提案額の妥当性が、ポイント的には低いと思えるのですけれども、この評価というか、どのようなことなのかというのを確認したいのですが、要は、予算額に対してそれを超える、相当上回るような提案があったから、評価として低いのか、あるいは、予算に対してそこまで至らない、過小の提案だったために、こういう評価になってしまっているのか、そこはいかがなのでしょうか。","respondent":"高梨公園課長","answer":"その予算額に対して、どれだけ低減されたかといったところで評価をしています。ここの部分につきましては、予算とほぼ同額といったところですので、中庸な評価という形で、こういった配点になっているところです。","voiceIndex":36,"id":"exchange-014"},{"speaker":"田中委員","kind":"提案","question":"附帯事項の中で、設計費に関わる経費の妥当性云々とありますが、ここで経費をさらに抑える方向で働いてしまうと、逆にそれより上の提案の内容が、質的にとか、量的に下がってしまう可能性も、仮に出てしまったとすると、この採点はもっと下がるようにも感じられてしまうのですが、要は、最小の費用で最大の成果を上げるという、最小の費用だけを求めるだけではなく。","respondent":"高梨公園課長","answer":"附帯意見のほうの経費の妥当性は、同じ経費の妥当性で分かりにくいのですが、こちらにつきましては、区が予算額を示したものではなく、その先、将来にかかる実施設計や工事監理等々の費用については、まだ区が予算額を示していないので、その妥当性については。","voiceIndex":38,"id":"exchange-015"},{"speaker":"田中委員","kind":"提案","question":"提案の内容がどうなのかは分かりませんけれども、例えば私の思いとしては、大井競馬場もぜひ品川競馬場にしていただきたいし、これは都議会議員のときから言っていたのですけれども、ホッケー場も大井ホッケー競技場なのですが、つくる前から、あそこは大井ではなくて、住所は八潮ですし、それよりも何よりも、品川ホッケー競技場にしてくれと、ずっと言っていたのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-016"},{"speaker":"西本委員","kind":"提案","question":"すみません、１点だけ確認させてください。事業者の方が、このような提案をしたいのだけれどもといったときに、「それは予算を超えるから難しいです」とはしてほしくないのです。自由度は高められるような予算取りというか、やみくもに予算を上げるべきとは思わないですけれども、いろいろ提案を事業者の方がしてきて、だけれども、それにはやはりお金が必要だ。","respondent":"高梨公園課長","answer":"事業者もやりたいことというところを、コミュニケーションを取りながら、場当たり的な形にならないような形で、計画的に、予算につきましても事業の進捗につきましても、進行していけるように区として取り組んでまいりたいと思います。","voiceIndex":42,"id":"exchange-017"},{"speaker":"西本委員","kind":"提案","question":"ぜひ、いろいろな提案があるし、状況も変わっていきますので、柔軟に対応をお願いしたいと思います。それと、これは意見として聞いていただければと思うのですが、多分、指定管理者という形になっていくのだろうと思うのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"すみません、聞き忘れまして。外部有識者の意見書を今回もらっているということですけれども、外部有識者の方を選定委員にしなかった理由を伺いたいと思います。ほかにいろいろ選定する中では、外部有識者の方が入ったりしていると思うのですが、そこを伺いたいのと、ヒアリングを事業者にしたときに、先ほど来、説明の中で少しずつ出ていますけれども、どういったやり取りがあったのかを教えていただければ。","respondent":"高梨公園課長","answer":"これから、リニューアルについても複数年で、我々としましては、出来上がった水族館が、また何十年という形で付き合っていく施設ですので、会社としての取組の意欲、複数年にわたってやるといった体制の部分等、質問が委員から出されたという状況でございました。","voiceIndex":46,"id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に意見だけ。今回、これまでのプロポを参考にして、選定委員を選んだということですけれども、この間、指定管理者などで外部委員が入って選定していると思いますので、今後そうした有識者の方を選定委員に入れて、やっていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"まつざわ副委員長","kind":"確認","question":"すみません、確認だけさせてください。公募で１者ということで、その中から、選定も大分ご苦労されたというのは、質疑の中で確認が取れました。それで、事業者が選定されまして、多分、これから基本設計に入ります。","respondent":"高梨公園課長","answer":"そういったところでも意見をいただきますし、これから事業者とも打合せしてまいりますけれども、かねてからご案内をしております区民アイデアの募集であるとか、区民向けの説明会、周辺にお住まいの方々に対しても、また個別の説明も必要でしょうし。","voiceIndex":50,"id":"exchange-021"}]},{"id":"topic-03","title":"しながわ区民公園北側ゾーン改修工事（第二期）","agenda":"しながわ区民公園北側ゾーン改修工事（第二期）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"変更内容の（２）と（３）のところで、これがどこに当たるのかという場所と、これが変更されることでの区民への影響とか、そういったところはあるのかどうか、伺いたいと思います。鉄鋼スラグ状の固い地盤が確認されたということで、それはそのまま残されているということですね。では、ほかの質問に答えていただきたいと思います。","respondent":"高梨公園課長","answer":"変更を行った場所についてですが、（２）の部分はテニスコートの舗装を全部やり替えてあります。舗装を撤去したところ、本来であれば下の部分に砂地というか、土砂があるはずのところに、鉄鋼スラグ状の固い地盤が確認されたといったところです。","voiceIndex":57,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"鉄鋼スラグの関連で、これがあったために排水施設が作れなかったということなのですが、これは完全に埋め戻して、そのままにしてしまった、表面をテニスコートにしたということなのだと思いますが、いわゆる土壌調査といいますか、そういった観点からは、戻したとしても、環境影響上問題はないということも確認した上で、そういう対応を取られたのか、お聞かせいただきたいと思います。","respondent":"高梨公園課長","answer":"テニスコートの舗装を撤去したところ、それが確認されて、テニスコートは、今までも支障もなかったということで、これからも十分問題ないということと、今ご質問のありました、残しても大丈夫かどうかというところは、先ほど申しましたとおり。","voiceIndex":60,"id":"exchange-023"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"まつざわ副委員長","kind":"質問","question":"公園の中で、看板のことだけ一つ言いたいのは、少し前になりますけれども、委員会で言わせていただきましたが、禁止看板を、禁止ではなくて、できる看板と、たしか私もこの足立区のをいいなと思って、質問させてもらったのです。","respondent":"高梨公園課長","answer":"可能な限り説明を尽くしているところではありますが、四六時中迷惑を被っている方の立場としましては、強い表現で一刻も早く迷惑行為をやめてもらいたいという気持ちも分かるところでございまして、そういったところのバランスを見ながら、ただ、そういったご意見の中。","voiceIndex":66,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"少し細かいところから質問といいますか、意見も含めてお願いいたします。それから２つ目が、樹木なのですけれども、これは要望を時々いただくのです。品川区は、樹木に対しては結構しっかりやられていると思っていて、ネームプレート、木の名前というのをなるべく書いてほしいのだと。鳥籠と呼んでいるのでしょうか、あれはいろいろあると思うのです。それについてのお考えを示していただきたいと思います。","respondent":"高梨公園課長","answer":"現在、施設の在り方とか、どういった連携の仕方ができるかというところについて、地域の各団体の方々とお話を進めているところですので、委員からご紹介のありました視点をしっかりと区としても把握し、地域の方々と話合いの中で、いいものがつくれるように。","voiceIndex":69,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"ここからは意見なのですけれども、これから公園整備の計画がなされていくのだろうと思いますが、ここは公表して、皆さんに理解をしていただきたいと思っています。いろいろなお祭りも盛大にあって、いろいろな方々が関わっているという公園ですので、うまく民間の方々とのコラボレーションができるように、交通整理が必要なときには交通整理、けれども出過ぎずということで、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"公園をつくりやすい場所と、そうでない場所、近隣に多くある場所と、町会内に一つもないという場所、２７４あってすばらしいのですけれども、その配置の状況も、ぜひ満遍なくといいますか、均等に身近なところに憩いの場として設けていただけるような取組を、ぜひお願いしたいと思います。最近ですと、新たな土地が出たときに、手順としては、企画部がまとめるのでしょうか。","respondent":"高梨公園課長","answer":"その旨の認識は、企画部としても持っていただいているものと考えていますので、基本的には、そういったところの優先度を高めてやっていきたいのですが、品川区内は、適地に適当な広さの土地というのがなかなか出てきづらいといったところですので、数少ないチャンスを。","voiceIndex":73,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"最近、確かに、なかなか新たな土地が見いだせない中でも、目黒線の地下化に伴って、その上部を緑道公園にしたりとか、既に先行して池上線の上部もそうですし、また、今回もＰＦＩの対象になっている東品川海上公園は、東京都の下水道局のポンプ場の上を利用してということでもありますし、勝島運河の先のところも多分そうだと思いますが、そのようにいろいろな併用した中での新たな土地の活用という視点で。","respondent":"高梨公園課長","answer":"もともと再開発は、地域の様々な課題解決を目的に行われているものですので、周辺の道路の拡幅であったり、場合によっては道路の新設であったり、その中で、周辺の状況等を見まして、公園や広場が少ないといったところは。","voiceIndex":75,"id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"国が入るのかどうか、そこも確認なのですが、要は、特定のために財源が入ってしまったために、公園を一旦はつくったけれども、時代の変化だとか周りの変化に伴って、その土地を別の用途に活用するといったときに、可能かどうかということと、ある場所では財源が公園用地として入ったために、それ以外の多目的のものには活用できない縛りがあるということも、一部にあるかと思うのですが、要は。","respondent":"高梨公園課長","answer":"別の視点、公園という視点で見ますと、都市公園法上の公園として指定をする、もしくは都市計画公園として指定をするということになりますと、そこは一定程度、恒久的に公園として指定をするということですので、例えば都市計画公園を外すということであれば。","voiceIndex":77,"id":"exchange-029"},{"speaker":"田中委員","kind":"質問","question":"分かりました。財源的には、多分、区なので、また同じ公園という範疇のものですから、例えばですが、場所によってはこれを入れ替えるといったことも、それがいいのか悪いのか、どういうメリットがあるのかというのも、それぞれの判断はあるのですが、そういう対応というのは可能なのでしょうか。","respondent":"高梨公園課長","answer":"最後、ご質問にありました、財源を入れた児童遊園等の入替えというところについては、それは補助金を所管している国であったり、東京都の判断というところがあろうかと思うので、ここで断定的なことは申し上げられませんけれども、いただいた額に相当するものということで。","voiceIndex":79,"id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"より有効に活用していただく配置が必要なところは、いろいろな手法を取ってご対応いただくことで、全体的な公園の評価の価値を高めていただけるようにお願いしたいと思います。その辺の今後の、１か所だけではあれなので、全体的な視点ならば考えられなくないというお話が以前あったかと思うのですが、その辺の、まず電源に関しての考え方をお聞かせいただきたい。","respondent":"高梨公園課長","answer":"ただ、今、公園の施設の様々な防災関連の製品の中では、公園の中に公園灯があって、上にソーラーパネルがあって、その電源を、スマホの充電ぐらいの容量であれば発災時に使えるという製品は、実際の遊具メーカー、公園施設メーカー等から出てきているというのがありますので。","voiceIndex":81,"id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"私は必要だと思いますので、ぜひご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":83,"id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"一つはトイレについて、先ほど洋式化を進めているということで、ぜひそれは進めていただきたいと思います。それと、公園が町会に１か所もないところというところで、優先度を上げてやっているということですので、ぜひそれを私からも、公園がつくれるように進めていっていただきたいと要望しておきたいと思います。","respondent":"高梨公園課長","answer":"バリアフリートイレ、だれでもトイレの中には、介助用ベッドということで、大人の介助ができるようなシートの設置も現在進めているところです。","voiceIndex":85,"id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいと思います。ボール遊びができる公園は、ぜひ増やしていただけたらと。それと、公園内にあるフットサル場、スケートボード場、ボルダリング場、これは、子どもたちが利用するというところで、ぜひ無料にしていただきたいと思うのですけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"ただ、例えば砂場に猫であったり、そういったものが入らないように柵がありますけれども、その柵と一体化したような屋根が作れないか等々、遊具メーカーにいろいろとヒアリングしながら、砂場になかなか日陰がなくてという声は公園課でもいただいてありますので。","voiceIndex":87,"id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"遊具のところは、砂場の屋根も検討されているということですので、ぜひ進めていただきたいと思いますし、施設の無料化は、ぜひ誰でも利用できるように進めていただきたいと、改めて要望しておきたいと思います。大体町会の方とか、そういうことになってしまうと思うのですが、それをさらに広げて、多くの利用者も含めて、声を聴いていただきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"ただ、１本も切らないのかどうかということにつきましては、提案の内容とか、また、中には古い樹木等もありますので、そういったところを総合的に勘案しながら、樹木等の対応については取り組んでまいりたいと考えています。","voiceIndex":89,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、面積としては、最大ですけれども２,０００m2余ということで、なかなかの広さだなと。そうなると、樹木の伐採なども出てきますし、これまでの公園の利用ができなくなってしまうということにもなりかねないかなと思いますので、そういったことも考慮いただきたいということで、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4396#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":38051,"voices":98}},{"id":"r05-20231128-9","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"文教委員会","time":"午前１０時０７分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","agenda":"第１０１号議案 学校教育職員の給与に関する条例の一部を改正する条例、(2)第１０２号議案 幼稚園教育職員の給与に関する条例の一部を改正する条例の２議案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"勤勉手当というのはどういう手当なのか、改めてご説明いただきたいのと、あと今回、一般職の特別給の改正というのは、全て勤勉手当に割り当てるということでしたけれども、その理由ももう少し伺いたいと思います。","respondent":"中谷指導課長","answer":"今回、一般職員につきまして勤勉手当に割り当てるというところですけれども、こちらは、民間の支給状況と比較というところにおいて割り当てるというところで、一般職員は勤勉手当に割り当てるというような結論となったものです。","voiceIndex":5,"id":"exchange-001"}]},{"id":"topic-02","title":"第３回～第５回品川区学事制度審議会の実施報告","agenda":"第３回～第５回品川区学事制度審議会の実施報告","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"前提として、パブリックコメント前の文教委員会の報告だと思うのですけれども、パブリックコメントにかける内容が全く示されていないというところで、審議会の内容も確認しようと思ったのですけれども、第３回までしかホームページに出ていない。議事録要旨もまだアップされていないということで、どうなのかという。議会を軽視していると言われても仕方がないと思うのですけれども、いかがでしょうか。","respondent":"柏木学務課長","answer":"パブリックコメントですが、中間答申については現在、最終調整をしているというところで、文言の表現の修正等を今実際行っているところですので、現段階ではお示しできないです。","voiceIndex":28,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"それで、「検討が必要となる学校の再確認」というような文言がありますけれども、検討が必要となる学校とはどこなのでしょうか、伺いたいと思います。それと、中間答申の案を作成するに当たって、当該学校の学区の地域からの声や意見はどのように聞いたのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"それと、地域の意見聴取ですが、メンバーの委員の中に地域の代表等が入ってありますので、そちらから意見等はいただいてあります。","voiceIndex":30,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"となると、中間答申というものに行く中には、検討が必要となる学校の名前というのは一切入っていないということでよろしいのか、伺いたいと思います。明かさない以上は、検討が必要な学校の地域の意見を聞いているかどうかも分からないということになってしまうのですけれども、それでいいのでしょうか、伺いたいと思います。","respondent":"柏木学務課長","answer":"答申に具体的な学校名が出るかですが、学校ごとに学級数の状況については資料として出す予定です。それと、地域等の意見等です。","voiceIndex":32,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"結局、前回の資料ですと、この後８回なのです。そしてもう一つは、どうやって具体的に影響がある地域の方の声を伺うのですか。伺うつもりがあるのでしょうかというふうに私は思うのですけれども、あまりに不十分といいますか、それだと進め方としても問題があるのではないですか。地域から相当、ハレーションが起こるのではないでしょうか。どうでしょうか。","respondent":"柏木学務課長","answer":"それと、地域の声ですが、こちらも一部、繰り返しになりますけれども、審議会で、地域の代表等も入っていますので、そこで受けてあります。最終的な答申を受けまして制度設計をするときには、また個別の地域等とはお話をさせていただきたいと考えています。","voiceIndex":34,"id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"伺いたいのは、つまり中間答申のみならず、答申にも、ではどこの学校をこういうふうにしますという学校の変更案が出てこないということなのか、確認させてください。それと併せて、第２回では委員から、学校の新設も含めて検討するのかという質問が出ていたのですけれども、私も必要な検討材料の一つなのではないかと思うのですけれども、検討の俎上には上ったのかどうかも併せて伺います。","respondent":"柏木学務課長","answer":"答申に個別的な学校の具体策というのが出るのかという、こちらも繰り返しになりますが、区全体としての、こういうときにはこういう方策等を検討したらどうかということですので、個別的にこの学校を答申でこうしなさいというものは出てこないと考えています。","voiceIndex":36,"id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"だから、結局、答申にもそういうことを書かないで、最後、教育委員会の任意みたいな感じになってしまっているようにしか聞こえないので、それは私は進め方としては、これだけ大きな影響を受ける地域にとっても、地域コミュニティの核の学校なわけですからどうなのかと、私は問題があるのではないかと思います。それは埼玉県の話だったのですけれども、どのような意見だったのでしょうか。","respondent":"柏木学務課長","answer":"１つ目、再開発の抑制等の件ですが、委員からある自治体を例にして、そういうことは品川区で可能かというお話は、意見としては出てあります。それと、中間答申の説明会ですが、実施する予定はございません。","voiceIndex":38,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"なぜ実施する予定がないのかというのを教えてもらいたいのと、あと私は先ほど、まちづくりの点では、そういう意見が出たわけではないですか。やはり教育環境に直結する問題だから言っているわけです。だから私は、他人事ではないのではないですかと言ったので、そこについても教育委員会のお考えを伺いたいと思います。","respondent":"柏木学務課長","answer":"説明会の件ですけれども、中間答申は区全体のことで分かりやすく示していますので、ご覧いただければ、説明会等なくてもご理解いただけるのではないか、ご意見も寄せられるのではないかと考えています。","voiceIndex":40,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"令和６年度当初から、通学区域を具体的にどう設計していくか進めていくということと、令和７年度から新制度の適用の開始を目指すことの２つが示されたと思いますが、ここでお聞きしたいのですが、よく地域からの声で上がっているのが、例えばなのですけれども、勝島に住んでいる方々が、どうして八潮学園ではなくて。","respondent":"柏木学務課長","answer":"区民の声の反映ですが、すぐできるもの、できないものが、正直ありますので、そういうご意見をいただいているということについては、いろいろな場でその部分も含めて検討し、区民の声等には回答させていただいているところですが、正直、通学区域を変更するというのは。","voiceIndex":43,"id":"exchange-009"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"私たち生活者ネットワークとしてはずっと、パブリックコメントがあったら、もう近隣の方には、パブリックコメントがあるから、ぜひ区民の声として出してくださいとお伝えしているのです。傍聴もしていますので、大体これは合っているということも判断できるのですけれども、学事制度審議会について、要旨であって発言録にはならないという理由が何かあったら教えていただきたいと思います。","respondent":"柏木学務課長","answer":"発言録等の公表ですが、発言録ですと、発言された方が特定されてしまうという部分で、審議で自由濶達なご意見等を本当に今いただいているところですので、そういう部分が制限されてしまうおそれがありますので、現状では発言録については公表する予定はございません。","voiceIndex":47,"id":"exchange-010"},{"speaker":"吉田副委員長","kind":"確認","question":"それを特定しない方法は幾らでもあると思いますし、障害者のほうはどうでしたっけ。だから時間がかかるので、やむを得ないと思うのですけれども、そういうことも一般的には、インターネット上の公開でなくても、公式な議事録・発言録として一般的に公開する場合には、発言者の確認は必ず取るはずです。そういう形を教育委員会事務局として取ることは可能だと思うのですが、いかがでしょうか。","respondent":"柏木学務課長","answer":"発言録ですが、正直、中で、本当に具体的に自分のお住まいの地域等を含めての発言等が結構多くありますので、委員Ａ、Ｂにしたとしても、分かる人には、この人だというのが分かってしまう、個人が特定されてしまうというおそれが、審議会の運営を見ていましてもありますので。","voiceIndex":49,"id":"exchange-011"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"やはり、それぐらいは発言には責任を持っていただきたいと思いますし、できるだけ、一般的にもう、すぐ個人が特定されてしまうような表現は確かにいかがなものかと思いますけれども、その辺は工夫をしていただいて、こういう発言ということで発表しますということを確認していただいて、ここについては、このとき言い過ぎてしまったから直してくださいなどというのはありかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-012"}]},{"id":"topic-03","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それを求めた上で、同時にここまで来ると、対症療法だけではなく、根本原因にも目を向けた抜本対策も必要なのではないかと思います。伺いますけれども、品川区教育委員会は、なぜこのようにいじめの重大事態が頻発すると考えているのか伺いたいと思います。根本には、子どもたちのストレスの高まり、学校が楽しくない、つらいということがあるのではないかと思うのですけれども、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"ご指摘いただいた点につきましては、教育委員会も真摯に受け止めて取り組んでいるところですので、今後も引き続き、いじめの予防や、万が一いじめがあったときには適切に認知して早期対応を行っていくということを、しっかりと実施してまいりたいという考えです。","voiceIndex":56,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"私は、今のご説明を聞いても、子どもが、いじめへの理解が仮にされたとしても、それで、では子どもがいじめに走らなくなるか。だから、私が伺ったのはあれなのです。ストレスなのではないですか。子どもがすごく今、追い詰められている。そういうのがあるのではないかと思うのですけれども、そこについては、いじめとの関連性について、どのように考えているのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"そうしたストレスをキャッチしたところに、教員がどうアプローチしていくのか。教員だけではなくて、スクールカウンセラーや、我々の組織にいるＨＥＡＲＴＳ等も含めて、そうした子ども一人一人の支援というものに努めてまいりたいと考えています。","voiceIndex":58,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"だから私は、いよいよそういうところに目を向けて、自分たちが子どもたちを追い詰めているという自覚を品川区教育委員会は持たなくてはいけないと思っているのですけれども、そういう点でどうでしょうか。先ほど、自らの教育施策が子どもたちのストレスの１つの要因であることは理解するというお話でしたけれども、やはり加速させているという自覚はあるのでしょうか、ないのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そういったところからも、学校教育は少しずつ変わっているところですので、それがストレスを加速させているとは考えてはございません。","voiceIndex":60,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"論争はあると思うのですけれども、私はもう少し自分たちの、これは国連・子どもの権利委員会からも、日本の教育は競争し過ぎると毎年指摘されているわけですから、それで、その先頭に立ってきたのが品川区の教育なのですから、その自覚を持っていただきたいと私は強く思います。","respondent":"丸谷教育総合支援センター長","answer":"市民科の例えばスチューデント・シティといったところの様子を見ると、子どもたちは本当に生き生きと活動していますし、そういった取組をしっかりと、根差していく、継続させていきながら、子どもたちにとっての学びの充実を図り、発見することが楽しい。","voiceIndex":62,"id":"exchange-016"},{"speaker":"ゆきた委員","kind":"質問","question":"現在、いじめの重大事態が６件あると報告を受けています。昨日、品川区のいじめ防止対策推進条例の一部を改正する議案で、いじめ対策委員会に臨時委員を設置できるようになると審議がされましたが、現在の品川区のいじめ対策委員会は、設置が５名以内で、４名で構成されていると聞いていますが、今現在、この６件の重大事態について４名で対応されているとの認識でよろしいでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"本体に対して諮問をしたところなのですけれども、今後この条例が改正されれば臨時委員を設けることができますので、この６件についてどう割り振っていくかというところは、今後、円滑に調査が進むように検討していきたいと考えております。","voiceIndex":65,"id":"exchange-017"},{"speaker":"ゆきた委員","kind":"質問","question":"今後は臨時委員も設置されていくと思われますが、条例にのっとることももちろんですが、公布されるまでの間の継ぎ目の期間、この間の期間の暫定的な措置があるのかないのかについても教えていただければと思います。","respondent":"丸谷教育総合支援センター長","answer":"条例が公布されるまでの期間ですけれども、調査の方針や、調査結果をいつまでに出せるかというところの検討は進めていきながら、円滑に引継ぎ、つなぎができるように努めてまいります。","voiceIndex":67,"id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それには、私は数字にあまりとらわれてほしくなくて、どうしても件数が出てしまうと、いろいろな方面から、そんなに品川区はあるのかなどと、もちろん言われることもあるのだけれども、ただ、そこに今とらわれてしまうと、解決できるものもできなくなってしまうと私は思うので、ぜひそこは、今この時期は、そうやって本当に一生懸命、洗い出しているからこそ浮き彫りになってきて。","respondent":"丸谷教育総合支援センター長","answer":"そこは、件数などにとらわれることなく、しっかりと一人一人の、被害に遭った児童・生徒、加害の児童・生徒に対して適切に対応していくという考えで取り組んでまいりたいと考えております。","voiceIndex":70,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひリアルなものを教えてくれ」という気持ちを示すことによって、学校側もリアルなものを提出しやすくなる環境になると思うので、その環境づくりを、ぜひつくっていただきたいと思いますし、ストレスの部分もそうで、まさに各子どもたちがいろいろな考えを持って、多分、いろいろなストレスの発散方法が、昔と違って特にそれぞれ違うのかと思うので、そこはある意味、スポーツもそうだし、昨日。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-020"},{"speaker":"せお委員","kind":"質問・要望","question":"この２件なのですけれども、お伝えできる範囲でいいのですけれども、報告までの経路というか、何というんですか、例えばＨＥＡＲＴＳを挟んでの教育委員会なのかとか、学校から直接来たのかという、そういうところをお話しできる範囲で教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"いずれも、２号、いじめに遭って不登校になったケースということで、いじめの報告と併せて不登校の報告が教育委員会に上がってきます。","voiceIndex":74,"id":"exchange-021"},{"speaker":"せお委員","kind":"質問・要望","question":"今のやり方がもしかしたら正しいかもしれませんし、件数が上がってきて、そういったところもぜひ一緒に検証していただきたいというところを要望します。本当にすばらしい言葉がいっぱいあったのですけれども。正直、支援学級でいろいろな体験をさせていただいているのです。体験の授業がすごく多いという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"それで、その調査の結果、どういう対応を教育委員会および現場がしていくというところで、今の区の姿勢で、さらに真価が問われるので、ぜひしっかりとというか、応援するという意味を含めて、頑張ってと言うと失礼ですけれども、きちんとしていただけるとありがたいということを、まずお話しします。お尋ねしたいことは、学校種のところで、義務教育学校の前期か後期かを書いていないのはなぜなのかと。","respondent":"丸谷教育総合支援センター長","answer":"そういった児童・生徒に対しては、しっかりとした心のケアが必要だと考えますので、スクールカウンセラーとの連携やＨＥＡＲＴＳの支援等も含めて、継続的に行っていきたいと考えております。","voiceIndex":78,"id":"exchange-023"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さっきのいじめを見てということなのですけれども、特に、いじめを経験したお子さんが、１年生のときに解決しました。それは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-024"},{"speaker":"吉田副委員長","kind":"質問","question":"私から伺いたいのは、例えばいじめの態様の分類については、これが文科省の文部科学大臣決定から、この文言をと、そのまま書かれているようなのですけれども、具体的にはもう少し、何というか、細かいいろいろな個別のケースがあると思うのですけれども、そういうことが報告されているのを、今日、委員会に向けた報告のためにこのようにまとめられたという理解でよろしいのでしょうか。","respondent":"丸谷教育総合支援センター長","answer":"そうしたところでの、８つ示された中でのものということで、実際にはもう少し、いじめの事案としては、絞った形での報告も上がっていますし、それを基に調査を行っていくということになっています。","voiceIndex":81,"id":"exchange-025"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"報告が必要ですので、報告のために、書式にのっとった形で報告されているということで理解いたしました。それで、先ほどからも、原因ということであれば、１つはやはり承認欲求というのは、いろいろな意味で、いじめというのは、ある意味で承認欲求が悪い方向に働いてしまった事例なのではないかというのを感じることがあります。もし何か見解があれば伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"これはいじめに当たるという意識がというところで言うと、児童・生徒の理解というところにつながっていくと思いますので、そういうことも認識を深められるようないじめ予防プログラムを検討しておるところですので、引き続き、教育委員会として努めてまいりたいと考えております。","voiceIndex":83,"id":"exchange-026"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"最後に、本当におっしゃるとおりだと思いますので、それは現場の先生方にとってはまた難しい対応ということになってしまうのかもしれませんけれども、その辺については、ぜひよろしくお願いいたします。ですので、そこでやはり、まずは本人の言い分を聞くという。でも、まずは本人の言い分を徹底的に受け止めるということは、ぜひ教員の方には徹底していただきたいと思います。これは要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-027"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"あまりにも保護者が学校に頼り過ぎという部分もあると私は思うのです。それは、シングルだろうが、いろいろそれぞれ家庭の事情はあると思うのですけれども、やはり一番は保護者が寄り添うというのが、加害者・被害者に対しても、絶対それはもう最終的には家庭教育というのが一番だと私は思っているので、もし、ほかに何かお考えがあれば教えていただきたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"やはり、いじめの定義の共通認識を、子どもも教員も保護者も、教育委員会は当然ですけれども、共通理解をした上で議論していかないと、どうしても話がずれてしまったり、かけ違ってしまったりしてしまいますので、そういった家庭への啓発ということも。","voiceIndex":87,"id":"exchange-028"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ家庭への啓発は、改めて私からお願い、要望させていただきたいと思いますので、もう本当に当然、教育委員会の皆さん、そして学校側の現場の先生方も、もう一回、繰り返しになりますけれども、本来ならば教育の場でいじめというのはあってはならないのですけれども、これは大小なりとも、今後、根絶というのはなかなか難しいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-029"},{"speaker":"高橋（し）委員","kind":"意見","question":"最後に一言。今、ほかの委員の方から、先生が当てにならないというお話があったのですけれども、保護者の方の考えなのか、委員の考えかはあれですけれども、それは考え方なので、そういうのはいいのですけれども、それに対して教育委員会としてどうかというのはお答えいただいたほうがいいと思ったので、お尋ねします。","respondent":"丸谷教育総合支援センター長","answer":"対応が適切ではなかった場合に、こちらから指導・助言、校長・管理職からも、その教員に対して指導していただいて、保護者との関係を修復するような形を取らせていただいているところです。","voiceIndex":91,"id":"exchange-030"}]},{"id":"topic-04","title":"ヤングケアラー調査の実施結果について（速報）","agenda":"ヤングケアラー調査の実施結果について（速報）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"大変重要な資料だと思って聞いていましたけれども、特に悩みなど相談できない方や、聞いてほしいという方が多いというのは、本当に深刻というか、何とかしてあげたいと強く思う内容だと思いました。２点伺うのですけれども、まず調査のやり方なのですけれども、送付して、どんなやり方で、どういうふうに回収したのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"今後のスケジュールというお話ですけれども、まず、一部並行してという作業にはなってまいりますが、今回出ているアンケートの結果を、次年度の予算にも支援策として反映していきたいと考えているところと。","voiceIndex":98,"id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"すみません。高校生のほうですけれども、これは全ての区内在住の高校生の数かということと、小・中学校は、区立校についてはそういうことだということなのですけれども、タブレット以外にも何か回答の仕方というのはあったのかということと、区立小・中学校ではない子というのはどうしたのかを教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"私立の小学校に通われているお子さんにつきましては、直接ご自宅にご案内を郵送させていただいてご回答いただいているという状況です。","voiceIndex":100,"id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問","question":"アンケートの結果から、家事援助の訪問支援や配食サービス、学習支援が必要なのだという実態が分かってきていますが、８月の文教委員会では、今年度はヤングケアラーについて既に予算化されているというお話もあったと思います。これからだと思われますが、具体的なところで決まっている事業等など、紹介できる範囲で教えてもらえればと思います。","respondent":"染谷子ども家庭支援センター長","answer":"そのほか、今回、実施を予定しているものの中で１つ、ピアサポートといいますか、当事者同士が集って、悩みのお話合いができるとか、区に配置しておりますヤングケアラーコーディネーターも併せて、そういったところでお話をしていくと。","voiceIndex":104,"id":"exchange-033"},{"speaker":"ゆきた委員","kind":"意見","question":"このアンケートも引き続き継続していきながら、この結果について反映できるような事業の展開を、ぜひともよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":106,"id":"exchange-034"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そこの子たちに支援が必要であって、ほかの子たちにはどちらかというと、それが駄目というよりも、逆にお手伝いをしてあげてというか、例えばきょうだいの面倒を見てあげてみたいな方向に、うまくつなげていかないと、せっかくこうやって一生懸命、区で今やっていただいているので、もったいなくなってしまうので、そこはぜひ気をつけて取り組んでいただきたいと思いますけれども。","respondent":"染谷子ども家庭支援センター長","answer":"今お話しいただきましたとおり、まさにお手伝いと、ヤングケアラーというケア負担が実際に発生しているようなところの境は非常に重要なところで、本来、子どもとして生活していく権利が侵害されているような状況があれば、まさに支援の対象として。","voiceIndex":108,"id":"exchange-035"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いします。実はケアをされている子も、その経験が将来生かされることも十分あるし、これはもう本当に、だから私が一番初めに言った、何でもかんでも駄目という、ヤングケアラー、イコール、よくないのだというのだけは、考えから取っ払っていただいて、ぜひいい方向に進んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"ご説明ありがとうございました。貴重な調査で、回答者の回答率など、もう少し高いと、実態にもう少し近づいたのではないかと思いますけれども、このパーセンテージでこれだけということは、数字的に言うと、きっともっといらっしゃるのではないかというところがあります。ご質問は、この内容は、学校、特に区立小学校、中学校にどのようにして伝わるのでしょうか。","respondent":"染谷子ども家庭支援センター長","answer":"学校の教員の皆様にも、ぜひこちらを共有させていただきたいと思いますので、教育委員会事務局と相談をさせていただければと思います。","voiceIndex":112,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それで、何が言いたいかというと、だれかに話したことがありますかというのは、きっと小学生だと先生などが多いのかという気もしますので、中学生もそういう部分があると思うのですけれども、それで、してほしいところに、話を聞いてほしいのと、あと、家族のことについて話を聞いてほしいというのが小学生にあり、中学生なども同じで、特に中学生は、勉強を教えてほしいというところもあるので。","respondent":"丸谷教育総合支援センター長","answer":"そうした上で、今回の調査結果につきまして、自校にいる子どもたちはどうなのかというところを、アンテナを高く張っていただいて、該当者がいるようでしたら、子ども家庭支援センターとも連携をしながら、その子のケアに努めていきたいということと、あとは学習支援であったり。","voiceIndex":114,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"回答率がこのぐらいのパーセンテージで、小学校だと１学年にコンスタントに１人いる。中学校だと、学校全体で１３、４、５人だから、１学年には４、５人いるということは、１クラスに１人いるという。単純な計算ですけれども、そういうところから、やはり、今お話があったような指導をきめ細かくしていただきたいと思います。これは要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-039"},{"speaker":"せお委員","kind":"質問","question":"今までも議論というか話がありますけれども、やはり感じ方も様々で、「つらい」と感じるときはありますかで、「まったくない」という人も一番多いですし、「いつもある」という方もいらっしゃるので、感じ方も様々だし、あと、その要因も様々で、かなり支援メニューというのは様々準備しないと、それは支援にならないのかというのは感じているところで、今では、私は把握していないのですけれども、今。","respondent":"染谷子ども家庭支援センター長","answer":"あと在宅介護支援センターにいらっしゃるケアマネジャーの方たちを対象とした研修なども実施しておりまして、ご自宅を見られるときに、ヤングケアラーという視点を１つ持って見ていただくというところについても、研修・啓発を進めているところです。","voiceIndex":118,"id":"exchange-040"},{"speaker":"せお委員","kind":"質問・要望","question":"庁内連絡会議を開いていただいているということなので、ぜひそれが１回で終わらず、定期的に続けていただきたいと思っています。やはり、先ほどからお話がありますけれども、かわいそうという空気になっているから、それは嫌だというお話などもあって、そういったいろいろな考え方があると思いますので、その辺もぜひ配慮していただきながら、庁内でも検討していただければと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-041"},{"speaker":"吉田副委員長","kind":"提案","question":"仕組みは最初につくっただけではやはり意味がないので、その運営というのでしょうか、それが大事だと思います。それで、定期的な協議を進めてほしいというのは、先ほど、せお委員からもご要望がありましたけれども、今既に、今後こういう調査を生かしてどういう協議を進めていくかというようなスケジュールがありましたら、教えていただきたいと思います。その１点。","respondent":"染谷子ども家庭支援センター長","answer":"今後、この調査の結果に基づいて、どういう形で仕組みをつくっていくかというところにつきましては、やはりこれまでと同様、子ども未来部のみで検討を進めていくものではないと思いますので、具体的支援策を実際につくっていく中でも。","voiceIndex":122,"id":"exchange-042"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"ですので、ここは教育委員会ということで、中学生、高校生、大学生まではテリトリーではないのかもしれませんけれども、そういうヤングケアラーもいらっしゃるということを視野に入れて、相談窓口や、何かそういうケア、もちろん家事支援やレスパイト支援をぜひお願いしたいのですけれども、そういう方たちもいらっしゃるということを片隅にとどめておいていただいて。","respondent":"染谷子ども家庭支援センター長","answer":"それで、今お話しいただいた事例のとおりで、ケアの責任や負担というのがすごく重くなる一方で、ご本人の将来を決めるような重大な選択をしなくてはいけないような状況というのが若者ケアラーの中にあるかと思いますので、そういった方たちに向けて。","voiceIndex":124,"id":"exchange-043"}]},{"id":"topic-05","title":"東京都からの一時保護受託の実施","agenda":"東京都からの一時保護受託の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２３区中２２区で児童相談所ができていくわけなのですが、一時保護の場所については、保護者が子どもを強引に連れ戻しに来るケースなどもあると思うので、必ずしも品川児童相談所で品川区の子どもを一時保護するわけではないとは思うのですけれども、開設後の一時保護における他区との役割分担や連携のルールというのは、もうつくられているのでしょうか。どのような中身になるのか、伺いたいと思います。","respondent":"長谷川児童相談所開設準備課長","answer":"一時保護した子どもの取扱いや、措置する場合のルール等につきましては、東京都がこれまで実施してきた体制を基本的には踏襲する形を取ってあります。２３区共同体で、会議体を持っていまして、その中で、東京都と区児童相談所になった場合のすみ分けのルールをつくっております。","voiceIndex":131,"id":"exchange-044"},{"speaker":"安藤委員","kind":"質問","question":"その会議体の中でいろいろ話しているということだと思うのですけれども、２２区で児童相談所が全て出来上がったときというのは、もう既にそういう一時保護の預かり先のルールというのですか、そういうものというのは出来上がるという感じでよろしいのでしょうか。","respondent":"長谷川児童相談所開設準備課長","answer":"一義的にはそのルールに従いまして、その後に、保護した子どもの措置先や保護する場所等につきましては、先行で開設している区が東京都と協議して決定した内容に従い、品川区も保護するといった方針です。","voiceIndex":133,"id":"exchange-045"}]},{"id":"topic-06","title":"品川区内保育園等あり方基本方針素案","agenda":"品川区内保育園等あり方基本方針素案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それぞれ教えていただきたいというのが１つ。それと、「保育需要増減時のバッファとしての役割」と書いてあるのですけれども、バッファというのは、緩衝、ゆとりという意味を含むと思うのですけれども、結局のところ、どういう意味なのでしょうか。日本語に置き換えていいので、教えていただきたいと思います。結局どれぐらい減らす、何園減らすと想定しているのか、伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"これからの保育需要の変化を鑑みながら、当然、各地区によっても、あと年齢によっても、保育の空き状況といったものは変わってまいりますので、そういったものを総合的に勘案しながら、どの地区で、どの園をというところでの具体的な検討を今後進めするという予定です。","voiceIndex":139,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問","question":"「素案」が「案」になる。それで、「案」が「方針」になるときは４月だと思うのです。方針発表がここですから。といいますのは、何というのでしょうか、きちんと、こういう段階段階の検討委員会や文教委員会の意見を聞いてもらって、「方針」というものをつくってもらわないと困るという意味で聞いているのです。何で減らしてしまうのですか。その辺を伺いたいのが２点目。その２つをお伺いします。","respondent":"今井保育教育運営担当課長","answer":"委員からお話がありましたとおり、当然、今後パブリックコメントを実施いたしまして、そこで出た意見を反映させて、本日、委員会で報告させていただいて、各委員の皆さんからいただいた意見等も反映させていただいてということで。","voiceIndex":141,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"それと、少し細かいことで申し訳ないのですけれども、現在、「素案」ではないですか。区立園の統合がなぜ必要なのか、改めて伺います。そして、これは聞いてもしようがないかもしれないですけれども、保育園を統合するという方針を出されているわけですけれども、保育園を統合して保育の充実というのは、かなり無理があるというか、矛盾しているのではないかと思うのですけれども、いかがでしょうか。","respondent":"今井保育教育運営担当課長","answer":"３点目と４点目のご質問については、関連するものといいますか、お答えが重複すると思いますので、まとめてお答えしますけれども、委員から挙げていただきましたとおり、今現在、品川区もそうですけれども、全国的に保育のニーズの多様化が進んでおりまして。","voiceIndex":143,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"委員長、ありがとうあります。なので、私としては頂けない、内容的には大いに異論のある素案なものですから、「案」を「方針」にする上で、やはり、ぜひ多くの区民の方、そして議会などの意見も聞きながら決めていく必要があると思うので、しつこくやってしまいました。園を維持したまま、例えば定員を思い切って減らす、ゆとりある保育環境をつくるなど、できるわけではないですか。お願いします。","respondent":"今井保育教育運営担当課長","answer":"３点目が、民営化の進め方についてのご質問でございまして、委員のご認識のとおりです。","voiceIndex":148,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"ということで、パブリックコメントの意見は何件ぐらいを目標にされているのでしょうか。この時点で伺いたいと思います。様々な形で働いております、保育士、職員の方々への影響も相当あるわけですから、こうした方々の意見をどう集約するつもりなのか、そのお考えをお聞かせいただきたいというのが２点目。説明会の開催は、やはり絶対必要だと思いますけれども、いかがでしょうか。","respondent":"今井保育教育運営担当課長","answer":"最後、説明会の実施についてですけれども、今回お示ししたとおり、概要版も用意させていただきまして、なるべく分かりやすく、内容が伝わるように対応していますので、現状で説明会を実施する予定はございません。","voiceIndex":150,"id":"exchange-050"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"昨年、出生数が８０万人を切って、今年も７０万人前半になるのではないかと言われている中で、見立てとして、今後一定数、減少するのかという見立てもある一方で、今年に入ってから急に、異次元の子育て支援だ、少子化対策だと政府が言ってきて、私も期待したのだけれども、蓋を開けてみたら何もないから、そのまま人口減少になってしまうのかと思いながらも、品川区も様々、子育て支援なりを充実させて。","respondent":"今井保育教育運営担当課長、石井保育支援課長","answer":"お金の部分については、区立保育園の保育士に対してお給料をというところでは、なかなか検討が難しい部分はありますけれども、そのほかの部分で、例えば保育士同士で顔を合わせる機会があって。例えば在宅支援ということですけれども、今年度、国のモデル事業を使って、未就園児の定期預かり事業を実施しています。","voiceIndex":153,"id":"exchange-051"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もちろん外的要素というのはいっぱいあって、それはもちろん、その時々で本当にいつも考えていただいているのは十分分かっているのですけれども、やはりそこは改めて強く要望していきたいと思うし、できたら今後、区の方針の中にも、そういった部分も、できたら反映していただいて、区は本気で保育園を考えているという、本気度を見せていただく意味では、私は処遇改善というのは、やはり一定。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-052"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つだけですけれども、医療的ケアのお子さんの対応というのは大変すばらしいと思うので、検討も入れていただきたいのですけれども、配慮が必要なお子さんたちの対応が、今後検討していく中で出てくると思うのですけれども、保育園ごとにいらっしゃる配慮の必要なお子さんに対する対応は、現在も加配や、そういうものであれだと思うのですけれども、関西の自治体だと、１週間や２週間に一遍。","respondent":"今井保育教育運営担当課長","answer":"現状で、例えば品川児童学園と連携した保育所等の訪問支援等を実施していますけれども、今後もやはり区立保育園として、医療的ケアもそうですし。","voiceIndex":158,"id":"exchange-053"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか、新たにそういった施設を造って、そこに行くというのは難しいので、このように一定、施設に別の機能を持たせるというときには、そういうことが行われるチャンスだと思うので、ぜひよろしくお願いします。要望で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-054"},{"speaker":"せお委員","kind":"質問・要望","question":"私からも１点。なので、就学前のところで、ぜひ保護者の方々と関わっていただいて、何か本当、いろいろなところと連携した支援が必要なのではないかとは思っているのです。なので、今、就学後に対しての就学前で行っている支援というのはどういうものがあるのかと、あと、今後そういったところを何か新たに考えるというか、支援としてやっていく、取り組んでいくものがあれば、教えていただきたい。","respondent":"立木保育課長","answer":"特別支援の関係ですと、今現在も、特に就学に向けての年長児に関しましては、ほかの支援が必要でないお子様と一緒に、例えば保幼小連携、学校とも連携を取って、学校にお邪魔させてもらったりはしているのですけれども、それ以外にも、就学に向けて保護者の方へ。","voiceIndex":161,"id":"exchange-055"},{"speaker":"せお委員","kind":"質問・要望","question":"なかなか保護者にとって、何というのですか、気づいていないというよりは、自分のお子さんには支援が必要がないと、別に悪気なく思っていて、その後、就学してというところで、早めに支援があれば発達の成長なども早くなるのかというのは、すごく日々感じているところなので、先ほども巡回相談などもありますし、そういったところの支援も活用しながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-056"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ハード面のことでお尋ねなのですけれども、素案の１３ページで、施設の併設状況なのですけれども、代替施設なり、再整備という点においては、独立した園だったらできると思うのですけれども、それぞれ地区別で見ても、児童センターがそれぞれ都営住宅、それぞれ併設の状況を今お示しされております。お願いします。","respondent":"今井保育教育運営担当課長","answer":"今ご質問のございました、今後の進め方、手法の検討といった部分のご質問ですけれども、委員ご指摘のとおり、例えば併設の施設等々ですと、その併設されている施設との調整、利用が一定できなくなる部分や、工事で影響を与えてしまう部分といったところが考えられますので、一定。","voiceIndex":164,"id":"exchange-057"},{"speaker":"高橋（伸）委員","kind":"意見","question":"荏原地区でも、やはり源氏前保育園と旗の台保育園も併設になっていて、源氏前保育園は図書館になったり、あと旗の台のほうは公園のある児童センターになる。その交渉というのは当然これからだと思うのですけれども、一番、私が思っているのは、都との交渉が結構、大変なのかと思っているのですけれども、そのことだけご答弁いただければと思います。","respondent":"今井保育教育運営担当課長","answer":"なので、こういった施設については、当然その調整に時間がかかるといった背景もありますので、後回しにするなどという話ではなく、長期的な目線を持って、改築に向けて準備を進めていくというような姿勢で取り組んでまいりたいと考えております。","voiceIndex":166,"id":"exchange-058"},{"speaker":"吉田副委員長","kind":"質問","question":"１つ、私がぱっと思いつくのは、やはり、このままほっておくと、もしかすると虐待の方向に行ってしまうかもしれない。そういう意味で、やはり区立保育園をだんだん減らしていくという方向はどうなのか。今後の保育の重要性、それこそ子育て支援だけではなく少子化対策にもつながるような保育園の運営というのはあるのではないかと思うのですが、その点についてはどのようにお考えか伺いたいと思います。","respondent":"今井保育教育運営担当課長","answer":"現状で、やはり保育ニーズとして減少の見込みがあるといった背景に基づきまして、また、今後、保育ニーズが多様化してまいりまして、在宅子育て支援等の強化も求められていく中では、まずそれを実施するための人的・施設的な余裕がある必要があると考えております。","voiceIndex":170,"id":"exchange-059"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"そういう議論をどんどん深めていっていただきたいと思うのですけれども、その中でもやはり人的な資源を確保するためには、先ほどもどなたか、ほかの委員から発言があったと思うのですけれども、やはり保育士の処遇の改善は、いろいろな場面で度々求めておりますので、特に私立園の保育士の処遇改善。なので、その辺のことも、区としてもぜひ国に対しても求めていただきたい。","respondent":"石井保育支援課長","answer":"現在、保育士の賃金等が改善されているかどうかということに関しては、国も相当程度、問題意識を持っており、例えば東京都がキャリアアップ補助金に対する財務情報公表様式というものを公開させてありますけれども。","voiceIndex":172,"id":"exchange-060"},{"speaker":"吉田副委員長","kind":"質問・要望","question":"なので、そういうことも含めて、ぜひ品川区では、そういうものがあったとしても、より分かりやすい公表の仕方というのも検討していただきたいと思います。処遇改善が事業者に行ってしまうというケースは、保育士の手当だけではなく、ほかのところでも見られますので、品川区ではぜひそのようなことがないように、保育の場面ではお願いしたいと思います。これは要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":174,"id":"exchange-061"}]},{"id":"topic-07","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"いつも文教委員会で体罰について報告していただくのですけれども、詳細はそのときで全然構わないのですけれども、品川区でも体罰等、東京都教育委員会が認定した、あるいは体罰に至らないまでもというものがあったのかどうかだけお願いします。","respondent":"中谷指導課長","answer":"今の体罰のご報告の件なのですけれども、先日、ご指摘いただいたとおり東京都教育委員会からの通知がございまして、これを受けまして品川区としましては、次回の文教委員会で詳細を含めてご報告させていただければと考えていますので、よろしくお願いいたします。","voiceIndex":190,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5116#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":65724,"voices":192}},{"id":"r05-20231128-5","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"総務委員会","time":"午前１０時０８分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案","agenda":"の給与等に関する条例の一部を改正する条例、(5)第９９号議案、職員の給与に関する条例の一部を改正する条例および(6)第１００号議案","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"一括でよろしいのですね。品川区一般職員の給与、また会計年度任用職員の給与も今回出るということですが、本来なら区民生活、それから区内の中小零細企業においては経営がまだ厳しい、一般の区民においても物価高騰で同様にやはり生活が厳しい中で、区の職員にも我慢をしてほしいところですが、これだけ物価が高騰した中で、今１世帯当たり年間１０万円以上の負担をされている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"澤田委員","kind":"質問・要望","question":"そもそも職員の給与の考えというのが、昭和３９年から民間の平均を取っていて、毎年４月にその平均を取って決めてきていて、長年職員の皆さんも特別職も下がってきたと理解しております。民間の給与と連動して、職員の給与が変わってきた中で、それに対して今回だけ連動しないということではなく、職員の皆さんと同じように、特別職も改正していくというのがいいのではないか、進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-002"},{"speaker":"塚本副委員長","kind":"意見","question":"賛成します。考え方としては、民間と合わせて上がるときは上がる、下がるときは下がる。そういうのがこの給与の設定としては合理的な、我々も含めて基本的にはそれが一番合理的であると思っていますので、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"１個ずつですか。すみません。気が焦っていました。第９５号議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-004"},{"speaker":"松本委員","kind":"意見","question":"第９５号議案については反対です。そこを上げるには相当な苦労がある。そういう中で、では我々議員がどういう成果を出しているのかというところに関しては、なかなかこの品川区民の皆さんの生活を、今これだけ物価が上がっている中で楽にさせられているかといったら、そう簡単では、そう断言できるほどではないと私どもは考えております。したがいまして、第９５号議案に関しては反対をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"提案","question":"私は第９５号議案、そのほか全ての議案に賛成しますが、考え方だけ言わせてください。１回目は下げませんでした。それをもうずっと受けてきた。それ以外でやるのであればほかのところで議論をするべきであって、それを寄附だ、どうのこうのとかやっているほうが私はおかしいと思っているので、私はこの件については必ずそのとおり、今提案があったとおりやるべきだと思っているので、第９５号議案は賛成。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"すみません、私もちょっと一言言わせていただきます。品川区内で多くの方たちが住まわれて、年金暮らしの方、それから本当に中小企業でボーナスも出ない、ボーナスが出てもわずか、給与は上がらない、そういう状況を考えたときに、やはり選挙で選ばれた方たちは、私は自重すべきだと思います。今回の第９６号議案については反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"先ほども申し上げましたけれども、全国自治体において月額報酬から日額報酬に変わっている状況を踏まえたら、一部の行政委員がやはりこのように増額されるというのは私は間違っていると思います。逆に減額するべきであると思います。ですから、第９７号議案は反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"反対です。ここだけは少し別のところなので。会計年度任用職員に関しましては、今回ほかのところと同じような増額部分だけではなくて、新たに手当の部分を他の職員の方たちと合わせるというところが令和６年度に入ってからの勤勉手当ですね。こちらについては同一労働同一賃金の観点から賛成したいところですが、期末手当の増額分については他の部分と同様のところがありますので、反対とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-009"}]},{"id":"topic-02","title":"第７６号議案、令和５年度品川区一般会計補正予算","agenda":"第７６号議案、令和５年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"確認","question":"１７ページの就学支援費のほうですが、確認ですが、学校給食費無償化事業で、これは国立・私立特別支援学校ということは学校全体に支援をするのか、それとも品川区に住民票がある子どもたちだけに支援するのですか。一応教えてください。","respondent":"遠藤財政課長","answer":"こちらは品川区に在住されている方を対象にして、という形になります。","voiceIndex":61,"id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"１５ページの保健衛生助成金で、公衆浴場物価高騰対策支援金と、中小企業活性化事業費で、運送事業者等燃料費高騰対策支援金、これが計上されています。ならば、公衆浴場だけではなく、また運送事業者だけではなく、他の産業・事業所においてもやはり平等・公平に支援をするべきだと私は思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":63,"id":"exchange-011"}]},{"id":"topic-03","title":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","agenda":"地方税の賦課及び徴収事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"そこにカメラがついているのです。そして、何時何分に例えばそこを通ったとか、普段は別に監視する必要はないですけれども、何かあったときにある方が例えば夜の９時に来てパソコンをいじっていて、その情報が漏れたとか、そういうときに目で見える、そういう情報管理も必要ではないかと思うのですが、すみません、庁内にはそういうカメラみたいなものは設置されているのですか。教えてください。","respondent":"提坂税務課長、佐藤（聡）経理課長","answer":"税務課の立場としては、全庁を把握しているものではございませんが、税務課ですとか戸籍住民課、国保医療年金課、区民の多くの皆様と接する事務室では設置してございませんが。生活福祉課ですとか一部の課においては、窓口の安全ですとか、そういったところの管理のためということで、個別につけている状況です。","voiceIndex":76,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"一部大手などは、やはりこういう相当な個人情報をお持ちでやり取りしているという、情報開示したりいろいろやっていますので、そういうことも今後必要になるのではないかと。その人を見るというのではなくて、フロア全体で誰が最終的にパソコンをいじっていたのかということも、あるときには一つの調べることができる要素の一つにもなると思いますので、ぜひ私は検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"すみません、ちょっと不勉強なので教えていただきたいのですが、特定個人情報保護評価は、品川区が発生させるリスクを分析して、そのリスクを軽減する適切な措置を講ずるというのだけれども、これを見ていくと、この根拠法令を見たときに平成２５年とか２６年で、何で今頃なのかと思った私がいます。","respondent":"提坂税務課長","answer":"これまでにも特定個人情報保護評価というのは少なくとも５年に一回実施しておりまして、その後、システム改修ですとかシステムに重要な変更を行う際に実施することになっておりまして、税のほうも前回４年前に行っております。","voiceIndex":80,"id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"今のはそのとおりだと思って伺っていました。そうではなくて、システムはもともとやっていたのを、４年に一回だとかそういうのでやり替えるから、改めて報告しているというだけなのか。ということは４年前にもやっているのだけれども、私もそれは不勉強で、その時ちゃんとやっているのだからという理解なのかどうなのかというところだけ、教えてください。","respondent":"提坂税務課長","answer":"資料の２、評価書の内容ということでＩからVIまで記載されておりますが、これは今回新たに記載したものということではございませんで、もともと記載している部分です。","voiceIndex":82,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2284#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":16154,"voices":90}},{"id":"r05-20231128-10","meetingId":"r05-cm11","date":"2023年11月28日","dateIso":"2023-11-28","committee":"議会運営委員会","time":"午前 ９時３０分～午前 ９時３６分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2023-01-01&TermEnd=2023-12-31"}],"sourceMeta":{"pages":0,"characters":2891,"voices":16}}]);
